import{_ as e,o as r,c as h,at as t}from"./chunks/framework.DftHzyL-.js";const u=JSON.parse('{"title":"风谈六步骤.pdf","description":"","frontmatter":{"title":"风谈六步骤.pdf","editLink":false,"outline":false,"permalink":"/content-for-search/pdf-content/书/风谈六步骤"},"headers":[],"relativePath":"content-for-search/pdf-content/书/风谈六步骤.md","filePath":"content-for-search/pdf-content/书/风谈六步骤.md","lastUpdated":null}'),o={name:"content-for-search/pdf-content/书/风谈六步骤.md"};function p(i,a,l,n,g,d){return r(),h("div",null,[...a[0]||(a[0]=[t('<h1 id="风谈六步骤-pdf" tabindex="-1">风谈六步骤.pdf <a class="header-anchor" href="#风谈六步骤-pdf" aria-label="Permalink to &quot;风谈六步骤.pdf&quot;">​</a></h1><blockquote><p>此页面由PDF自动索引生成，仅用于搜索功能，查看网站中相应的PDF页面。</p></blockquote><hr><hr><h2 id="page-1" tabindex="-1">第 1 页 <a class="header-anchor" href="#page-1" aria-label="Permalink to &quot;第 1 页 {#page-1}&quot;">​</a></h2><p>free go 向自由进发 风 谈 六 步 骤 分享人/风 编辑排版/一曼 2021.8.17</p><hr><h2 id="page-2" tabindex="-1">第 2 页 <a class="header-anchor" href="#page-2" aria-label="Permalink to &quot;第 2 页 {#page-2}&quot;">​</a></h2><hr><h2 id="page-3" tabindex="-1">第 3 页 <a class="header-anchor" href="#page-3" aria-label="Permalink to &quot;第 3 页 {#page-3}&quot;">​</a></h2><p>感谢圣多纳释放法创始人 莱斯特·利文森先生 只要你想要帮助，我绝不会离开你。 现在“真正的我（real me)”把你当做“真正的你(real you)”来看待。当我不在这儿，不在这具肉身里和你在一起时， 是真我在帮助你。 任何时候，你请求真正的我时，你会发现真正的我就在那儿。 所发生的就是你向上提升了，这样你就能自己得到答案,你必 须去得到它。 ——莱斯特·利文森 （1909.7.19—1994.1.18）</p><hr><h2 id="page-4" tabindex="-1">第 4 页 <a class="header-anchor" href="#page-4" aria-label="Permalink to &quot;第 4 页 {#page-4}&quot;">​</a></h2><hr><h2 id="page-5" tabindex="-1">第 5 页 <a class="header-anchor" href="#page-5" aria-label="Permalink to &quot;第 5 页 {#page-5}&quot;">​</a></h2><p>感谢坦诚、耐心、详尽分享释放法的 风 你带给我无限的启发和动力 是我前往自由之路最好的榜样 感谢你把原始释放法传播开来 衷心感谢你的无私分享与指导 感谢讲授及传播原始释放法的老师们 感谢“原始圣多纳释放法”公众号的运营者： 我是无限 感谢“通往自由的捷径”公众号的运营者： 天成 感谢其他所有分享释放法的自媒体 感谢92年原始释放法教学视频的字幕翻译组： 视频1、4、5、7、8字幕&amp;翻译： 童 视频3字幕&amp;翻译： Fay 视频2、6翻译： 晖-Lucky 你们为原始释放法的传播做出了巨大的贡献 感谢所有无私翻译制做学习资料的网友 感谢践行并推广释放法的网友 感谢所有一路指引和陪伴我们学习的人们 谢谢你们</p><hr><h2 id="page-6" tabindex="-1">第 6 页 <a class="header-anchor" href="#page-6" aria-label="Permalink to &quot;第 6 页 {#page-6}&quot;">​</a></h2><p>6 编 者 记 我在2019年10月中旬左右开始接触灵性，2020年3 月就遇到了释放法。虽然第一次尝试就感受到用它释放情 绪既简单又快速，但由于当时未接触到原始释放法，从拉 里和海尔的书中在文字层面上学习释放感觉弯弯绕绕，不 明重点，这让我中途放弃了释放，一直是用清理的方法。 虽然暂时停止了释放，但其实心里还是一直惦记着释 放法，也知道它才是更究竟的方法。 后来风出现了，如他的名字“风”一样，他本人也像 一股吹走释放圈迷惑沉闷的和煦春风，为在释放道路上摸 索的伙伴们带来了清晰的指引和明亮的希望。 他不但明晰了释放的操作要点，解开了我对于释放的 种种疑惑，同时也让我看到了走向终点最需要抓住的核心 关键——贯彻六步骤。 每当网友询问关于释放的问题时，风总是非常耐心详 尽地回答。由于他拥有强大的记忆力，加上对莱斯特教导 的熟悉性，他总是依托和引用莱斯特曾经的讲解来回答问 题。尽管他在灵性方面涉猎颇广，但他很少引用其他方法 理论来突显自己，他为传播原始纯正的释放法做出了巨大 的贡献。</p><hr><h2 id="page-7" tabindex="-1">第 7 页 <a class="header-anchor" href="#page-7" aria-label="Permalink to &quot;第 7 页 {#page-7}&quot;">​</a></h2><p>7 他为人处事的态度，他的博学睿智，他对自由坚持不 懈的追求，无一不带给我启发与坚持实践释放的动力。 他践行“仅仅通过释放获得一切”的真实事例，也令 我在懈怠之时备受鼓舞。最终他通过持续释放到达终点， 让我第一次觉得“开悟”离我如此之近。 身体力行实践释放法并最终达到自由的风，是继莱斯 特之后让我再一次把注意力转向无限存在的那扇窗户。 可以说，是风的分享，拉我重新回到释放法，没有他 厘清方法，反复耐心地强调重点，我是难以走上正确释放 的道路的。 这也要感谢「原始圣多纳释放法」公众号的运营者“我 是无限”，是你严格无私的分享才让更多人能够接触到详 尽原始的释放法资料，非常感谢你一直以来的付出。 正是你的严谨性，创建出一个更有利于学习释放法的 氛围，由此吸引到风入群分享，让原始释放法终于有机会 披露给对释放感兴趣的网友们。 此外还要特别感谢天成，他谨遵风希望免费传播释放 法的教导，无私地将风的聊天记录分享给大家。他是一个 非常擅于提问的人，没有他做一个优秀的“提问者”，可 能很多关于释放的要点与提醒我们也无从知晓。</p><hr><h2 id="page-8" tabindex="-1">第 8 页 <a class="header-anchor" href="#page-8" aria-label="Permalink to &quot;第 8 页 {#page-8}&quot;">​</a></h2><p>8 在探索释放的道路上，非常感谢他给予我的帮助、提 醒与鼓励，感谢他的公众号“通往自由的捷径”。 风在2020年9月到2021年3月这半年间对原始释放 法的讲解分享，无疑是一笔学习释放的宝藏。 一开始我是出于自助的态度去整理，后来以六步骤为 主线，挑选了部分内容，将如珍珠般散落在各处的分享串 联起来，集结成册，方便自己和大家既对释放有一个整体 的了解，也能时常提醒自己贯彻六步骤。 希望这本《风谈六步骤》能指引你学会使用六步骤， 帮助你更好地自助，贯彻六步骤直到到达终点。 但任何资料性的东西最终都需要放下，不需要在头脑 中累积内容来发展心智。心智是障碍，学习需要亲身体验。 如风所说：“释放是一个人最自然的能力，但足够多 的心智内容，会障碍你的这个能力。忘记释放，其实并非 是你学的不够多，并非是你累积的知识不够多，而是因为 你累积的太多了。当你积累的很多的时候，你就在发展你 的心智，这会遮蔽/削弱你释放的能力。” 所以这本书最后也需要放下，仅需回到六步骤，保持 简单去释放。</p><hr><h2 id="page-9" tabindex="-1">第 9 页 <a class="header-anchor" href="#page-9" aria-label="Permalink to &quot;第 9 页 {#page-9}&quot;">​</a></h2><p>9 看书、谈论、分享等等都无法代替真实去释放，唯有 去持续释放才是真前进。 莱斯特曾说，释放法是当今世上唯一能达到终极自由 的简单方法，在我了解其他灵性方法和实践释放的过程当 中，确实亲身感受到这一点。 在持续释放的状态之中，我感受到了六步骤的环环相扣， 它的确是一份引导自己走在正确释放之路上的清晰地图。 欢迎你走上释放之旅，重视六步骤，不断去释放，持 续释放到终极自由,祝你成功。 要表达对莱斯特和风的敬爱和感恩，唯有贯彻实践他 们所教授的，走向他们一直所指的方向，走向终点，获得 自由。 最后以莱斯特的话作为结尾：“我们所走的这条路是 从这里开始，直到完全的自由。这是我要强调的第一点。 第二点是，我们此生就能达到！对很多有同样目标的人而 言，通常需要很多世才能达到。但是，我们今生就能做到。” 祝福所有在路上的伙伴，加油。 一曼 2021年9月20日 中秋节</p><hr><h2 id="page-10" tabindex="-1">第 10 页 <a class="header-anchor" href="#page-10" aria-label="Permalink to &quot;第 10 页 {#page-10}&quot;">​</a></h2><p>10 问: 释放法是专门为这个时代准备的吗？ 风: 是的。尤迦南达在莱斯特完全觉醒之后就选择离开 了，也正式宣告guru的时代的终结。 莱斯特只能帮助到小众人，在这一时代也只有极少数的 人会觉醒。有这个方法的人都有机会。 这个时代会有很多假大师，但是在这个时代只有释放法 能够通向自由。因此宣称自己通过其他方式自由的，都是假 大师。 我指的是在1970年之后，在1970年之后觉醒的，除了 上一世已经觉醒的之外，只有释放法能做到了。 而一个通过其他方式已经觉醒的人，会和你推荐释放法， 不管他自己是用什么方法觉醒的，因为大师知道一切。 问: 拉玛那教导的终极方法，也做不到吗？ 风: 理论上终极问题是最快的，但是实际上这个星球目 前没有人可以用。 问: 尤迦南达教导的克利亚瑜伽呢？ 释放法是当今唯一一个简单高效达到自由的方法</p><hr><h2 id="page-11" tabindex="-1">第 11 页 <a class="header-anchor" href="#page-11" aria-label="Permalink to &quot;第 11 页 {#page-11}&quot;">​</a></h2><p>11 风: 不会在这一生自由。克利亚瑜伽的要求太高了，它 属于王瑜伽，是综合性的道路。 释放法是这个时代唯一简单易行的方法。 看上面一段视频，莱斯特其实和学生说过很多次， Sedona method是唯一一个现在有效的，大部分不知道 Sedona method的人会花很长很长时间到达自由。 问: 如果我们不去把它用到极致，那我们真的是全世界 最愚蠢的人。 风: 你没有理由不去用释放法，无论是走向觉醒还是获 得更好的世界，它都是最高效的。不仅高效，而且简单。 因为你们都会经历低谷，而经历低谷的时候，很容易放 弃。如果这时候有一个看上去有诱惑性的东西，你就会被吸 引过去。 所以我强调的是我所知道的一件事，目前这个时代，从 1970年开始，在这120年间，只有释放法能够走到终点。 放弃释放法，等于放弃这一世自由，不管你转去用其他 任何灵性方法。</p><hr><h2 id="page-12" tabindex="-1">第 12 页 <a class="header-anchor" href="#page-12" aria-label="Permalink to &quot;第 12 页 {#page-12}&quot;">​</a></h2><p>12 关于92年原始释放法课程视频的说明 【2020.10.12】 风：这（指释放方法）是1992年sedona institute 视频里所用的，莱斯特所创立的释放法机构的原始流程。 后来海尔和拉里都成立了自己的机构，因为不能教的 一样，所以都对这个方法有所删改，但是确实是原始流程 最为管用。 原先释放法课程分四天，第一个周末两天学释放情绪， 下一个周末两天学释放欲望。所以释放情绪的阶段没有必 要滞留太久，只要熟悉了就可以尝试去释放欲望。 释放法不需要看书，视频里面也基本没有理论讲解， 只是不断引导学生做释放，你跟着做自然就会了，会惊叹 于这个方法的简洁和有效。 用释放案例来学习是最简单的方法。要学习流程是怎 样操作的，最好就是自己体验。看看别人是怎么操作的， 自己跟着操作，或者让别人引导你，很快就能学会。所以 你会看到sedona institute教理论的部分很少，而实践 的部分完全就是实例引导。整八个视频就是不断地给你们 看别人是怎么释放的。</p><hr><h2 id="page-13" tabindex="-1">第 13 页 <a class="header-anchor" href="#page-13" aria-label="Permalink to &quot;第 13 页 {#page-13}&quot;">​</a></h2><p>13 【2020.9.21】 释放法起初确实很简单： identify the feeling.Feel the feeling. Could you let go? Would you? When? 前面那几个（ 指前四个视频 ）都是workbook（ 练习本 ） 的用法，包括设定目标之类的。第五个（视频）才开始释 放欲望。不设定目标，你会把你的欲望推到潜意识深处。 设定目标才能让它浮现，这点和很多人理解的不一样。 一个表面的“无欲”并不是真正的无欲，它是欲望被 压抑的结果。well，你可以从情绪表上找到这个情绪，情 绪表的基本用法其实很简单。 前面（ 指前四个视频 ）其实都是对于新人来说的，熟 悉了释放之后，还是都要上溯到想要控制和想要被认同释 放，课程也是这样说的。 按我的理解，前面的课程设置其实是让你更加in touch with（ 接触到 ）情绪，因为一般人其实太容易忽略 自己的情绪，压抑的本能太强大，所以通过好几种方式来 让你去注意到你的情绪。</p><hr><h2 id="page-14" tabindex="-1">第 14 页 <a class="header-anchor" href="#page-14" aria-label="Permalink to &quot;第 14 页 {#page-14}&quot;">​</a></h2><p>14 比如说第一课后面海尔还讲了一个例子，说你有某些 特别的癖好，比如喜欢吃东西，比如说抽烟，比如说打游戏， 这些背后都有情绪。在你被这些习惯推动前，先释放。 第二个视频讲suppressed feeling，以及success， 让你去有意识回忆自己什么时候压抑了情绪，这是在允许 潜意识浮现。为什么他们要讨论success，因为人在“成功” 这个主题上压抑了很多情绪。 再下一个视频讲的应该是目标，目标则更让你无法回 避情绪了。我记得有很多人说自己无欲无求，但是问他： “你 没有什么想实现的吗？没有什么想要的吗？没有什么想改 变的吗？” 他一想，好像有不少呢。再深入一看，原来那背后都 是情绪，所以目标的重要性在于勾出那些你压抑住的情绪。 这一点，是莱斯特在音频里讲的，所以前四个视频都 是在反复让你接触角落里的情绪，第五个视频才真正让方 法深入起来，去看你的情绪背后的“想要”。</p><hr><h2 id="page-15" tabindex="-1">第 15 页 <a class="header-anchor" href="#page-15" aria-label="Permalink to &quot;第 15 页 {#page-15}&quot;">​</a></h2><p>15 （更多释放法资料可在“原始圣多纳释放法”公众号上查看） 一曼注：各位伙伴，如果你正在学习释放法，完全按照免 费公开的92年原始释放法教学视频以及莱斯特和风对释放的讲 解走即可，完全不需要去报其他任何线上或线下的收费课程、 工作坊。 目前市面上开设释放法收费课程的老师大部分加入了很多 自己心智上的理解，改变了原本简洁、直接、迅速的释放法， 所以请大家谨慎。</p><hr><h2 id="page-16" tabindex="-1">第 16 页 <a class="header-anchor" href="#page-16" aria-label="Permalink to &quot;第 16 页 {#page-16}&quot;">​</a></h2><p>16</p><hr><h2 id="page-17" tabindex="-1">第 17 页 <a class="header-anchor" href="#page-17" aria-label="Permalink to &quot;第 17 页 {#page-17}&quot;">​</a></h2><p>17</p><hr><h2 id="page-18" tabindex="-1">第 18 页 <a class="header-anchor" href="#page-18" aria-label="Permalink to &quot;第 18 页 {#page-18}&quot;">​</a></h2><p>18 2020.12.20</p><hr><h2 id="page-19" tabindex="-1">第 19 页 <a class="header-anchor" href="#page-19" aria-label="Permalink to &quot;第 19 页 {#page-19}&quot;">​</a></h2><p>19</p><hr><h2 id="page-20" tabindex="-1">第 20 页 <a class="header-anchor" href="#page-20" aria-label="Permalink to &quot;第 20 页 {#page-20}&quot;">​</a></h2><p>20</p><hr><h2 id="page-21" tabindex="-1">第 21 页 <a class="header-anchor" href="#page-21" aria-label="Permalink to &quot;第 21 页 {#page-21}&quot;">​</a></h2><p>21 自由不需要六步骤以外的步骤 ——风 2020.10.23</p><hr><h2 id="page-22" tabindex="-1">第 22 页 <a class="header-anchor" href="#page-22" aria-label="Permalink to &quot;第 22 页 {#page-22}&quot;">​</a></h2><p>22 第一步:你必须想要自由超过想要世界。 你必须想要自由超过想要被认同和想要控制 想要被认同和想要控制=世界 第二步:做出自由的决定。 第三步:所有感受都来自想要被认同和想要控制，它们都 是生存程序。释放它们。 第四步:持续释放。 第五步:当你卡住时，释放对卡住的感受的想要改变。 第六步:每次你释放，你都更愉悦、轻松、脱离限制。随 着释放，你会越来越愉悦、轻松、脱离限制。 莱斯特： There is no stops in six steps. (六步骤里没有停止。) 注：因海尔和拉里后来都对六步骤在表达上有所修改，无法确定六 步骤最初的原始版本。此六步骤版本是风摘取莱斯特在进阶课程 the way中谈及释放时所讲的零散原话翻译出来的版本，供参考。 The Six Steps to Freedom 自由六步骤</p><hr><h2 id="page-23" tabindex="-1">第 23 页 <a class="header-anchor" href="#page-23" aria-label="Permalink to &quot;第 23 页 {#page-23}&quot;">​</a></h2><p>23 2020.12.2</p><hr><h2 id="page-24" tabindex="-1">第 24 页 <a class="header-anchor" href="#page-24" aria-label="Permalink to &quot;第 24 页 {#page-24}&quot;">​</a></h2><p>24 The six steps 1) Want freedom more than anything else. . 2) Decide you can do the method and be free. 3) See all your feelings as expressions of three basic wants: the want of approval, control, and survival. Release the want of approval, the want of control, and lastly the fear of death. 4) Release continuously. 5) If you are stuck, let go of wanting to change the stuckness. 6) Release more and more and become happier and lighter, until you move beyond happiness into imperturbability and freedom.</p><hr><h2 id="page-25" tabindex="-1">第 25 页 <a class="header-anchor" href="#page-25" aria-label="Permalink to &quot;第 25 页 {#page-25}&quot;">​</a></h2><p>25 六步骤 1) 想要自由超过其他的一切。 2）决定你能通过释放获得自由。 3）你所有的感受都是三种基本欲望（想要被认同、想要控制、 想要生存）的表现形式，释放想要被认同、想要控制，直到 最后释放对死亡的恐惧。 4）持续不断地释放。 5）如果感觉卡住，释放“想要改变”卡住的情况。 6）随着越来越多地释放，变得更加快乐和轻松，直到你超 越幸福状态，进入波澜不惊和自由的境界。 一曼注：此六步骤是在网上找到的可能接近原始六步骤的版本， 仅供大家参考理解，实操还是以风翻译的版本为主。</p><hr><h2 id="page-26" tabindex="-1">第 26 页 <a class="header-anchor" href="#page-26" aria-label="Permalink to &quot;第 26 页 {#page-26}&quot;">​</a></h2><p>26 Again, the Six Steps are a key to everything.</p><hr><h2 id="page-27" tabindex="-1">第 27 页 <a class="header-anchor" href="#page-27" aria-label="Permalink to &quot;第 27 页 {#page-27}&quot;">​</a></h2><p>27 再说一次，六步骤是一切的关键。</p><hr><h2 id="page-28" tabindex="-1">第 28 页 <a class="header-anchor" href="#page-28" aria-label="Permalink to &quot;第 28 页 {#page-28}&quot;">​</a></h2><p>28</p><hr><h2 id="page-29" tabindex="-1">第 29 页 <a class="header-anchor" href="#page-29" aria-label="Permalink to &quot;第 29 页 {#page-29}&quot;">​</a></h2><p>29</p><hr><h2 id="page-30" tabindex="-1">第 30 页 <a class="header-anchor" href="#page-30" aria-label="Permalink to &quot;第 30 页 {#page-30}&quot;">​</a></h2><p>30</p><hr><h2 id="page-31" tabindex="-1">第 31 页 <a class="header-anchor" href="#page-31" aria-label="Permalink to &quot;第 31 页 {#page-31}&quot;">​</a></h2><p>31 2020.12.31</p><hr><h2 id="page-32" tabindex="-1">第 32 页 <a class="header-anchor" href="#page-32" aria-label="Permalink to &quot;第 32 页 {#page-32}&quot;">​</a></h2><p>32</p><hr><h2 id="page-33" tabindex="-1">第 33 页 <a class="header-anchor" href="#page-33" aria-label="Permalink to &quot;第 33 页 {#page-33}&quot;">​</a></h2><p>33 2021.1.11</p><hr><h2 id="page-34" tabindex="-1">第 34 页 <a class="header-anchor" href="#page-34" aria-label="Permalink to &quot;第 34 页 {#page-34}&quot;">​</a></h2><p>34</p><hr><h2 id="page-35" tabindex="-1">第 35 页 <a class="header-anchor" href="#page-35" aria-label="Permalink to &quot;第 35 页 {#page-35}&quot;">​</a></h2><p>35 ——莱斯特 《终极自由之路》 1.“我不能”意味着我不去做。 2.“我做不到”，仅仅是这个想法阻止了你去做。 3.那些认为自己做不到的人，实际上是不想做。 4.只要你能赶紧去做，它就会发生。 5.愿望和企图都没用，你必须行动！ 6.不要试试看了，直接去做！</p><hr><h2 id="page-36" tabindex="-1">第 36 页 <a class="header-anchor" href="#page-36" aria-label="Permalink to &quot;第 36 页 {#page-36}&quot;">​</a></h2><p>36 2020.12.7</p><hr><h2 id="page-37" tabindex="-1">第 37 页 <a class="header-anchor" href="#page-37" aria-label="Permalink to &quot;第 37 页 {#page-37}&quot;">​</a></h2><p>37 2020.12.29</p><hr><h2 id="page-38" tabindex="-1">第 38 页 <a class="header-anchor" href="#page-38" aria-label="Permalink to &quot;第 38 页 {#page-38}&quot;">​</a></h2><p>38</p><hr><h2 id="page-39" tabindex="-1">第 39 页 <a class="header-anchor" href="#page-39" aria-label="Permalink to &quot;第 39 页 {#page-39}&quot;">​</a></h2><p>39</p><hr><h2 id="page-40" tabindex="-1">第 40 页 <a class="header-anchor" href="#page-40" aria-label="Permalink to &quot;第 40 页 {#page-40}&quot;">​</a></h2><p>40</p><hr><h2 id="page-41" tabindex="-1">第 41 页 <a class="header-anchor" href="#page-41" aria-label="Permalink to &quot;第 41 页 {#page-41}&quot;">​</a></h2><p>41</p><hr><h2 id="page-42" tabindex="-1">第 42 页 <a class="header-anchor" href="#page-42" aria-label="Permalink to &quot;第 42 页 {#page-42}&quot;">​</a></h2><p>42 2021.3.11</p><hr><h2 id="page-43" tabindex="-1">第 43 页 <a class="header-anchor" href="#page-43" aria-label="Permalink to &quot;第 43 页 {#page-43}&quot;">​</a></h2><p>43</p><hr><h2 id="page-44" tabindex="-1">第 44 页 <a class="header-anchor" href="#page-44" aria-label="Permalink to &quot;第 44 页 {#page-44}&quot;">​</a></h2><p>44 2020.10.24</p><hr><h2 id="page-45" tabindex="-1">第 45 页 <a class="header-anchor" href="#page-45" aria-label="Permalink to &quot;第 45 页 {#page-45}&quot;">​</a></h2><p>45</p><hr><h2 id="page-46" tabindex="-1">第 46 页 <a class="header-anchor" href="#page-46" aria-label="Permalink to &quot;第 46 页 {#page-46}&quot;">​</a></h2><p>46</p><hr><h2 id="page-47" tabindex="-1">第 47 页 <a class="header-anchor" href="#page-47" aria-label="Permalink to &quot;第 47 页 {#page-47}&quot;">​</a></h2><p>47</p><hr><h2 id="page-48" tabindex="-1">第 48 页 <a class="header-anchor" href="#page-48" aria-label="Permalink to &quot;第 48 页 {#page-48}&quot;">​</a></h2><p>48</p><hr><h2 id="page-49" tabindex="-1">第 49 页 <a class="header-anchor" href="#page-49" aria-label="Permalink to &quot;第 49 页 {#page-49}&quot;">​</a></h2><p>49</p><hr><h2 id="page-50" tabindex="-1">第 50 页 <a class="header-anchor" href="#page-50" aria-label="Permalink to &quot;第 50 页 {#page-50}&quot;">​</a></h2><p>50 2020.12.23</p><hr><h2 id="page-51" tabindex="-1">第 51 页 <a class="header-anchor" href="#page-51" aria-label="Permalink to &quot;第 51 页 {#page-51}&quot;">​</a></h2><p>51</p><hr><h2 id="page-52" tabindex="-1">第 52 页 <a class="header-anchor" href="#page-52" aria-label="Permalink to &quot;第 52 页 {#page-52}&quot;">​</a></h2><p>52</p><hr><h2 id="page-53" tabindex="-1">第 53 页 <a class="header-anchor" href="#page-53" aria-label="Permalink to &quot;第 53 页 {#page-53}&quot;">​</a></h2><p>53 ——风 2020.3.13 释放所有感受 你的心智安静 你就到了</p><hr><h2 id="page-54" tabindex="-1">第 54 页 <a class="header-anchor" href="#page-54" aria-label="Permalink to &quot;第 54 页 {#page-54}&quot;">​</a></h2><p>54</p><hr><h2 id="page-55" tabindex="-1">第 55 页 <a class="header-anchor" href="#page-55" aria-label="Permalink to &quot;第 55 页 {#page-55}&quot;">​</a></h2><p>55</p><hr><h2 id="page-56" tabindex="-1">第 56 页 <a class="header-anchor" href="#page-56" aria-label="Permalink to &quot;第 56 页 {#page-56}&quot;">​</a></h2><p>56</p><hr><h2 id="page-57" tabindex="-1">第 57 页 <a class="header-anchor" href="#page-57" aria-label="Permalink to &quot;第 57 页 {#page-57}&quot;">​</a></h2><p>57 莱斯特的音频keep it simple（讲到），他 察觉到了想要认同，想要控制和想要安全，只是他 第一个月只察觉到了想要认同，第二个月只察觉到 了想要控制，第三个月才察觉到对死亡的恐惧。 所以他才说，如果他当时有六步骤，他会更快 达到终点，&quot;你们现在有六步骤，所以你们应该比 我更快&quot;。 如果你去做，就很简单。如果你不做，就不可能。 简单，或者不可能（simple，or impossible）。 只需要几周，最多几个月，自由。 ——风 2020.10.23</p><hr><h2 id="page-58" tabindex="-1">第 58 页 <a class="header-anchor" href="#page-58" aria-label="Permalink to &quot;第 58 页 {#page-58}&quot;">​</a></h2><p>58</p><hr><h2 id="page-59" tabindex="-1">第 59 页 <a class="header-anchor" href="#page-59" aria-label="Permalink to &quot;第 59 页 {#page-59}&quot;">​</a></h2><p>59</p><hr><h2 id="page-60" tabindex="-1">第 60 页 <a class="header-anchor" href="#page-60" aria-label="Permalink to &quot;第 60 页 {#page-60}&quot;">​</a></h2><p>60 你只需要一个星期贯彻六步骤，来扭转过去强 烈的习惯，释放就能像飙车一样向前进，重点是符 合流程，贯彻六步骤，其他的我也没有任何要添加 的了。 莱斯特所画出的地图路线清晰，只要继续走就行。 我记得在释放的第一个星期，每一次释放，会 有巨大的能量涌出。 到后来，不仅不需要睡觉，每天也只需要一顿 饭。在第二个星期，已经不需要进食了，甚至需要 每天去天桥上跑一圈来消耗掉这些不断涌出的能 量，我是到最近几天才重新进了些食。 ——风 2020.10.23</p><hr><h2 id="page-61" tabindex="-1">第 61 页 <a class="header-anchor" href="#page-61" aria-label="Permalink to &quot;第 61 页 {#page-61}&quot;">​</a></h2><p>61 在第二个星期的时候，感受就会不断浮现出来， 然后离开，像波浪一样。 但是当我停下来时，瞥一眼六步骤，立即就会 知道自己哪一步有问题，于是释放就又立即进行了。 流程并没有改变，只是它变得更直接了，操作 更少了。 我感到自己一直在六步骤上，而这六步骤形成 一个巨大的推动力，让释放持续下去。 领悟频繁发生，这时候你会被它们带着走，但 只要继续提醒自己六步骤，就会继续释放，达到更 高的高峰。 ——风 2020.10.23</p><hr><h2 id="page-62" tabindex="-1">第 62 页 <a class="header-anchor" href="#page-62" aria-label="Permalink to &quot;第 62 页 {#page-62}&quot;">​</a></h2><p>62 对死亡的恐惧是两大欲望、一切情绪和思想的 起因。只要对死亡的恐惧没有彻底被释放，它就会 不断发展想要认同和控制。 因为人们没有那么想要自由，所以很难自由， 他们会在一个极度美好的状态就停下来。 但无论是美梦还是噩梦，你都还在梦中。如果 不超越梦境，你就会掉下来。 ——风 2020.10.23</p><hr><h2 id="page-63" tabindex="-1">第 63 页 <a class="header-anchor" href="#page-63" aria-label="Permalink to &quot;第 63 页 {#page-63}&quot;">​</a></h2><p>63 释放到后来，想要生存（对死亡的恐惧）会相 当明显，而这是我现在的主要释放对象，在它之上 的想要控制和认同，已经清理得非常稀少了。 说是“释放到后来”，是不是听上去像是十分 遥远的事？但其实也只是一两个星期的持续释放而 已。不要把它扩展到&quot;年&quot;的单位，因为它不需要。 这次只有一个目标，那就是自由。 ——风 2020.10.18</p><hr><h2 id="page-64" tabindex="-1">第 64 页 <a class="header-anchor" href="#page-64" aria-label="Permalink to &quot;第 64 页 {#page-64}&quot;">​</a></h2><p>64 2020.10.22</p><hr><h2 id="page-65" tabindex="-1">第 65 页 <a class="header-anchor" href="#page-65" aria-label="Permalink to &quot;第 65 页 {#page-65}&quot;">​</a></h2><p>65</p><hr><h2 id="page-66" tabindex="-1">第 66 页 <a class="header-anchor" href="#page-66" aria-label="Permalink to &quot;第 66 页 {#page-66}&quot;">​</a></h2><p>66</p><hr><h2 id="page-67" tabindex="-1">第 67 页 <a class="header-anchor" href="#page-67" aria-label="Permalink to &quot;第 67 页 {#page-67}&quot;">​</a></h2><p>67</p><hr><h2 id="page-68" tabindex="-1">第 68 页 <a class="header-anchor" href="#page-68" aria-label="Permalink to &quot;第 68 页 {#page-68}&quot;">​</a></h2><p>68 2021.3.16</p><hr><h2 id="page-69" tabindex="-1">第 69 页 <a class="header-anchor" href="#page-69" aria-label="Permalink to &quot;第 69 页 {#page-69}&quot;">​</a></h2><p>69</p><hr><h2 id="page-70" tabindex="-1">第 70 页 <a class="header-anchor" href="#page-70" aria-label="Permalink to &quot;第 70 页 {#page-70}&quot;">​</a></h2><p>70</p><hr><h2 id="page-71" tabindex="-1">第 71 页 <a class="header-anchor" href="#page-71" aria-label="Permalink to &quot;第 71 页 {#page-71}&quot;">​</a></h2><p>71</p><hr><h2 id="page-72" tabindex="-1">第 72 页 <a class="header-anchor" href="#page-72" aria-label="Permalink to &quot;第 72 页 {#page-72}&quot;">​</a></h2><p>72 问：如果一个人对此很真诚但却没有成功，上师会 向他伸出援手吗？ 莱斯特：一个开悟的上师能提供最大的帮助，但如 果你不自助，他也无法帮助你。 这是最重要的一点。如果你不帮助你自己，他就无 法帮助你。 当你努力自助时，他会加入你，帮助你实现你已 经准备就绪的觉醒。 （ When you try to help yourself, He joins you and helps you to a realization that you&#39;re ready for. ） 问：他会帮助我们？ 莱斯特：当你准备好觉醒时，他会帮助你实现这一 点。如果你敞开胸口，接受宇宙意识的注入，那是因为 你已经准备好了。 在所有的帮助中，上师的帮助是最大的，因为他是 过来人，他能引领你走上同样的道路。 ——《终极自由之路》第三十二章 开悟——放下无意识</p><hr><h2 id="page-73" tabindex="-1">第 73 页 <a class="header-anchor" href="#page-73" aria-label="Permalink to &quot;第 73 页 {#page-73}&quot;">​</a></h2><p>73 （*指注入实践释放法的灵感）</p><hr><h2 id="page-74" tabindex="-1">第 74 页 <a class="header-anchor" href="#page-74" aria-label="Permalink to &quot;第 74 页 {#page-74}&quot;">​</a></h2><p>74</p><hr><h2 id="page-75" tabindex="-1">第 75 页 <a class="header-anchor" href="#page-75" aria-label="Permalink to &quot;第 75 页 {#page-75}&quot;">​</a></h2><p>75</p><hr><h2 id="page-76" tabindex="-1">第 76 页 <a class="header-anchor" href="#page-76" aria-label="Permalink to &quot;第 76 页 {#page-76}&quot;">​</a></h2><p>76</p><hr><h2 id="page-77" tabindex="-1">第 77 页 <a class="header-anchor" href="#page-77" aria-label="Permalink to &quot;第 77 页 {#page-77}&quot;">​</a></h2><p>77</p><hr><h2 id="page-78" tabindex="-1">第 78 页 <a class="header-anchor" href="#page-78" aria-label="Permalink to &quot;第 78 页 {#page-78}&quot;">​</a></h2><p>78 图片来自英文版workbook第90页</p><hr><h2 id="page-79" tabindex="-1">第 79 页 <a class="header-anchor" href="#page-79" aria-label="Permalink to &quot;第 79 页 {#page-79}&quot;">​</a></h2><p>79 贯彻这三件事情，你将会迅速到达波澜不惊。 你到达波澜不惊 （自由）的门票 你现在已经拥有了你需要的一切去走完全程，到达 波澜不惊。（去往自由的门票在这里了。） 1. 仅仅释放这三个想要。 2. 让它持续不断并且立即释放。 允许想要被认同，想要控制和想要安全出现在你的 意识里并且立即让它离开。 3. 让它成为一个自己动手去做的工具。</p><hr><h2 id="page-80" tabindex="-1">第 80 页 <a class="header-anchor" href="#page-80" aria-label="Permalink to &quot;第 80 页 {#page-80}&quot;">​</a></h2><p>80 让我来说一个重点：不要恐惧自由。 莱斯特经常和他的学生讲的，不要恐惧自由。从莱 斯特的时代到现在，几乎每一个使用释放法却又不用到 极致的人都在恐惧自由。 你之所以不去释放，是你害怕失去你的感受，你害 怕会死，而实际上不会。 因此，莱斯特不断强调：你不会失去任何事，你只 会失去你的痛苦。 你去做那些事，你向外寻找“大师”们的帮助，你 应该知道你做的那些事看上去与自由相关，但实际上只 是拖延。 包括，整理关于我的资料，包括进行分享。当你逃 避向内看时，你会去整活，你会做一切事情——除了释放。 你的心智会告诉自己那对自由有益，或者对世界有 益，但是那就是让你停下释放而已。 只要你停下释放，不管你做什么，那都是反方向。 我不断强调这一点：谈论自由并不会让你自由，持续释 放才会。 你要自己提醒自己：在六步骤上吗？ ——风 2020.3.11</p><hr><h2 id="page-81" tabindex="-1">第 81 页 <a class="header-anchor" href="#page-81" aria-label="Permalink to &quot;第 81 页 {#page-81}&quot;">​</a></h2><p>81 释放了感受，你就不会有被强迫驱动的思想，你 可以自由地选择想你想要的，这会让你的世界就如你 想要的呈现出来。 世界只是一个呈现而已，只是一个显示屏。当你 想要改变画面时，砸显示屏是没有用的，只有释放有 帮助。 外面什么都没有，只有你的一堆思想。是你创造 了那个画面，没有例外。画面仅仅是思想而已，它不 是其他的任何东西 把感受清空，你就没有思想，你的心智彻底安静 下来。你会认出你是无限存在，然后再也不会失去这 份知道，你可以随意放入感受和思想，但不会再被它 运作，仅仅用于和人交流。 事实上只要你到达星光层时，你就看不到任何物 质，只能看到明亮炽热的光。当你到达三摩地，体验 到无限意识时，没有任何感受和思想。 自由之后你可以决定让身体走完它预设的，也可 以直接离开，那是你的选择，完全自由的选择。 ——风</p><hr><h2 id="page-82" tabindex="-1">第 82 页 <a class="header-anchor" href="#page-82" aria-label="Permalink to &quot;第 82 页 {#page-82}&quot;">​</a></h2><p>82 在这条路上你永远不会失去任何东西，你只会拥有 越来越多你真正想要的，直到你拥有全部。 除了我们给自己强加的绷带和伤痛，我们发现在灵 性道路上永远不会失去什么。 你放下限制，放下痛苦，但你永远不会失去任何有 价值的、美好的东西。 你知道，当你是无限时，你可以保有有限。你不会 失去任何东西。 我们担心要放弃我们的身体、放弃我们的家族，但 那不会发生。 那些开悟的人只是放下对身体和家族的执着，脱离 执着所带来的束缚感，取而代之的是完全的自由。 （自由后）你可以做任何事，但你不会消失。 你永远都不再受影响，因为你已经拥有了不受搅扰 的平静。 ——莱斯特</p><hr><h2 id="page-83" tabindex="-1">第 83 页 <a class="header-anchor" href="#page-83" aria-label="Permalink to &quot;第 83 页 {#page-83}&quot;">​</a></h2><p>83 问：我觉得你开悟比较容易，因为你之前没有太多 先入为主的东西。 莱斯特：是的。我很幸运，因为对这个主题知道太 多是种障碍。小我会用头脑的知识代替真实的体验。所 以我在那之前对此一无所知，真的非常非常地幸运。 问：人们都认为这很难，但你当时并不知道这很难。 莱斯特：是的。但是这样一说，能够帮你看到你需 要放下头脑知识所带来的障碍。我的经历可能激励你走 上这条路。 我说：不要相信任何事。从零开始。将你的知识建 立在体证的坚实基础上，一步步地去建立。每个人都必 须这么走过来。 问：你拿不走别人的经验？ 莱斯特：是的。你可以通过道听途说，但是唯一有 用的却是你亲自体验而来的。 以开车为例。如果我说我看过有关如何开车的书籍， 我已经知道怎么开车了。我真的知道怎么开车了吗？不， 除非我真的开过车，否则我不会知道怎么开车。这个道 理同样适用于这条道路，我们必须亲自去体验一切。</p><hr><h2 id="page-84" tabindex="-1">第 84 页 <a class="header-anchor" href="#page-84" aria-label="Permalink to &quot;第 84 页 {#page-84}&quot;">​</a></h2><p>84</p><hr><h2 id="page-85" tabindex="-1">第 85 页 <a class="header-anchor" href="#page-85" aria-label="Permalink to &quot;第 85 页 {#page-85}&quot;">​</a></h2><p>85</p><hr><h2 id="page-86" tabindex="-1">第 86 页 <a class="header-anchor" href="#page-86" aria-label="Permalink to &quot;第 86 页 {#page-86}&quot;">​</a></h2><p>86 关于六步骤 海尔在他的书中对六步骤有这样的介绍： “黄金六步是对圣多纳释放法的一个高度概括。莱斯特在 1974年创立了“黄金六步”这个概念来总结释放的整个过程。他 当时在和一小拨人一同搞圣多纳法的理论研究，一边训练那些人， 一边和他们一起把圣多纳释放法的教学系统化，顺带探究自学圣多 纳释放法的方法。 黄金六步这个概念是突然出现在他脑海中的，他当即把它写 在了手中那本书里夹的书签上。这个概念自打创立以来没有经过很 大的更改，经典而完美。 循着黄金六步来练习释放法是很有用的。许多人都把这六步 写在小纸条上夹在钱包里随身携带，甚至有人把它写在每天的任务 清单上。你还可以把它贴在桌前的墙上，或者设成屏保。总之，任 何能够随时随地提醒你释放的方式都行。 我还建议你集中练习释放法时，面前要有一份黄金六步，以 便在卡住的时候自我拯救一下。就像我说过的那样，这六步代表了 你做过或没做过的所有练习中最核心、最精要的部分。” 【2020.9.17】风：按莱斯特的说法，释放法所需要的一切知 识都在六步骤里，你只需要一条简单直接的道路，然后义无反顾地 走下去就行了。 所以，凡是鼓舞你继续释放的东西，你可以看看，凡是让你 停下释放的东西，你应该警惕。一旦停止释放，我就知道我错了， 至少不在道路上。让你停止进步的东西，包装得再神圣也没有用。</p><hr><h2 id="page-87" tabindex="-1">第 87 页 <a class="header-anchor" href="#page-87" aria-label="Permalink to &quot;第 87 页 {#page-87}&quot;">​</a></h2><p>87 我大致就是这个观点，简简单单地实操就好，真相会展现在 你面前的，不需要在此岸用语言修饰。只要你没体验到，转换无数 种描述方式，它也不是你的。 【2020.9.30】风：莱斯特喜欢用最简洁的语言来表达那些艰 涩的概念，所以我做翻译也尽量是往日常走，尽量不用那些大词。 我都找不到六步骤的原版，莱斯特没集中讲过六步骤，都是比较散 得提到，或者提一下six step，不过拼一下大概差不多，我试着 用他的原话重新译一个吧。 第一步: 你必须想要自由超过想要世界。（你必须想要自由 超过想要认同和控制。认同和控制=世界） 第二步: 做出自由的决定。 第三步: 所有感受都来自想要控制和想要被认同，它们都是 生存程序。释放它们。 第四步: 持续释放。 第五步:当你卡住时，释放那个对于卡住的感觉的想要改变。 第六步: 每次你释放，你都更愉悦、轻松、脱离限制，随着释放， 你会越来越愉悦、轻松、脱离限制。 好了，这是我摘取莱斯特先生零散的原话拼起来的六步骤， 供参考。 【2020.9.30】风：知识的部分，我们只需要知道六步骤和释 放流程，剩下的就是不断去操作和体验。如果在概念性的东西上有 歧见，先放到一边，去实际释放看看吧。</p><hr><h2 id="page-88" tabindex="-1">第 88 页 <a class="header-anchor" href="#page-88" aria-label="Permalink to &quot;第 88 页 {#page-88}&quot;">​</a></h2><p>88 走完全程唯一需要的就是六步骤 ——风 2021.1.11</p><hr><h2 id="page-89" tabindex="-1">第 89 页 <a class="header-anchor" href="#page-89" aria-label="Permalink to &quot;第 89 页 {#page-89}&quot;">​</a></h2><p>89 第一步: 你必须想要自由超过想要世界。 You must want freedom more than you want the world(approval and control). 你必须想要自由超过想要被认同和想要控制 想要被认同和想要控制=世界 风谈六步骤 Step 1 莱斯特：对，那是第一步，而且是方法的第一步，不 是吗？你必须想要自由超过你想要这个世界。 让我稍微改变一下说法，但这的确是它一开始的样子。 因为它看上去对人们没有实质意义，所以我们修改了它， 改成“你必须想要自由超过想要被认同和控制”，因为被 认同和控制等同于这个世界。但我认为更好的是用“你必 须想要自由超过想要世界”。 如果你做到了，你的行为接下来就会是：调转你朝着 世界的方向，专注回你自身，做那些从世界出离需要做的 事，允许你的无限存在仅仅是存在于此。所以第一步是你 必须想要自由超过想要这个世界。 ——摘自the way part1</p><hr><h2 id="page-90" tabindex="-1">第 90 页 <a class="header-anchor" href="#page-90" aria-label="Permalink to &quot;第 90 页 {#page-90}&quot;">​</a></h2><p>90 问：如何可以调转方向，真正在经验层面达成第一步呢？ 【2020.11.17】风：释放法里面的调转方向的方式是 通过不断确认你的 gain 。你通过释放获得好处，你就会想 释放。 比如你今天要考试，你以前有努力复习考成功的经验， 你就会努力复习。可是如果你通过释放考成功一次，你就 会去做释放。 你要确认自己所有的 gain 都是来自释放。 get everything by releasing only 。一开始获得好处 很重要，让 gain 支持你获得更高的 gain 。 简单地说，只有当你见到世界=痛苦、所有快乐都来 自内在时，你才会转向，才会达到第一步。只要你还认为 世界上有快乐，你就会停下来去追寻。 经常听音频和看视频的话，应该会见到莱斯特经常问 两个问题：一个是&quot;你们有没有体验过内在picture改变， 外面马上改变&quot;，另一个是&quot;你们有没有发现所有快乐都 是来自内在&quot;。 你真的只有discover到这一点，你才会做到第一步。 在阿含经这种古典里，它就被表述为见苦、见苦集。但是 莱斯特用白话随口说出来，你会忽略。</p><hr><h2 id="page-91" tabindex="-1">第 91 页 <a class="header-anchor" href="#page-91" aria-label="Permalink to &quot;第 91 页 {#page-91}&quot;">​</a></h2><p>91 所以调转方向真的不是通过喊着&quot;我要自由&quot;的方式， 而是一点点确认你的gain来自于释放，没有什么在六步 骤之外。 你不能只是抗拒世界，厌恶世界，这样是没有用的。 不幸的是，大部分人喊着&quot;想要自由&quot;时，他们压抑的是 对世界的厌恶。但厌恶和贪恋是一回事，它们是欲望的两 个方向。 你必须真的在经验层面做到第一步，才会起作用。通 过不断释放，不断确认你的收获。确认你的快乐来源。 OK，释放吧，从获得一点好处，到获得所有好处。也 没什么其他要说的了。</p><hr><h2 id="page-92" tabindex="-1">第 92 页 <a class="header-anchor" href="#page-92" aria-label="Permalink to &quot;第 92 页 {#page-92}&quot;">​</a></h2><p>92 【2020.12.3 见到快乐完全源自内在才会转向】 风：主要是要达成第一步，达成第一步后面的都达成 了，主要是流向完全转变。 你们没有注意到另一个第一步的说法，想要自由超过 想要控制和认同，more than，你可以想要控制和认同， 但是你想要自由要超过它们。 我发过莱斯特讲解“入流”的话： 莱斯特：对，那是第一步，而且是方法的第一步，不 是吗？你必须想要自由超过你想要这个世界。 让我稍微改变一下说法，但这的确是它一开始的样子。 因为它看上去对人们没有实质意义，所以我们修改了它， 改成“你必须想要自由超过想要被认同和控制”，因为被 认同和控制等同于这个世界。但我认为更好的是用“你必 须想要自由超过想要世界”。 如果你做到了，你的行为接下来就会是：调转你朝着 世界的方向，专注回你自身，做那些从世界出离需要做的 事，允许你的无限存在仅仅是存在于此。所以第一步是你 必须想要自由超过想要这个世界。 ——摘自the way part1</p><hr><h2 id="page-93" tabindex="-1">第 93 页 <a class="header-anchor" href="#page-93" aria-label="Permalink to &quot;第 93 页 {#page-93}&quot;">​</a></h2><p>93 （接下来风引用了他在2020.11.16分享的内容） 风：做到第一步，你就会落入后五步。莱斯特确实是 这样说的。古今的表达（指前面引用的莱斯特的话和下面 阿含经的两段），可以对照一下看看。 「大德！所谓明丶明者。大德！云何为明耶？云何为 随明耶？比丘！苦之智，苦集之智，苦灭之智，顺苦灭道 之智，此名之明；如是者为随明。」 集就是成因，苦集就是苦之成因。知道苦，知道苦之成 因，知道苦可以灭去，知道灭苦之道，这是四圣谛第一转。 这个知道叫作&quot;明&quot;，明就像在屋子内开了一盏灯，这个时 候&quot;出世间八圣道&quot;会马上展现在你面前，顺苦灭道之智。 「圣弟子！苦、苦思惟，集……灭……道、道思惟， 无漏思惟相应于法，选择、分别、推求、觉知、黠慧、开 觉、观察，是名正见，是圣、出世间、无漏、不取、正尽苦、 转向苦边。」 你的每一个选择、分别、推求、觉知、黠慧、开觉、 观察就会自然地转向（这叫转向苦边），与无漏相应。无 漏是古译，意思就是完美的、没有缺憾的，你不会再追求</p><hr><h2 id="page-94" tabindex="-1">第 94 页 <a class="header-anchor" href="#page-94" aria-label="Permalink to &quot;第 94 页 {#page-94}&quot;">​</a></h2><p>94 有漏（不完美、有缺憾）的快乐，这个阶段在七觉支里面 是从念觉支到择法觉支的阶段，在六步骤里面就是第一步 和第二步。 但现在没有任何一派佛教还知道这个东西，你去寻找 任何一派佛教对七觉支的说法，都是错误的。而莱斯特用 白话来解释这个，却十分清晰。 简单地说，只有当你见到世界=痛苦、所有快乐都来 自内在时，你才会转向，才会达到第一步。只要你还认为 世界上有快乐，你就会停下来去追寻。 经常听音频和看视频的话，应该会见到莱斯特经常问 两个问题：一个是&quot;你们有没有体验过内在picture改变， 外面马上改变&quot;，另一个是&quot;你们有没有发现所有快乐都 是来自内在&quot;。 你真的只有discover到这一点，你才会做到第一步。 在阿含经这种古典里，它就被表述为见苦、见苦集。但是 莱斯特用白话随口说出来，你会忽略。 你保留着在世界寻找快乐的可能,就不会做到第一步, 因为凡是你认为可以找到快乐的地方，你都会决定去的。 所有快乐都来自内在，但你真的需要自己discover这一 点，你要体验到。你不能只是抗拒世界，厌恶世界，这样 是没有用的。</p><hr><h2 id="page-95" tabindex="-1">第 95 页 <a class="header-anchor" href="#page-95" aria-label="Permalink to &quot;第 95 页 {#page-95}&quot;">​</a></h2><p>95 【2020.11.17 六步骤第一步对应佛法中讲的入流】 风：你之所以会在这个世界追求快乐，原因是什么？ 因为你在经验层面错误地以为世界上有快乐。 因此莱斯特让你发现，这个世界等于miserable（悲 惨的）。完全体验到这一点，会发展出一个智能，这个智 能佛陀叫作见苦，见苦之智。接着你会见到苦之成因，世 界之所以痛苦，是因为你的贪恋和嗔恨（贪恋和嗔恨是你 的欲望的两个方向，就是三个想要：想要安全、想要被认 同、想要控制），只要它们熄灭，你的痛苦就会完全消失， 所有快乐都在你的内在。 这个了知、这个智能，佛陀叫作苦集之智以及苦灭之 智。知道世界是痛苦，知道痛苦如何形成，知道痛苦如何灭， 这构成了一个正确的观察，佛陀称之为“正见”，或者叫“明” 和“圣智”。（知道苦，知道苦之成因，知道苦可以灭去， 知道灭苦之道，这是四圣谛第一转，也就是达到预流。） 以正见为先导，整个道路的八个部分都呈现到你面前， 佛陀称之为“出世间八圣道”，方向开始调转。这在六步 骤里，就是达到了第一步，所以，六步骤一开始是操作指南。 到了这里，你的每一个选择、分别、推求、觉知、黠慧、 开觉、观察就会自然地转向，全身心调转到解脱的方向， 与无漏思惟相应。无漏是古译，意思就是完美的、没有缺 憾的。你不再在不完美的世界里寻找快乐，于是全身心地、</p><hr><h2 id="page-96" tabindex="-1">第 96 页 <a class="header-anchor" href="#page-96" aria-label="Permalink to &quot;第 96 页 {#page-96}&quot;">​</a></h2><p>96 自然地在每一个抉择里调转方向。 所以达到六步骤的第一步，这其实已经是佛教里面所 谓的初果圣人、预流果、入流果、慧解脱，已进入圣者之流， 你会自然断除三种结： 第一个结是疑结，由于整个道路呈现在你面前，所以 你断除了所有疑惑。 第二个结是身见结，由于见到世界的缺陷，你不会在 任何地方寻找“我”，不会以为身体是“我”。 第三个结是戒禁取结，由于看到一切的来源，你不会 再升起仪式、外在的力量有效果，不会再生起它们能够导 向终点的想法。 同时你有可能进入恶道的业力完全被清除。到这里， 是第一步完成的结果，剩下五步会自然掉入你的经验中。 除了在 the way 里，莱斯特在别的音频里描述的“做 到第一步，你的每一个行为都会是趋向自由的”也是一样的。 在真正进入六步骤之前，有疑惑都是很正常的，这些 是反反复复。因为在道路呈现之前，你不会真正断除疑结。 在道路呈现之后，信根建立，古代的译法叫不坏净信，实 际上就是第二步的达成。</p><hr><h2 id="page-97" tabindex="-1">第 97 页 <a class="header-anchor" href="#page-97" aria-label="Permalink to &quot;第 97 页 {#page-97}&quot;">​</a></h2><p>97 【2020.12.11不断通过释放接触到无限意识，感受到它 是快乐的唯一来源，才会完全转向 】 风：莱斯特到三摩地的时候，他并不知道有三摩地这 一回事,所以知不知道三摩地这个概念并不影响你到那里。 我反复说明的是，涅比卡帕三摩地，其实六步骤的第 一步的完全达成。 为什么呢，因为你只有在接触到无限的那一刻才会完 全达成。 不断地通过释放接触到无限，会突然一下子发现那些 种子都不起作用了，你在其他地方寻找快乐的动机全部没 了。因为你在经验层面发现快乐的唯一来源，这时候种子 就不会再起作用了。 你如果不接触到无限意识，你永远会觉得世间有快乐。 只要你觉得世间有快乐，你的方向就有可能再朝向世 间，这很简单。</p><hr><h2 id="page-98" tabindex="-1">第 98 页 <a class="header-anchor" href="#page-98" aria-label="Permalink to &quot;第 98 页 {#page-98}&quot;">​</a></h2><p>98 莱斯特：此刻我不会给你们更多指引，我已经给了你们太多， 你们对我所说的有什么感觉？到目前为止，你们对我给你们的 那些感觉如何？这些是重点： 第一个是，你想要自由超过想要世界。 第二个是，通过释放从你的内在获得所有的快乐。 下一个是，决定自由，并去做。 再下一个是，直接释放对死亡的恐惧——对你们来说这是 最困难的一个，因为你们觉得如果释放了它，你们就会死。 ——摘 自 THE WAY Part4 第一课是你要想要自由超过你想要这个世界。随之，你应 该从你自己内在获得所有的快乐，仅通过释放去得到它。 —— 摘自 THE WAY Part 2 风：从你的内在获得所有快乐，完全做到，这就是涅 比卡帕三摩地的达成。 莱斯特说的太平常了，以至于人们会忽视他的意思。</p><hr><h2 id="page-99" tabindex="-1">第 99 页 <a class="header-anchor" href="#page-99" aria-label="Permalink to &quot;第 99 页 {#page-99}&quot;">​</a></h2><p>99 在你完全释放掉心智之前，你会对无限存在有一个预 览，也就是说，尽管你还没有完全释放掉整个心智程序， 但是会有心智退居幕后的时刻。这时候，你的心智完全静 止了，暂时性地。于是你在这一刻可以体验到无限存在， 对它有一个预览，这可以极大增加你对自由的向往。 因为你会发现自己无论在世界上获得什么，都抵不上 那个快乐的万分之一，在世界上的每一刻，相比那个状态， 都在煎熬。 在此之后你的释放是不一样的。你不再需要提醒自己 六步骤，因为你在第一步里，你的每一个决定都自然朝向 自由。释放根本停不下来，而且会经常进入三摩地，会经 常接触到无限，每一次都会带走你的很多欲望。 我之前说过，通过有一些方法达到涅比卡帕三摩地， 习性上会差一点，因此需要更多的时间来释放业力，因此 莱斯特花了三个月，其中的过程是把释放的方法探索出来。 如果不用释放法，仅仅是通过进入无限来烧掉业力的 话，会花上更长时间。 灵修圈喜欢说一个词，悟后起修。悟解保任，行解相应， 这其实是禅宗的概念。因为禅宗是智性的方法，所以要保 任，需要在生活中每一处，用无限意识来矫正你的习性， 认识到你不是行为者，而是你的无限存在透过你在做，这 个过程就是释放业力的过程。</p><hr><h2 id="page-100" tabindex="-1">第 100 页 <a class="header-anchor" href="#page-100" aria-label="Permalink to &quot;第 100 页 {#page-100}&quot;">​</a></h2><p>100 释放业力只有在你认识到自己不是那个行为者时才会 发生，而无法通过行为本身发生。 Roller:就是真正达到圣弟子才是悟后。 风：当然。佛教对这个的区分比较准确。预流果之前， 无论什么神通境界，都只能叫凡夫，处在凡夫之流。 预流之后，就是圣者之流，圣弟子。 欲界天人，色界天人，无色界天人，都是凡夫。</p><hr><h2 id="page-101" tabindex="-1">第 101 页 <a class="header-anchor" href="#page-101" aria-label="Permalink to &quot;第 101 页 {#page-101}&quot;">​</a></h2><p>101 【2020.11.14对自由的渴望不是建立在对世界的厌恶上】 风：莱斯特说厌恶感往往被压抑得更深。 对世界的厌恶和对世界的贪恋一样，都是想要世界。因 此就目标释放而言，你必须实际做到。 如果不能达成你的目标，那一定还有&quot;我不能&quot;的程序 被压抑在深处。 所以，当莱斯特强调&quot;通过释放获得一切&quot;的时候，你 需要真的做到，而不是用一种限制性观念替代它。 （接下来 Roller 引用了一段 《 get high to release 》 中的话） 莱斯特:很难去看到对这世界的厌恶（aversions）， 你的贪恋（attachments）很明显，而且你一直都在追逐它 们，但厌恶的情绪又将你拒之门外。 因此，当你追求目标时，就会出现“哦，我怕”，“我 不能”和所有这些东西。 所以，将对这世界的厌恶情绪浮现出来然后你就可以去 放下它们。如果你没有意识到这件事，那么你将无法看到 或去处理它，因此，在世界去获得成就可以带出你的消极 程序与想法。 世界无法为你提供富裕和丰富的服务的唯一原因是因为</p><hr><h2 id="page-102" tabindex="-1">第 102 页 <a class="header-anchor" href="#page-102" aria-label="Permalink to &quot;第 102 页 {#page-102}&quot;">​</a></h2><p>102 你有相反的想法，而他们却被压制了。 努力使世界变得更美好，让相反的感觉浮出水面，然后 你释放它们。因为如果你无法成功，那是因为你坚持在使 用使你失望的程序，却看不到它们。 风：有一个贪恋，就会有一个厌恶，attachment and aversion，成对出现。 厌恶是欲望的层面，这是在the right path里面有说 到，desire（attachment） and aversion。 workbook里面有want 和 don&#39;t want，你想要的就是 贪恋，不想要的就是厌恶。 但它们都是一种&quot;想要&quot;，只是两个不同的方向， different direction。</p><hr><h2 id="page-103" tabindex="-1">第 103 页 <a class="header-anchor" href="#page-103" aria-label="Permalink to &quot;第 103 页 {#page-103}&quot;">​</a></h2><p>103 【2020.11.17 用目标勾出压抑的感受，通过释放确认自 己所有收获来自无限内在，才会趋向自由，达成第一步】 风：如果你有想要的，你就去做到，这就是莱斯特教 你的。你获得越多，你越能发掘快乐的真正来源。真正做 到的时候，你根本不用思考你想要自由还是世界，你接下 来的每一个行为和抉择都会自然趋向自由。 可是当你依然保留着&quot;世界中有快乐&quot;的可能性时， 你就不会做到，你会下意识地去其他地方寻找快乐，这就 构成你的目标，你要用这个目标把程序勾出来，实现目标， 你才会发现程序一直在运作你，你的方向才会真正调转。 如果你压抑它，它就一直在里面影响你，你就永远做 不到第一步。 第一步不是口号，六步骤是一个非常完美的地图，你 需要通过释放来确认自己所得，直到你发现所有快乐都 来自于一个东西——无限存在，发现如莱斯特所说，the world is completely miserable。 当你达成目标，你会发现你没有获得想象中的快乐， 这时候你会勾出下一个目标，下一个对世界的想要。当你 再达成，你发现你还是没找到你想要的快乐，于是你的欲 望会到再下一个目标。 你会不断上升，不断确认快乐的来源，直到你体验到</p><hr><h2 id="page-104" tabindex="-1">第 104 页 <a class="header-anchor" href="#page-104" aria-label="Permalink to &quot;第 104 页 {#page-104}&quot;">​</a></h2><p>104 所有快乐的来源是你“心智安静下来，让内在的无限存在 显现了更多”，你的方向就会调转，这就是彻底完成了第 一步，自由就变成了你的唯一目标。 接下来，如莱斯特所言，你会自动掉入后五步，就是 这样。 【2021.11.19 真正达到第一步后不会退转】 风：不会再受到自我意识的诱惑，完全趋向自由。这 是六步骤的第一步，瑜伽里面他们叫涅比卡帕三摩地，真 正工作的开始。 如果你没达到这里，你就有可能退转，如果你达到了， 就不会退转，真正达到第一步你就不会沉沦。入流（预流）， 不再后退。 对快乐来源的洞见会让你达成第一步，在此之后你的 每一个决定都是向内，都是解脱你的束缚，往你的真实存 在走。最关键的是你习惯用从世界中挣扎的方式来获得， 你得发现这是愚蠢的，释放，然后轻而易举地获得，让它 成为你的常态。 表格是很好的工具，我也建议你们用表格（指 workbook里的释放表），我强烈建议的是目标表格，而且 是建议加上失败后的记录。</p><hr><h2 id="page-105" tabindex="-1">第 105 页 <a class="header-anchor" href="#page-105" aria-label="Permalink to &quot;第 105 页 {#page-105}&quot;">​</a></h2><p>105 你得发现自己实现每一个目标的能力，你得消除你的 失败程序，而消除它的前提是面对它，允许它浮出。 如果你真正做到第一步，你的每一个抉择和行 动，都会自然趋向自由的方向，然后你就会决定自由。 要不然为什么莱斯特和kam说，达到第一步， 就没有任何东西能阻碍你，因为第一步就是涅比卡 帕三摩地，不会退转了，种子都不起作用了。 ——风 2020.12.3</p><hr><h2 id="page-106" tabindex="-1">第 106 页 <a class="header-anchor" href="#page-106" aria-label="Permalink to &quot;第 106 页 {#page-106}&quot;">​</a></h2><p>106 【2020.11.28 如何快速达到第一步】 风：我深切知道了阿含经中“预流”的含义，预流、入流， 当你彻底达成六步骤的第一步时，每一个趋向、抉择都导 向自由。 见苦之智，这是达成第一步的先导，你会看到世界的 方向=痛苦，而自由的方向——无限存在是快乐的唯一来 源，你就会自发停止所有试图在世界上撞得头破血流去寻 找快乐的行为。 问：如何可以快速经验性地达成第一步呢？也就是预流阶段。 风：贯彻六步骤。六步骤里面最容易让人忽视的就是 第六步，但第六步正是达成第一步的关键。 因为你事实上在经验层面是在世界的方向寻找快乐， 所以你要实践莱斯特最喜欢的那个教导：get everything by releasing only，当你每一次想要一个事物，通过释 放来达成，这个收获就会让你更想要释放。 不断确认你的gain，会让你持续释放。直到你发现你 的目标一个个实现，你仍然不快乐，你就会在经验层面“发 现”任何事物根本不能带给你快乐。 立即地，你会觉知到快乐的唯一来源，这时候马上会 发生一个流向的改变，一个生命流向的彻底改变，你完完</p><hr><h2 id="page-107" tabindex="-1">第 107 页 <a class="header-anchor" href="#page-107" aria-label="Permalink to &quot;第 107 页 {#page-107}&quot;">​</a></h2><p>107 全全调转了方向，这就是完全达成了第一步：想要自由超 过想要世界。 接着，就会按照莱斯特说的，不断掉入后五步中去。 第一步的完全达成，需要预流，但是你如果不 主动运用第一步和第二步，你也不能达到预流。六 步骤是需要你主动贯彻的，然后当你彻底达成第一 步，后五步就会带着你走。 所以对你们来说最具有实践性的就是莱斯特最 推荐的教导： get everything by releasing only （仅仅通过释放获得一切）。 everything means everything （一切就是一 切），你仅仅通过释放获得想要的一切，这也能让 你贯彻六步骤。 ——风 2020.12.16</p><hr><h2 id="page-108" tabindex="-1">第 108 页 <a class="header-anchor" href="#page-108" aria-label="Permalink to &quot;第 108 页 {#page-108}&quot;">​</a></h2><p>108 【2020.11.20 风讲述他是如何达成第一步的】 风： 释放什么都能做到，让它成为你的体验。闭关的 过程，我还实现了好多目标。不过我没有用目标表格，我 只是把我想实现的列了出来，然后不停释放，之后发现大 多数都达成了。 Roller: 闭关的时候你已经踏入第一步了吗？ 风： 后来那次确证了六步骤，确证六步骤那次我知道 有些东西彻底发生了转变，后来突然意识到那是阿含经里 的预流，再之后看了尊者的解释知道那也是瑜伽里的涅比 卡帕三摩地。 确证是达成第一步，只有达成第一步你才能断疑，断 疑才叫&quot;确证&quot;。整个道路会呈现在你面前，你直接知道 接下来该怎么走到终点，一个直接的知道，不需要通过思 考。然后你发现，你的每一个行为不可能往自由的反方向 走了，这个改变流向的感觉是非常明确的。 我是无限： 你是怎么突然确证六步骤的？ 风： 你是说直接知道六步骤吗？ 我是无限： 嗯，连续释放了多久？ 风： 我释放了一个星期不到，持续释放。</p><hr><h2 id="page-109" tabindex="-1">第 109 页 <a class="header-anchor" href="#page-109" aria-label="Permalink to &quot;第 109 页 {#page-109}&quot;">​</a></h2><p>109 我是无限： 一直闭关释放一个星期？ 风： 嗯，我的持续释放不是呆做在那里逼自己释放， 我写了很多目标在上面，我的心理活动是验证。 当时我是这样的：我做一次释放，然后感觉到很好， 我就会说，再释放一次，会不会感觉更好，验证一下第六步。 然后我卡住了，我就说，验证一下第五步吧，释放一下想 要控制看看到底会不会变好。一看，哈哈，果然顺畅了， 好开心，继续再释放一次。 所以整个过程其实挺有趣的，不是很多人想象的坐在 那里苦修。大概持续释放了几天之后，我已经感到很快乐 了，这时候洞见自然冒出来，我就直接知道快乐的唯一来 源是什么。 痛苦就是限制你的无限存在，当你用感受遮住它时， 那就是痛苦。 这个领悟一发生，我立即感到有些东西改变了，释放 变得很主动，不需要任何那些纸上目标的勾引。就是不停 释放、不停释放，然后就到了我说的那个点，和整个心智 一下子抽离了，感觉心里使用的所有力量全部往内走。就 那么一瞬间，感觉整个身心都转向了。然后后面的步骤就 一下子全知道了。 我当时以为那些经验是个体化的，所以很多没细说。</p><hr><h2 id="page-110" tabindex="-1">第 110 页 <a class="header-anchor" href="#page-110" aria-label="Permalink to &quot;第 110 页 {#page-110}&quot;">​</a></h2><p>110 比如我身体压力卸下时突然完全放松挺直。 现在我知道这是必然会生的，因为这是进入三摩地的 先决条件，也是达到涅比卡帕三摩地的前面几支中的一支。</p><hr><h2 id="page-111" tabindex="-1">第 111 页 <a class="header-anchor" href="#page-111" aria-label="Permalink to &quot;第 111 页 {#page-111}&quot;">​</a></h2><p>111 当你达到涅比卡帕三摩地，就是完全达成六步骤 的第一步，完全地达成第一步会让你自发性地掉进后 五步。在此之前，你要不断核实六步骤，确保你在达 到第一步的路上。 ——风 2020.11.26</p><hr><h2 id="page-112" tabindex="-1">第 112 页 <a class="header-anchor" href="#page-112" aria-label="Permalink to &quot;第 112 页 {#page-112}&quot;">​</a></h2><p>112 我说一个很简单的，第一步的用法。 当你想要去和别人说话时，假设你有想要认同， 这个时候你停止了释放，这个时候，一个想要认同在 运作你。 如果你提醒自己第一步，我想要自由超过想要认 同和控制，你就能够让这个想要认同浮现出来。 否则，你就会去说话，让那个想要认同待在里面 运作你。 所以尽量搞清楚六步骤，要彻底清楚，这样才能 持续释放下去。 ——风 2020.10.24</p><hr><h2 id="page-113" tabindex="-1">第 113 页 <a class="header-anchor" href="#page-113" aria-label="Permalink to &quot;第 113 页 {#page-113}&quot;">​</a></h2><p>113 第一步，想要自由超过想要认同和控制，如果做 不到，很多感受甚至没法浮现出来，此刻如果你想要 控制和认同超过你想要自由，你就不会去释放。 因为想要自由没有超过想要控制和认同，所以你 就把它压在里面，你不会让它出来。 只有你想要自由，你才会允许它浮现。所以，确 保自己做到第一步。 如果你想要自由，你就会决定去做，你会允许它 浮现出来，而不是让它待在里面运作自己。 允许自己觉察到当下的感受，它们是想要控制或 者想要认同，放它离开。 ——风 2020.10.24</p><hr><h2 id="page-114" tabindex="-1">第 114 页 <a class="header-anchor" href="#page-114" aria-label="Permalink to &quot;第 114 页 {#page-114}&quot;">​</a></h2><p>114</p><hr><h2 id="page-115" tabindex="-1">第 115 页 <a class="header-anchor" href="#page-115" aria-label="Permalink to &quot;第 115 页 {#page-115}&quot;">​</a></h2><p>115</p><hr><h2 id="page-116" tabindex="-1">第 116 页 <a class="header-anchor" href="#page-116" aria-label="Permalink to &quot;第 116 页 {#page-116}&quot;">​</a></h2><p>116 第一步只能不断确认，一开始做不到，但是你 释放之后，会感觉更自由，那是第六步对第一步的 促进作用，也是 gains book 的用法，你记录下自 己的收获，这会让你越来越认识到自由的价值，从 而也越来想要自由。 第一步可能一开始有点抽象，但你每次释放， 都能体验到“更自由”是什么感觉，慢慢它就对你 不抽象了。 ——风 2020.10.1</p><hr><h2 id="page-117" tabindex="-1">第 117 页 <a class="header-anchor" href="#page-117" aria-label="Permalink to &quot;第 117 页 {#page-117}&quot;">​</a></h2><p>117 按照六步骤释放，一个星期你就能达到极高的状 态，甚至进入涅比卡帕三摩地。如果你把这个过程拖 很长，那就一定不在六步骤中。莱斯特告诉你，释放 一次，相当于冥想好几个月，一次释放只需要几秒钟 而已，你只需要几秒钟就等于冥想了几个月。 这个方法是极高效的，你可以看看六步骤，就知 道自己在不在里面。如果你在六步骤中，你的释放会 是持续的，愉悦也是持续增加的。 ——风 2020.12.16</p><hr><h2 id="page-118" tabindex="-1">第 118 页 <a class="header-anchor" href="#page-118" aria-label="Permalink to &quot;第 118 页 {#page-118}&quot;">​</a></h2><p>118 这很简单也很容易， 你只要做出选择。 当你想要自由时， 你决定想要自由比想要你生活中的一切都要多 时，我指的是一切，关系，财富…… 当你想要自由多于你想要这些东西时， 你很快就会得到它。 而且，当你看到你想要自由的唯一原因是去拥 有自由，这将帮助你迅速做出决定。 但你必须保持简单，开始去做吧，通过释放你 的感受来消除心智活动。 当你这样去做的时候，你处于爱，丰盛的最高 状态，而这是你的本然状态。 ——莱斯特</p><hr><h2 id="page-119" tabindex="-1">第 119 页 <a class="header-anchor" href="#page-119" aria-label="Permalink to &quot;第 119 页 {#page-119}&quot;">​</a></h2><p>119</p><hr><h2 id="page-120" tabindex="-1">第 120 页 <a class="header-anchor" href="#page-120" aria-label="Permalink to &quot;第 120 页 {#page-120}&quot;">​</a></h2><p>120 我的记录</p><hr><h2 id="page-121" tabindex="-1">第 121 页 <a class="header-anchor" href="#page-121" aria-label="Permalink to &quot;第 121 页 {#page-121}&quot;">​</a></h2><p>121</p><hr><h2 id="page-122" tabindex="-1">第 122 页 <a class="header-anchor" href="#page-122" aria-label="Permalink to &quot;第 122 页 {#page-122}&quot;">​</a></h2><p>122 我决定去走向自由，我要去做了。昨天释放的时 候，这个决定变得十分清晰。我现在这个状态，曾经 的自己完完全全不敢想象，但我知道还不是终点。 百分之七八十以上的时间我都在&quot;知道&quot;的层面 运作，只是&quot;知道&quot;，不需要调动任何&quot;知识&quot;和&quot; 信念&quot;。 心智运作的比以前少了很多很多，我看到了莱斯 特说的&quot;所有快乐都来自内在&quot;，当我们试图在世间 获得快乐，我们是创造了一个匮乏，这个匮乏驱动了 很多感受和念头。 我们所谓的从世间获得快乐，真正发生的状况仅 仅是我们通过告诉自己&quot;我达成了目标&quot;，从而暂时 让心智安静了。心智安静=快乐。 因为快乐的唯一来源只是存在，而心智是无限存 在的唯一遮蔽物。 去做吧，我知道了，几个月或者几个星期就可以 做到自由。这次不是&quot;我相信&quot;，而是&quot;我知道&quot;， 清晰地看到了全景。 贯彻六步骤，你就可以做到。 ——风 2020.10.18</p><hr><h2 id="page-123" tabindex="-1">第 123 页 <a class="header-anchor" href="#page-123" aria-label="Permalink to &quot;第 123 页 {#page-123}&quot;">​</a></h2><p>123 现在，我因为那个第一步的动力太过强烈，导 致会自发地进入释放，会被推动着释放，因此很难 降到可以引导别人的状态。 因为一旦持续释放，心智会非常安静，就无法 把别人看作自己之外的事物，这样你没办法把对方 看作是有问题的。 重新把别人视为一个与自己分离的对象，需要 很大的努力。如果不这样做，感觉就会持续向上走， 当向上走，二元性就会消失。 保持纯正，运用流程，keep it simple， sweetheart，这是莱斯特说的kiss 原则，莱斯特 说，这很简单，但人们一直在做的，是把它高度复 杂化，我们可以用很多语言体系来讨论一个相同的 事，我们可能转化很多表达范式，但是那些不是必 要的。 必要的是什么？学会释放流程和六步骤。 这是你在达到自由这条路上所需要的一切工具 和地图。 ——风 2020.10.23</p><hr><h2 id="page-124" tabindex="-1">第 124 页 <a class="header-anchor" href="#page-124" aria-label="Permalink to &quot;第 124 页 {#page-124}&quot;">​</a></h2><p>124 【2020.10.23 真的决定了就会马上去做】 风：决定自由不是祈祷文，不是心理暗示，决定就是 决定。就好像你现在决定从座位上走到门口。你决定了， 就会马上去做。 【2020.10.23 你的决定会带你去向想要的地方】 风：第一步是想要自由，第二步是决定自由。 如果你只是决定感觉好，或者达成某个物质目标，那 么在你得到之后你就会停下来。 如果你决定自由，在你到达自由之前就不会停下来。 因为你想要的、决定的，你就会带自己到那里去。 风谈六步骤 Step 2 第二步: 做出自由的决定。 Make the decision to go free.</p><hr><h2 id="page-125" tabindex="-1">第 125 页 <a class="header-anchor" href="#page-125" aria-label="Permalink to &quot;第 125 页 {#page-125}&quot;">​</a></h2><p>125 【2020.10.24 决定通过释放来达到自由】 风：第二步只是决定，下决定自由，决定去用这个释 放流程达到自由。 有的时候你踌躇不决，你会想“我要不要释放掉它 呢？”，或者你想用别的方法，比如觉察，比如参问，只 要你不决定去用释放流程做到自由，你会一直这样徘徊， 那么也就做不下去。 想要自由和决定自由，都是可以直接做的。 just want it more ， just make the decision. 当一个想要控制或认同运作你的时候，你确定释放掉 它会比它待在里面更好，它就会浮出来。 比如你现在想去玩游戏，那里面有个想要控制在运作 你，你觉得释放掉这个想要控制比去控制更重要，你就达 成了第一步，它就会浮现出来给你释放。 想要控制和认同=想要世界，也就是往限制的方向走， 限制的方向没有自由可言。</p><hr><h2 id="page-126" tabindex="-1">第 126 页 <a class="header-anchor" href="#page-126" aria-label="Permalink to &quot;第 126 页 {#page-126}&quot;">​</a></h2><p>126</p><hr><h2 id="page-127" tabindex="-1">第 127 页 <a class="header-anchor" href="#page-127" aria-label="Permalink to &quot;第 127 页 {#page-127}&quot;">​</a></h2><p>127 【2021.1.2每个人在每一刻都可以决定达到自由，这是 完全的自由意志。只有一件事你有自由意志，那就是选择 自由或者被束缚】 兰若： 那莱斯特这一生的觉醒，也是预设的？ 风： 只有觉醒这一件事没法预设。其他所有事情，你 都没有自由意志可言。 你只有一件事有自由意志，那就是选择认同你的身体 或者无限存在。其他事情，任何事情，都没有自由意志。 你的每一个想法都是被过去的程序推动的，包括你想要什 么、厌恶什么，取决于你程序的倾向。 只有一件事，是完全的自由意志——那就是在任何时 候，你都能认同你的无限存在。 释放，就是途径。 FREE: 那我们遇到释放法应该也是预设？ 风： 当然是。如果没有非常非常好的业力，你不可能 遇到释放法。抵达涅比卡帕三摩地，你的每一生就会浮现 出来。随后认识到在每一件事中，都不是自己在行动，你 一直是无限存在。这些后面的东西其实不需要说，我还是 想强调六步骤，贯彻它。</p><hr><h2 id="page-128" tabindex="-1">第 128 页 <a class="header-anchor" href="#page-128" aria-label="Permalink to &quot;第 128 页 {#page-128}&quot;">​</a></h2><p>128 彻底完成第一步的话，需要持续释放。六步骤都要注 意。但如果你的意愿力量（will power）足够强大的话， 也能仅凭渴望一瞬间达成第一步。 每个人都可以自由，只要你去做。 如果你一开始走得很快，但中途停下来了，那你就无 法自由。贯彻六步骤直到终点，贯彻是必须的。 倚天： 决定自由就是决定释放，决定释放需要先看破 头脑是自由的唯一障碍吗？ 风： 决定就是决定。你现在可以释放，也可以逃避情绪， 去玩手机，但是你决定释放。 当你达成第一步时，你只需要下一次决定：决定自由。 不要用任何头脑的方式尝试突破，跟着视频练习。 我两年前曾经持续释放过一次，一个星期。当时，心 智内的agflap清空得差不多了，接着处在一个非常舒适 的状态，身边的世界也展现前所未有的和谐。 接着，整整半年一次释放也没有做，接着那些agflap 就回来了，我甚至忘记了怎么释放情绪和欲望，持续地卡 住，所以才进群交流。 后来我发现群里的人似乎不知道莱斯特后期音频和原</p><hr><h2 id="page-129" tabindex="-1">第 129 页 <a class="header-anchor" href="#page-129" aria-label="Permalink to &quot;第 129 页 {#page-129}&quot;">​</a></h2><p>129 始版本的释放法的存在，于是就翻译了the way和92课 程的两篇。 在翻译的过程中，我自己也温习了一遍，记起了其中 的要点。于是我又开始持续释放，记着上次的教训，就一 次往前走了。 在你到终点前，一定不要停下来。 因为一旦你不在前进，就在后退。 因为你没完全释放掉想要控制和认同，以及死亡的恐 惧，树根还没砍断，树枝和树叶会慢慢长出来。 没有所谓的静止不动，一旦你不在前进，你就在后退。 &quot;以后再做&quot;，这是个头脑的诡计，一旦用未来式，你 的头脑会让它待在未来。 以后再做，意味着永远不会做。 这个时代只有非常少的人才趋向自由。</p><hr><h2 id="page-130" tabindex="-1">第 130 页 <a class="header-anchor" href="#page-130" aria-label="Permalink to &quot;第 130 页 {#page-130}&quot;">​</a></h2><p>130 【2020.10.18】 风：第三步，就是所有感受都是想要控制和认同。时 时刻刻你都有感受，你看到的整个世界，就是想要控制和 认同。你二十四小时防卫着，不让死亡的恐惧浮现出来。 防卫的机制，就是想要控制和认同。 【2020.10.23】 风：第三步是&quot;所有感受都是想要控制和认同，释放 它们&quot;，所有感受的意思就是所有感受，你现在一定有感受， 它一定是想要控制和认同，你可以释放它们。 风谈六步骤 Step 3 第三步: 所有感受都来自想要被认同和想要控制， 它们都是生存程序，释放它们。 All feelings culminate in two want：wanting of approval and wanting of control.</p><hr><h2 id="page-131" tabindex="-1">第 131 页 <a class="header-anchor" href="#page-131" aria-label="Permalink to &quot;第 131 页 {#page-131}&quot;">​</a></h2><p>131 【在释放成为惯性之前，按照流程走，不要仅是觉察】 【2020.10.24】风：只要你认出想要被认同和想要控 制，你会马上有一个自然放它离开的倾向，它就会在你甚 至来不及问之前就消散。 问：一觉察，它就走，有的时候是，有的时候还有。 风：所以，使用流程。不要用自己发明的“只是觉察”， 它不会走的。流程已经很简单了：允许自己觉察到感受， 觉察到它是想要控制还是认同，然后让它离开。 如果你试图跳过流程，它不会奏效的，可能奏效一两 次，但它不会总是奏效，因为头脑的惯性非常强大，如果 不用这个技巧，你的压抑的习惯会拉着你走。 释放流程是不符合人的习惯的，所以一开始要有意识 用流程，直到到达一个点，流程会带着你走。 【2020.10.22】问：风，请问释放到一定程度，像你 这样也是用流程一步一步释放，还是一觉察到任何想要它 就离开了，就不需要再问问句了？ 风：floats up and out，像波浪一样浮现然后离开。 释放到后面，动力会很强大，只要你做一个释放的决定， 它就会带着你走，你不需要像之前那样努力操作了。 【2020.12.30】风：当你持续释放之后，问句都是多 余的。不过刚开始，还是需要问句引导。</p><hr><h2 id="page-132" tabindex="-1">第 132 页 <a class="header-anchor" href="#page-132" aria-label="Permalink to &quot;第 132 页 {#page-132}&quot;">​</a></h2><p>132</p><hr><h2 id="page-133" tabindex="-1">第 133 页 <a class="header-anchor" href="#page-133" aria-label="Permalink to &quot;第 133 页 {#page-133}&quot;">​</a></h2><p>133 【2020.10.23释放的要点在于流程，在于持续释放。不 要与其他方法中的觉察与观照混淆】 清溪： 风，只是觉察到想要这个倾向直接释放。不觉 察来自想要认同还是来自想要控制，这样操作可行吗？不 行的话，为什么？ 风： 你觉察得清晰，才能释放。当它浮现到表面来， 你就会直接觉察到，然后就会有自然的倾向放它离开。 倚天： 释放的关键还是觉察的能力，对吧。 风： 不是,是流程。不管你觉察能力多好，只要你在流 程中该让你释放想要控制的时候去觉察别的，你就会卡住。 明空： 平时是感受和情绪来了再释放，还是时刻觉察时 刻主动去问当下的感受主动走流程呢？ 风： 主动用流程。 朝颜： 要一件一件的去释放，一个一个人的去释放，是吗？ 风： 不是一件一件事释放，是一个个感受释放。要有意 识觉察到你的感受，以及它激起的想要控制和认同。 倚天： 那就是说，释放的要点就是要能够觉察到那个“想要”？ 风： 释放的要点是流程，我无法说是觉察，因为觉察是 一个很容易被混淆的东西。</p><hr><h2 id="page-134" tabindex="-1">第 134 页 <a class="header-anchor" href="#page-134" aria-label="Permalink to &quot;第 134 页 {#page-134}&quot;">​</a></h2><p>134 大道至简： 释放和旁观有何不同？ 风： 当你旁观的时候，你想要控制还是想要认同？ 大道至简： 就是不参与，只是旁观。 风： 很多人说:我只是观照。它的意思是把自己放在一 个观照者的角度，但这是一种佯装，因为你还压抑着感受。 那些驱动力还在深处运作着你，想要控制和认同还在驱动你。 大道至简： 请教二者本质区别是啥？ 风： 一个是压抑，一个是释放。 大道至简： 旁观我理解是自然无为，有压抑还是有为。 风： 你这样做不到无为。莱斯特说，无为有两种：一 种是最低的状态，万念俱灰；另一种是最高的状态，平静， 即万事万物都很完美，都是无限，没有什么需要改变的。 你觉得如果你现在想要刻意去做到无为或者顺其自然，你 会是哪种？ 莱斯特有一句更好的概论：“方法很简单，方法也很容 易。让感受浮现出来，觉察出它们是想要认可或控制，然 后让他们出去。贯彻这个方法的六个步骤，会花几个月的 时间来清空你所有的垃圾。” 释放法的重点当然还是持续释放，而不是持续观照。察</p><hr><h2 id="page-135" tabindex="-1">第 135 页 <a class="header-anchor" href="#page-135" aria-label="Permalink to &quot;第 135 页 {#page-135}&quot;">​</a></h2><p>135 觉到你现在的感受，然后觉察出它是想要控制或者认同， 然后释放。 我修过很多种类型的禅修，修过不同的重视觉察的方 法，它们真的和释放法不一样。如果用那些经验来操作释 放流程，只会造成阻碍。 清溪： 觉察到想要控制或者认同，只是觉察想要的倾向， 无需觉察到想要认同什么内容，想要控制什么内容，不管 认同或控制的内容是任何？对吗？ 风： 是的。你们是不是认为一定有内容？不是的，这个 世界不是这样创造出来的。你是先创造了一个心智，是先 有对死亡的恐惧的倾向，然后才有想要控制和认同。然后 再有agflap的情绪，然后才有思想，然后思想投射出物质 世界，物质世界再联系成事件内容。 所以，事件内容是结果，并不是事件导致想要的倾向， 而是想要导致事件。想要驱动每一个念头创造世界。因此如 果你察觉到想要，这是起因，你并不需要对应事件。 清溪： 原来如此，以前完全搞错方向了，释放想要，其 实是从因上放手，对吗？ 风：想要是最根本的原因。</p><hr><h2 id="page-136" tabindex="-1">第 136 页 <a class="header-anchor" href="#page-136" aria-label="Permalink to &quot;第 136 页 {#page-136}&quot;">​</a></h2><p>136 【2020.10.18 觉察感受时不需要努力】 风：当流程说“允许自己觉察到”时，它指的不是你 用力去挖掘，而是你此刻什么也不做的情况下觉察到什么， 不需要呼唤努力、不需要使用控制。 课程为什么不教你“如何觉察”？ 因为“如何”含有一种头脑的努力。 比如，你问自己现在想要控制还是想要认同，你马上 就能觉察到。如果不能，那你就是想让自己能，想要事情 按照自己的来，那就是想要控制。这非常简单。 所以，再说一次，你们要牢记六步骤，把它放在身边， 随时拿起来看。释放的任何问题都能在六步骤中找到答案。</p><hr><h2 id="page-137" tabindex="-1">第 137 页 <a class="header-anchor" href="#page-137" aria-label="Permalink to &quot;第 137 页 {#page-137}&quot;">​</a></h2><p>137 【2020.10.23 释放掉足够多的想要认同和控制，下面对 死亡的恐惧会自动浮现出来给你释放】 芳菲： 风老师，六步骤里只有“想要控制和认同”， 没有提到“想要生存”的欲望这第三个want呀。 风： 这个会自动浮现，因此不需要放在步骤里刻意操 作，莱斯特在the way里面有讲到这些。 【插一段风2020.9.30的分享】 风：我昨天刚好重听了一下莱斯特的两个音频，他说 在释放掉足够多的想要控制和想要认同之前，你不会觉察 到对死亡的恐惧（想要生存、想要安全）。对死亡的恐惧 （fear of dying)是更深的，所以一开始你不用去考虑。 我知道后面的释放法会让你同时去注意三种欲望，但最初 的只要你去注意想要控制还是想要被认同。你释放掉这些 覆盖住想要生存（对死亡的恐惧）的欲望，它自然会浮现 出来被你看见，然后你就可以释放它了。 所以，莱斯特说的会简洁一些：一开始你不会允许对 死亡的恐惧浮现，因为你是那样地程序化，你的所有感受 都是生存程序（survival programs），它们的作用就是 防卫你不去接触到对死亡的恐惧，所以当你释放掉这些防 卫程序，底下的对死亡的恐惧就会自动浮现，That&#39;s the way it is。（笑）</p><hr><h2 id="page-138" tabindex="-1">第 138 页 <a class="header-anchor" href="#page-138" aria-label="Permalink to &quot;第 138 页 {#page-138}&quot;">​</a></h2><p>138 【2021.1.17 cap状态不是顶端，停留在cap会发展出 agflap,彻底释放三大欲望，才会自由】 风： 莱斯特经常说释放agflap，但是没有说释放 cap。 天成： 为什么会这样说？ 风： 因为cap是所谓的正面情绪：无畏，接纳，平静。 cap会吃掉agflap。在无畏下，你会自然倾向于做出好的 行动，在接纳中，你会接受原本的和谐和完美。 但是到达cap时，你不会去除所有的agflap。你必须 释放掉想要控制和认同才能去除所有的agflap。 这就像有很多人问，为什么cap要释放？因为它不是顶 端，cap是相对性的。 你即便到达了cap，在你释放掉三大欲望之前，你不会 彻底清除agflap。 因为cap是所谓的好的感受，而好的感受对应着不好的 感受。 对于好的感受，如果你想要控制它，就会发展恐惧—— 害怕失去它。你想要更多，就会发展贪求——想要获取更 多的好感受。</p><hr><h2 id="page-139" tabindex="-1">第 139 页 <a class="header-anchor" href="#page-139" aria-label="Permalink to &quot;第 139 页 {#page-139}&quot;">​</a></h2><p>139 如果不到顶端，agflap会被持续发展出来。除非你到 达涅比卡帕三摩地，让无限存在成为你永恒的认同，这个 时候，你就不会再发展agflap。 天成： 释放掉足够多的想要控制和认同，就可以到达涅 比卡帕三摩地吗？ 风： 还要释放死亡的恐惧。 天成： 要释放到接触到更底层的分离感才能到达涅比卡 帕三摩地？ 风： 释放掉你是这具身体的分离感，在你释放掉的那一 刹那，你会达到三摩地，因为你认同了无限存在。 处于cap时，只能说你目前的情绪状态达到了cap，可 以说你的垃圾清空到一定程度。 释放掉三大欲望，清楚所有的agflap。 那样你就自由了，自由了就可以主宰心智。 清除所有的agflap要达到波澜不惊，只是cap是不够 的。当你处在cap时，说明你还有与之对应的负面情绪在 极深处，但是在cap的状态下，你更有能力向下挖掘（dig down），去释放掉那些极深的感受。</p><hr><h2 id="page-140" tabindex="-1">第 140 页 <a class="header-anchor" href="#page-140" aria-label="Permalink to &quot;第 140 页 {#page-140}&quot;">​</a></h2><p>140 情绪能量表 情绪 万念俱灰（ A pathy） 悲痛 ( G rief) 恐惧 ( F ear) 贪求 ( L ust) 愤怒 ( A nger) 自尊自傲 ( P ride) 无畏 ( C ourageousness) 接纳 ( A cceptance) 平静 ( P eace) 100%－ 95% 94%－ 90% 89%－ 85% 84%－ 80% 79%－ 70% 69%－ 60% 59%－ 35% 34%－ 15% 14%－ 0% 0%－ 5% 5%－ 10% 11%－ 15% 16%－ 20% 21%－ 30% 31%－ 40% 41%－ 65% 66%－ 85% 86%－ 100% 压抑情绪所消耗的能量 余下可用能量 一曼注：agflap是情绪表中前六种情绪的英文首字母 缩写。当在释放法中提到“agflap”时，通常指消极情绪， cap代表情绪表中的后三种积极情绪。 从这个表格中我们也可以看到，为什么我们处于消极情 绪时感觉没有精力去行动，因为大部分能量都用来压抑情 绪了。</p><hr><h2 id="page-141" tabindex="-1">第 141 页 <a class="header-anchor" href="#page-141" aria-label="Permalink to &quot;第 141 页 {#page-141}&quot;">​</a></h2><p>141 【2020.1.11感觉没有感受/感受模糊不清怎么办】 风：所以我是不建议人们去把自己的经验总结成方法 的,永远要回到原始流程，完整的流程。 首先你要放松身体，一旦你发现自己在用力做释放， 需要停下来放松身体。因为很多人因为过去的错误习惯， 习惯了去用力。 释放时如果你试图找一种感受，那就是在逃避当下的 感受，你全天候二十四小时逃避着当下的感受。 释放不是一种需要你付出极大精力的活动，有人可能 因为以前错误的练习方式对释放有错误的概念。 接受不清晰的感受，不清晰的感受是一种感受，需要 认识到这一点。你不存在没有感受的时候，你只有不把感 受当感受的时候。 莱斯特专门提到这个vague feeling（模糊不清的感 受），模糊不清的感受是因为你在逃避感受，去感受你的 模糊不清吧。 没有感觉，是一个模糊不清的感觉，或者不明显的感 觉。去有意识注意你的模糊不清，先注意到它，不要那么急。 如果你去感受时，你的感受是&quot;没有感受&quot;，这时候不要 去找别的感受，只是允许这个&quot;没有感受&quot;在这里。先去</p><hr><h2 id="page-142" tabindex="-1">第 142 页 <a class="header-anchor" href="#page-142" aria-label="Permalink to &quot;第 142 页 {#page-142}&quot;">​</a></h2><p>142 注意这个&quot;没有感受&quot;，或者说空白的感受，有意识注意它， 直到你认出它是一种感受。 没有感受，模糊不清的感受，只是你在逃避感受而已， 它并不是真的没有感受。 你第一个被压抑的感受是死亡的恐惧（想要生存）， 然后发展了想要认同和控制，它们发展了九种情绪分类， 还有许许多多的个体感受。 释放法里面我们说情绪，指的是agflapcap那九种情绪。 我们说感受时，个体感受、情绪、欲望，所有的都是 感受。</p><hr><h2 id="page-143" tabindex="-1">第 143 页 <a class="header-anchor" href="#page-143" aria-label="Permalink to &quot;第 143 页 {#page-143}&quot;">​</a></h2><p>143 【2021.2.3 以轻松的心态释放】 风： 试着放轻松看看。 伯利恒之星： 好的。 风： 不需要让它变得很明显再释放。如果你把释放这 件事变得非常痛苦，那你当然就不想释放 伯利恒之星： 也是。 风： 带点探索的心态，轻松的心态。看看问句之后它 会发生什么。不要那么苦哈哈的（笑）。释放不是做作业。 伯利恒之星： 你真了解我，好，我试着轻松一些。 风： 比如一桌人坐着打麻将。有个人说“好像有一辆 凯迪拉克不错”。你一只手摸一张牌，一边随口说道&quot;这 样啊，那来一辆凯迪拉克&quot;。 嗯，好像有点感觉不可能？想要控制还是想要认同？ 貌似是想要认同。能够放它离开吗？好像能。 再check一下，好像轻松点了。我的凯迪拉克到了吗？ 我靠，还没到。这是想要控制和想要认同呢？就这样释放 啊（笑）。一边摸麻将一边就可以让凯迪拉克到手了。等 你打完麻将，释放得差不多了。出去一看，门口一辆凯迪 拉克。</p><hr><h2 id="page-144" tabindex="-1">第 144 页 <a class="header-anchor" href="#page-144" aria-label="Permalink to &quot;第 144 页 {#page-144}&quot;">​</a></h2><p>144 【2020.10.22当下更能觉察到哪个感受，就释放哪一个】 冰紫：三种欲望打包一起问可以吗？ 风：不可以。不是你打包就会更快一点。感受的原因， 当然是三种都有，因为认同是控制的原因，生存是认同的 原因，但是你释放的只是此刻你更能觉察到的那一个。 【2020.9.30从入门到最后释放什么】 风：释放情绪是学习释放法的入门，就是说，它让你 学会如何释放，熟悉释放的过程。熟悉之后，你就释放两 个想要（想要控制和认同）。等死亡的恐惧浮现，你就释 放死亡的恐惧。就这么简单。</p><hr><h2 id="page-145" tabindex="-1">第 145 页 <a class="header-anchor" href="#page-145" aria-label="Permalink to &quot;第 145 页 {#page-145}&quot;">​</a></h2><p>145 【2020.10.24清楚释放是什么感觉，就可以开始释放“想要”】 风：如果你一开始就能释放想要控制和认同，那当然 可以，但没有体验过释放的人很可能不知道什么是释放， 会把压抑当作释放，这时候需要从释放情绪开始体验。 等你掌握了这个方法，这个流程，六步骤就是你唯一 需要的指导了。</p><hr><h2 id="page-146" tabindex="-1">第 146 页 <a class="header-anchor" href="#page-146" aria-label="Permalink to &quot;第 146 页 {#page-146}&quot;">​</a></h2><p>146</p><hr><h2 id="page-147" tabindex="-1">第 147 页 <a class="header-anchor" href="#page-147" aria-label="Permalink to &quot;第 147 页 {#page-147}&quot;">​</a></h2><p>147</p><hr><h2 id="page-148" tabindex="-1">第 148 页 <a class="header-anchor" href="#page-148" aria-label="Permalink to &quot;第 148 页 {#page-148}&quot;">​</a></h2><p>148 【2020.11.27 释放感受不是允许接纳感受】 风： 允许感受浮现和离开的确是释放流程的一个简单 描述，因此在方法上，很多释放法练习者很容易会转变为 允许接纳。 不进入六步骤，就到达不了自由。 有一个东西，我们叫&quot;纯粹觉知&quot;，或者叫flow of awareness，莱斯特在早期所说的觉知之流，他描述的是 最终的存在的状态，很多种描述，但是抵达它的过程是严 密的。 当人试图内省时，或者只是安静的坐着，等同于试图 强行分开感官和生命力。人在达到pranayama这一阶段之 前，生命力是向外流的，向感官流动。 因此，当你在身体和心理层面的生命力（prana)没有 被你完全掌控之前，试图用头脑控制自己纯粹觉知，这是 无法奏效的。生命力向内流，感官自然关闭，这时候觉知 才有可能纯粹，以至于达到三摩地，两个阶段的三摩地。 六步骤是一个完整地图，其中任何一步没有做到都会 使你停滞。当人们在心智中认为自己保持在&quot;觉知&quot;中接 纳一切时，实际上已经停止了释放。丢掉了第四步的持续 释放。</p><hr><h2 id="page-149" tabindex="-1">第 149 页 <a class="header-anchor" href="#page-149" aria-label="Permalink to &quot;第 149 页 {#page-149}&quot;">​</a></h2><p>149 在焉： 生命力向内流，在释放法中是怎么达成的呢？ 风： 不断在起因层面释放想要控制和认同。因为你流 向感官=流向世界，世界=想要控制和想要认同。 如果你不断释放，生命力就会被完全控制，它不再向 外。 在焉： 感觉把注意力放在腹部，好像脊柱挺直，释放 更加顺利。 风： 释放实际上不需要固定姿势，把注意力放在感受 中心是对的。 在焉： 胸腹是指胸部和腹部的大片区域吧。 风： 就是瑜伽里的心轮。 在焉： 你进入三摩地，应该是非常深的入静状态。仅 仅是日常生活随时随地释放就可以达到吗？还是必须有一 定时间长度的安静集中释放才有可能进入？ 风： 三摩地有两种，一种是有种子的三摩地，一种是 无种子的三摩地。当你到达无种子的三摩地，就可以随时 进入，因为作为先决条件，身心的生命力已经被完全掌控 了 在焉： 可以详细说说吗？</p><hr><h2 id="page-150" tabindex="-1">第 150 页 <a class="header-anchor" href="#page-150" aria-label="Permalink to &quot;第 150 页 {#page-150}&quot;">​</a></h2><p>150 风： 只需要一个决定就可以进入。有种子的三摩地我 很早就达到过，在我中学修习帕奥禅法时，它把烦恼镇压 了下去。 瑜伽科学中说的涅比卡帕三摩地，是一个已经转向的 阶段，类似于佛陀说的预流，生命流向的转变，在莱斯特 那里，就是彻底达成第一步。 接下来你的每一个抉择都会自然是趋向自由的，只有 在这时，你才会从凡夫之流转到圣者之流，并且再也不会 退转，只有自由一个方向可以前行。 在焉： 怎么可以达成第一步，是一个意愿，还是释放 的结果？ 风： 是不断贯彻六步骤的结果，这可以通过the way 里面的一个指引，比如通过释放获得想要的一切。当你这 样做时，你会慢慢发现你在一切中想要寻找的都是快乐。 而快乐的唯一来源就是心智安静下来，让无限存在展现了 更多，因此你就会越来越趋向自由。 这时候你就会自然放弃其他方向的尝试，全部的生命 力都集中到一个方向，只留存一个目标，那就是自由，这 就完全达成了第一步，就会自然掉入后五步。</p><hr><h2 id="page-151" tabindex="-1">第 151 页 <a class="header-anchor" href="#page-151" aria-label="Permalink to &quot;第 151 页 {#page-151}&quot;">​</a></h2><p>151 【2020.10.23释放与体感无关，释放是释放心理感受】 美丽人生： 释放掉饥饿的感觉，就不用去吃饭了吗？ 风： 释放的不是饥饿的感觉，饥饿的感觉是身体感觉， 已经是结果了。 你要释放它的起因：心理感受，以及驱动它们的想要 控制和认同，以及驱动想要控制和认同的“对死亡的恐惧”。 想要生存的欲望就是对死亡的恐惧，对死亡的恐惧是 莱斯特经常用的词。 饿是一种身体感受，这其实已经是表达了，是一个结 果。当你释放了想要控制，可以随时关掉饥饿感。 again，身体感受，是一个结果，已经是表达了。 所以，我发现很多人对身体感受做释放，这不是释放 法。释放法释放的是feeling，是情绪，是驱动情绪的原 因——想要。 当你释放掉这些原因层面的东西之后，身体感受这种 结果层面的东西就会变化。 如果你对着结果——对着身体感受释放，你就会困难 重重，因为你无法通过砸镜子里面的人来改变姿势。 如果你想要改变身体的痛苦,释放想要改变（控制）。</p><hr><h2 id="page-152" tabindex="-1">第 152 页 <a class="header-anchor" href="#page-152" aria-label="Permalink to &quot;第 152 页 {#page-152}&quot;">​</a></h2><p>152 不用释放身体的痛苦，它是一个结果,如果你释放掉对它 的控制，它马上就会被纠正。 当你释放对死亡的恐惧时，会带出来痛苦的身体感受， 但是重心不是在释放身体感受上，而是放在你对它的情绪 和基本欲望上。 （风引用了一段the way part1里的对话） 学生：有一次我去操作释放这个对死亡的恐惧，我带 出了一些很沉重的身体疼痛，所以我一定是有什么做错了， 但是这花费了很长时间去搞定它。 莱斯特：你没有释放它，反而是把它在身体中表达了 出来，你在让你的身体走向死亡。痛苦是指向死亡的。所以， 你并没有释放它，而是让它表达在身体上。 美丽人生：释放了控制，病痛自动会消失了吗？ 风：释放了对它的所有心理感受，就不会表达在身体 上了。 痛苦实际上是对死亡的恐惧在身体中表达出来的结果， 也说是说，如果你压抑对死亡的恐惧，它就会在身体中表 达出来，形成痛苦的身体感受。但如果你释放了对死亡的 恐惧，它就会随之消散。所以，不要做六步骤以外的事。 除了想要控制和想要认同，以及之后浮现的对死亡的</p><hr><h2 id="page-153" tabindex="-1">第 153 页 <a class="header-anchor" href="#page-153" aria-label="Permalink to &quot;第 153 页 {#page-153}&quot;">​</a></h2><p>153 恐惧之外，你不需要释放任何其他东西，因为一切都是它 们三个的结果。 在释放完认同和控制之前，对死亡的恐惧会偶尔出来， 但不经常。 【注：莱斯特说，只要你持续释放想要认同和控制， 对死亡的恐惧（想要安全/生存）会自动浮现出来给你释放。 所以六步骤当中没有提到释放想要安全。】</p><hr><h2 id="page-154" tabindex="-1">第 154 页 <a class="header-anchor" href="#page-154" aria-label="Permalink to &quot;第 154 页 {#page-154}&quot;">​</a></h2><p>154 【2020.10.22要释放的是“原因”，不是释放“结果”】 风：身体感受已经是&quot;表达&quot;（expression）了。 第一个被压抑的是对死亡的恐惧，然后它发展了想要 认同。想要认同发展了想要控制，想要认同和想要控制发 展了九种情绪状态。 九种情绪状态发展了许多细微的感受，感受发展了所 有思想。思想投射出去就是你的物质世界，物质世界包括 你的身体，因此身体和整个物质世界，是你的&quot;造物&quot;， 是一个投射的结果了。 释放的时候，你释放的是作为原因的情绪、欲望，而 想要生存（对死亡的恐惧）是想要认同和控制的原因。 所有感受都是生存程序（ all feelings are survival programs ）。你释放的是情绪（feeling），而不是已经 作为结果而表达在身体上的身体感受。 当你释放掉情绪，你的那些疾病的身体感受也会随之 消散，因为你的身体仅仅是星光体的精确拷贝。 课程仅仅用两天时间让新人来熟悉释放情绪，情绪表 格是辅助你去辨认你的情绪。因为很多人除了身体感受， 无法辨认出自己目前的情绪是什么，因此他们需要表格的 辅助，很快你就可以过渡到释放欲望（想要）的阶段。</p><hr><h2 id="page-155" tabindex="-1">第 155 页 <a class="header-anchor" href="#page-155" aria-label="Permalink to &quot;第 155 页 {#page-155}&quot;">​</a></h2><p>155 想要控制和认同是一种限制你的感受，但有时 候我们就会这么愚蠢，我们宁愿要限制不要自由。 有时候你会卡住真的就是因为你不愿意释放它们， just want it 。 当你认识到想要控制和认同限制你时，你就更 想要自由。 ——风 2020.10.18 直接释放想要认同、控制，以至于想要生存（对死亡 的恐惧)，清理底层驱动，这个才是释放法这个工具的用法。</p><hr><h2 id="page-156" tabindex="-1">第 156 页 <a class="header-anchor" href="#page-156" aria-label="Permalink to &quot;第 156 页 {#page-156}&quot;">​</a></h2><p>156 2020.12.12</p><hr><h2 id="page-157" tabindex="-1">第 157 页 <a class="header-anchor" href="#page-157" aria-label="Permalink to &quot;第 157 页 {#page-157}&quot;">​</a></h2><p>157</p><hr><h2 id="page-158" tabindex="-1">第 158 页 <a class="header-anchor" href="#page-158" aria-label="Permalink to &quot;第 158 页 {#page-158}&quot;">​</a></h2><p>158 【2020.10.23 想要安全→想要被认同→想要控制】 风：想要改变是想要控制的一种。 如果一个东西你感觉很不喜欢，你就想要改变； 如果你感觉很喜欢的，你就想要维持、想要占有。 那都是想要控制。 想要控制的具体解释，就是&quot;你想要世界按照你想要 的那样来&quot;。 想要控制是最表面的想要。 你为什么想要占有这个、想要改变那个呢？ 因为想要得到认同。 为什么想要得到认同呢？ 因为想要安全。 你觉得别人认同你，你就能活下去了。 想要安全、生存是最深的那个想要。 想要生存发展了想要认同和想要控制。 想要认同和想要控制发展了agflap。</p><hr><h2 id="page-159" tabindex="-1">第 159 页 <a class="header-anchor" href="#page-159" aria-label="Permalink to &quot;第 159 页 {#page-159}&quot;">​</a></h2><p>159 【2020.10.18】 风：控制是好事情，想要控制不是。想要=匮乏，想 要控制，是对控制的一种匮乏感。 【2020.10.18】 风：持续释放那些你想做到的事情上的想要控制和认 同，然后你就达成了你想做的事。</p><hr><h2 id="page-160" tabindex="-1">第 160 页 <a class="header-anchor" href="#page-160" aria-label="Permalink to &quot;第 160 页 {#page-160}&quot;">​</a></h2><p>160 【2020.12.16释放了一切感受后，是超越一切的平静】 快乐时光: 释放掉了对身体的掌控是一种什么样的状 态？在此之前可有什么征兆？ 风: 释放对身体的掌控？ 快乐时光: 释放掉了一切感受的掌控。 风: 释放了一切感受吗？ 快乐时光: 嗯。 风: 超越一切的平静 ，那是不可描述的 ， imperturbability ，没有任何人事物可以打扰到的绝对宁静。 莱斯特说，在梵文里面它叫 Nirvana ，涅槃。在你通 过任何方法让心智暂时全部安静下来，能够短暂地接触到 它。这即是瑜伽科学里面所说的萨比卡帕三摩地。 但是在萨比卡帕三摩地中，种子的力量还存在，因此 还会退失。而当你达到涅比卡帕三摩地时，一切种子都失 去作用了，这时候你还有残存的业力，但是你消除它只是 个时间问题。 有的大师会选择把那些残存的业力保留更长时间，以 不断地回到世界上来帮助更多人，有的大师则会达成帕拉 穆克塔，成为一名悉达（完美的存在），直接融入无限。</p><hr><h2 id="page-161" tabindex="-1">第 161 页 <a class="header-anchor" href="#page-161" aria-label="Permalink to &quot;第 161 页 {#page-161}&quot;">​</a></h2><p>161 许韬： 这些是知识还是知道？ 风: 对你们而言是知识。 快乐时光: 其他的我就不懂了，傻傻的往前，持续释 放就可以对吧？ 风: 嗯，贯彻六步骤。 涅比卡帕三摩地在六步骤中，仅仅是第一步的完全达 成。随后工作才刚刚开始，你会掉入到后五步中去。 你的每一个选择、决定，都自然地趋向自由，因为种 子不起作用了，即意味着朝向世界的方向已经不起作用， 完全地朝向自由这一个方向。 宏: 辞职算这样的事吧？ 风: 不是，这和任何行动都不相关，这仅仅是你发现 了莱斯特所说的“快乐的唯一来源”，当你发现时，你就 可以调转方向。在方向的彻底调转时，你会进入所谓的涅 比卡帕三摩地。种子失去作用，意味着世界的方向完全失 去作用。 清溪: 是不是需要放下工作，还有离开人群？觉得在 人群中，人际关系交往中，心智就是活跃的。 风: 你想要压抑那些活跃的心智吗？</p><hr><h2 id="page-162" tabindex="-1">第 162 页 <a class="header-anchor" href="#page-162" aria-label="Permalink to &quot;第 162 页 {#page-162}&quot;">​</a></h2><p>162 宏: 我讨厌人际关系，我非常希望能过隐居的生活。 风: 那是“对世界的厌恶”。 清溪: 目前需要释放这些活跃的心智，但释放干净彻 底了，最终的走向会不会是上面提到的那样？离开人群？ 风: 这取决于你的选择，对世界的厌恶并不是想要自 由，要了解这一点。厌恶和贪恋是成对出现的，你对世界 有一个想要的贪恋，同时就会有厌恶。我发现有许许多多 的人，将“对世界的厌恶”当成是想要自由。 清溪: 哦，那就是当真正释放自由了，融入人群与离 开人群是没有区别的?无二无别，是这样吗？ 风: 无限存在的永恒宁静不会被打扰到。</p><hr><h2 id="page-163" tabindex="-1">第 163 页 <a class="header-anchor" href="#page-163" aria-label="Permalink to &quot;第 163 页 {#page-163}&quot;">​</a></h2><p>163 压抑的感受在潜意识中持续驱动着我们的潜意 识念头，mind is only creative，每一个念头都 会显化，不管你去不去看它。 潜意识念头仅仅是那些我们现在不去看的念 头，我们把它程式化，让它在后台自动运作。 所以，被压抑的感受也是你的感受，它依然会 驱动那些你不想看到的念头自动地在潜意识中运 作，因此，不要压抑感受，释放它们。 ——风 2020.10.22</p><hr><h2 id="page-164" tabindex="-1">第 164 页 <a class="header-anchor" href="#page-164" aria-label="Permalink to &quot;第 164 页 {#page-164}&quot;">​</a></h2><p>164 【2020.10.15 在日常生活中，每当我们使用身体/使用 感官时，就可以觉察背后的想要，释放它】 注：第三步对我们日常的释放是一个极大的提醒，在 移动身体、用身体操作某些事情、面对某些突发事件、产 生某些念头情绪等等背后，都必定有“想要控制/想要被 认同”这两个程序在运作。 看到所有感受都源自两个想要，随时发现，随时释放。 关于这一点，在日常生活中如何更好地实践呢？下面这段 分享也许能给你带来启发。 风： 我昨天还有个更深的体验，稍稍考虑了下，还是 分享出来。 那是在我去买水和食物过马路的时候，我发现自己下 意识地防卫，在更细微的层面上看到了自己的想要控制， 于是我释放了它。 持续释放了十几分钟，我自然地闭上了眼睛，一路被 一种内在的“知道”一步步指引，走回了家。 这种知道不是视觉，不是听觉，不是感官中的任何东 西，但是它比视觉、听觉更加周遍，只是一步步很笃定地 觉知，其中没有犹豫踌躇。 余生可贵： 是一种信任？</p><hr><h2 id="page-165" tabindex="-1">第 165 页 <a class="header-anchor" href="#page-165" aria-label="Permalink to &quot;第 165 页 {#page-165}&quot;">​</a></h2><p>165 风 ： 如果你说信任，这里面还有二元性，但那个感觉 并不是分离的。它是一个“知道”接着一个“知道”发生。 我知道我要往这儿走，我知道下一步要往那儿走。 今天我还在释放，因为早上我又用我的眼睛来工作， 但我发现我可以用觉知来工作。 现在大概是一半一半，有时候习惯性地用眼睛工作， 但是觉察到之后，释放掉我努力去看地想要控制，就能够 回到觉知工作。 我是无限： 你还在工作没闭关啊。 风： 我说的“工作”指的是看路，看东西，比如刷牙洗脸。 这里面的问题在于，这些真的是想要控制。当深入时，你 会接触到，甚至我看到我有意识运作了五脏。但这些东西 一开始不用被考虑，当释放了一些对死亡的恐惧时，我发 现对身体本身的控制就变得明显起来。 比如我一个简单的坐姿，坐起来，需要运用能量，需 要唤起控制。把身体维持，也需要唤起想要控制。 紫： 是不是头脑认为不控制就会死，因为怕死，所以 想控制？ 风： 嗯，最底层的，是想要生存。随着释放会越来越 清晰 我现在最大的问题是，很容易停止释放，要不断用</p><hr><h2 id="page-166" tabindex="-1">第 166 页 <a class="header-anchor" href="#page-166" aria-label="Permalink to &quot;第 166 页 {#page-166}&quot;">​</a></h2><p>166 六步骤提醒自己，否则就会进入一种觉知的状态，感觉周 围的事情都非常完美和谐。 每当这时候，就要提醒自己第一步，因为这个停止也 是因为想要控制。 繁星： 风，通过释放，你变得平静，安宁，舒适了吗？ 我们释放的目的是为了找回平安的自性对吧，而不是为了 释放而释放，保持不断释放的姿势。如果已经安宁了，又 为何非要强迫自己释放呢？不安宁才需要释放啊。 风： 每一次释放，你都会感觉更高，原来的平安只是 相对的。只不过到了一个舒适的阶段，你就会缺乏动力。 先前因为活在痛苦中，所以有强烈的动力释放。 在后来，就必须要加强第一步，为了自由而释放。莱斯 特有一篇音频 《 get high to release 》 ，专门批评过这种做法， 这样是永远达不到终点的，因为这样是为了 feel good 而释放。 当你感觉好的时候，你就停下来。停下来的时候，你 就在压抑，生存程序就会发展。如果你不是往自由的方向 走，就是往限制的方向走。 因此，莱斯特强调，要在你感觉很好的时候继续释放。 在很高的时候走得更高， higher and higher ，而不能停在当 下这个很完美和谐的感觉里。</p><hr><h2 id="page-167" tabindex="-1">第 167 页 <a class="header-anchor" href="#page-167" aria-label="Permalink to &quot;第 167 页 {#page-167}&quot;">​</a></h2><p>167 去听听那篇 《 get high to release 》 ，就明白了。 you don&#39;t have to wait you down then release ， get high to release 。 如果你感觉到平安，释放了那个&quot;平安&quot;，你会感觉 更好，试试看吧。 想要维持这个舒适，也是想要控制。 如果你不释放，你就在压抑，没有所谓的静止不动。 不在前进，你就在后退。 如果你不在undo你的心智，使它更安静，那么你的心 智就在变得更嘈杂。因此在到达终点之前，要一直持续释 放，make it constant，这正是第四步。 生存程序，就是你的感受，感受会驱动感受。如果你 压抑它、隐藏它；如果你不压抑它，就释放了。 如果你释放完了所有的感受，也就是生存程序，一切 就结束了，你就自由了。 这里面并没有一个需要停下来的中间点，所以有一个 学生问他应该如何如何的时候，莱斯特在音频里面说“ you stopped. There is no stop in the six steps. ” （风下面现场翻译了一段 《 get high to release 》 的话分享给 大家）</p><hr><h2 id="page-168" tabindex="-1">第 168 页 <a class="header-anchor" href="#page-168" aria-label="Permalink to &quot;第 168 页 {#page-168}&quot;">​</a></h2><p>168 有多少人是为了感觉好才去释放？你究竟要等多久？ 这就是你的问题所在，你没有去做它。 你们做的是什么？你只想停留在好感觉上，因此你只 会感觉不好之后再去释放，这样才能继续得到好感觉，因 为只有一种好的感觉，就是释放后的感觉。 过了一段时间，你再次感到不好，于是你释放以得到 好的感觉，反复如此拖延了整个过程。 如果释放的目的是自由，几个月的时间就足以清理所 有的垃圾。如果释放是为了摆脱困境，这样一来，就是一 个极其漫长的过程。 （注： 《 get high to release 》这 篇文章有非常好的 提醒作用，下面摘选一些文中的其他段落，感谢翻译者 Roller ） 一开始你没有选择，你深陷在沉重和痛苦的状态中， 你需要有从地狱中走出来的动机让你去释放。但是现在你 已经进步上升了，那应该成为过去。 释放的理由应该是去向自由。你所能得到的最高最好 最美妙的感觉与状态就是完全的自由。你相信吗？ 好吧，那你为什么不全力以赴到达最高的状态，去往自 由呢？那是因为你一直坚持着这个沉重的状态——“自我”。</p><hr><h2 id="page-169" tabindex="-1">第 169 页 <a class="header-anchor" href="#page-169" aria-label="Permalink to &quot;第 169 页 {#page-169}&quot;">​</a></h2><p>169 你无法快速摆脱困境的原因是，你释放后自己会感觉 良好，这会导致你在目标达成后停止释放。如果你为了自 由而释放，就不会停下来。你会珍惜你获得自由的一切机 会。每一次下跌对你来说都是一个绝佳的机会，每次跌落 （down）都是释放和上升的绝佳机会。 你没有落入到这六步骤的后续步骤，因为你遗漏了第 一件事——想要自由，相反的而是想去满足自我，满足“我” 这自我感。 你并不想自由，这就是为什么现在你们都还没走完全 程的原因。 追逐外在世界的美妙状态，每当获得一分的快乐，你 就会得到一分接着又一分的痛苦。如果你看一下，这是如 此明显。 每天都在向你证明，你的幸福并不是去满足心智，你 不会赢！通过满足心智（body-mind）的每一分幸福，你 都会遭受极大的痛苦！每一个想法都有附着一定的痛苦。 为什么？它把你的注意力从你的存在中移开。当你心智安 静时，你将身处最美好的地方。 因此，我建议你从现实中醒来。 Release when you’re high 。 应该用大写的字母写在你的笔记上： RELEASE WHEN HIGH. GO HIGH TO RELEASE. （在高处释放，到 达高处继续释放）</p><hr><h2 id="page-170" tabindex="-1">第 170 页 <a class="header-anchor" href="#page-170" aria-label="Permalink to &quot;第 170 页 {#page-170}&quot;">​</a></h2><p>170 所有被抑制的能量现在都在试图冲出来（push up）， 而你试图将其抑制下来。停止按住它，它每一点都会释放 出去，它会马上排出去。压制它是坚持自我程序。 自我感包含所有喜恶，所有思想。你必须将注意力从 它上移开，并将其放在存在上。 Release when you’re high 。 我们状态越高，我们就 越接近我们的存在。 高峰状态与宁静是同一件事。 当你 go high 时，你就充满了能量。在万念俱灰、悲 观的状态时，你只有很低的动力。 往上（ Up here ），你的动力、能量可以达到高峰。因此， 进入该区域，然后挖掘出对死亡的恐惧。 往下（ Down here ），你会继续深陷其中，无法放手。 往上走，你可以面对死亡的恐惧。而且，当你释放了大部 分的恐惧时，就可以相对轻松地释放剩余部分。去释放吧。 如果我前一段时间对你说过这些话，那将毫无意义， 因为你陷于 AGFLAP 中，以至于看不清东西。你唯一看 到的是 AGFLAP 。</p><hr><h2 id="page-171" tabindex="-1">第 171 页 <a class="header-anchor" href="#page-171" aria-label="Permalink to &quot;第 171 页 {#page-171}&quot;">​</a></h2><p>171 但是我们每个人都已经进入这个领域，知道自己的感 觉，可以置身其中，然后深入挖掘并面对对死亡的恐惧， 不安全感和对生活的恐惧。 这样一来，你将摆脱所有恐惧。 恐惧是不自然的。永恒的生命有什么要担心的，尤其 是关于死亡的恐惧。因此，从这里开始，重点放在这里。 Feel high，然后挖掘对死亡的恐惧并释放它。 心智（头脑）必须安静下来，然后你才能认同自己的 存在，这就是终极状态。 这就是我今天想对你说的。滚出坑，上升，完成过程！ 只需要几个月或更短的时间。如果第一步达到——想要自 由多于你想要满足自我，那么其他步骤就可以实现，然后 你会一直贯彻六步骤。 这令人相当振奋，因为你会越来越高，直到无法再高 为止，无处可去——你遍及整个宇宙，你是无限的。简单 来说，就是会认同自己的存在，“我是我”（ I-am-ness ）。 然后，你将看到整个的全部真相。只有我的存在。其他一 切都是想象力，是一种幻想。 所以，我说，释放吧。记在心上： Go high and release 。（去到高处并持续释放）</p><hr><h2 id="page-172" tabindex="-1">第 172 页 <a class="header-anchor" href="#page-172" aria-label="Permalink to &quot;第 172 页 {#page-172}&quot;">​</a></h2><p>172 当然，如果你正处于低谷，请释放以升高，以便更深 入地释放。不要停留在那里，从那里继续前进到达更高处。 （move on from here to higher.） 不要停下来，往高处走，利用高峰（highness）释放， 直到无处可去；你遍布整个宇宙。</p><hr><h2 id="page-173" tabindex="-1">第 173 页 <a class="header-anchor" href="#page-173" aria-label="Permalink to &quot;第 173 页 {#page-173}&quot;">​</a></h2><p>173</p><hr><h2 id="page-174" tabindex="-1">第 174 页 <a class="header-anchor" href="#page-174" aria-label="Permalink to &quot;第 174 页 {#page-174}&quot;">​</a></h2><p>174</p><hr><h2 id="page-175" tabindex="-1">第 175 页 <a class="header-anchor" href="#page-175" aria-label="Permalink to &quot;第 175 页 {#page-175}&quot;">​</a></h2><p>175 （注：关于“不要释放到好状态时就停下来”，在此 插一段风在2020.9.20的分享，以提醒我们。此时风还未 进入极佳的持续释放阶段，很快他在一周后就有了突破。） 风：我记得两年前吧，那是我的高峰期，我觉得大概 大部分时间都处于cap里面，但是我知道下面还有很多垃 圾没释放，不想去看那些。 后来停止了很久很久，就是不想释放。还是没有下决 定，一次性走到终点，想待在那种美好的状态里，然后很 快那些负面情绪就回来了。 停止释放后，这个比较好的状态只持续了几个月就回 到了原状，头脑又变得很嘈杂。 但我现在的感受很不好，因为以前经历过一个相对高 的状态，所以掉下来之后，每天都在煎熬，难受得很。 说个粗俗的比喻，就像猪圈里的猪，吃过新鲜饭菜之 后就不觉得泔水好吃了，再回来吃泔水就比先前不知道有 新鲜饭菜时难受很多。 我总是会停下来，但是我确实意识到了头脑是个垃圾 堆。如果一辈子活在头脑里，简直太悲惨了，来来去去都 是相同的欲望和反应啊，非常程式化。</p><hr><h2 id="page-176" tabindex="-1">第 176 页 <a class="header-anchor" href="#page-176" aria-label="Permalink to &quot;第 176 页 {#page-176}&quot;">​</a></h2><p>176 【2020.10.18 通过释放想要，获得想要的一切】 注：一般我们提到“仅仅通过释放获得一切”，对于“一切” 的理解，我们可能往往想的是这些诸如此类的事情，比如获得 金钱，得到某个物品，身体恢复健康，学会一门外语，获得某 项才艺技能，获得某种超能力等等…… 其实“一切”并不只是指一个阶段性的目标，你可以 在任何大大小小的事情上放大对“一切”的觉察力，因为 我们每一刻其实都有想要做到的事情，就像仅仅只是抬一 下胳膊，关一下灯。 我们可以通过释放毫不费力让胳膊自动抬起来吗？下 面风引导群友释放的对话，也许能给你带来“通过释放获 得想要的一切”启发。 JianWang： 风，莱斯特用举手来说明 “get everything by releasing only” ，这个你做个示范说明吧。 风： 你想试试吗？你现在就可以试试。你想做到什么？ 下一件你想做的事是什么？ JianWang： 就比如“举起手”。 风： 嗯，你能看到这是想要控制还是想要认同吗？ JianWang： 控制。</p><hr><h2 id="page-177" tabindex="-1">第 177 页 <a class="header-anchor" href="#page-177" aria-label="Permalink to &quot;第 177 页 {#page-177}&quot;">​</a></h2><p>177 风： 放它离开了吗？ JianWang： 能。 风： 还有吗？ JianWang： 还有。 风： 觉察到更多。它离开了吗？ JianWang： 更多精细的出来了。 风： 嗯，持续释放它们你有看到随着释放，你越来越 不是个“行为者” （注：doer，也译为“做者”） 吗？ JianWang： 慢慢举手动力越来越强，可以了，他自然 的举起来了。 风： That&#39;s it。任何事，你通过释放来做到。这就 是get everything by releasing only。字面意思。 JianWang： 一举一动皆有“控制”。</p><hr><h2 id="page-178" tabindex="-1">第 178 页 <a class="header-anchor" href="#page-178" aria-label="Permalink to &quot;第 178 页 {#page-178}&quot;">​</a></h2><p>178 【2020.9.21如何对目标做释放】 风：关于目标，第四个视频的讲法是这样的： 写出你的目标（以现在时）， 然后看着你的目标， 释放你对目标的第一感受， first feeling。 好了，完了，就这么简单。 第一感受释放掉了，再看看你的目标，再释放此刻的 第一感受，直到你感觉目标已经实现，注意是“已经实现”。 其实上面我已经复述出几乎全部内容了，剩下的就是 重复引导，原始的释放法真的很简单。 我以前设定过目标释放很多次，现在我很少设定目标 了，因为我发现没有什么真正想要的。 我说一下自己关于目标的经验，“目标是可以让你持 续释放的一种方法。你看着目标，只要不欺骗自己，就会 有大量“不可能”之类的感受涌现。当然也有一些愤怒、 悲苦之类的。五花八门的情绪。 按照流程一个个释放。 释放之后，有一种清晰笃定的感觉，“知道”它就是我的。</p><hr><h2 id="page-179" tabindex="-1">第 179 页 <a class="header-anchor" href="#page-179" aria-label="Permalink to &quot;第 179 页 {#page-179}&quot;">​</a></h2><p>179 就是看着目标，冒出一个情绪释放一个，再看看目标， 它有没有到“已经实现”的状态。如果没有，那一定是想 要控制和想要被认同（情绪上是无能为力、贪求、愤怒、 恐惧等等），再释放最上面的感受，一个一个来，直到全 部清空。 我个人的经验是，这样持续下去，你会到达一个“我 很自信目标能成功”的状态，但是这个状态不行，这应该 处于自尊自傲和无畏上下，这个状态还是要释放。 目标流程我检验过很多回，一般来说，这个“我相信 肯定会实现”的情绪下面还有很多潜意识情绪，释放之后 又会有不少涌现出来。 真正的目标完全释放是什么感受呢？是那一刻“知道” （不用思考、不用相信）目标已经是我的了，非常清晰笃定， 仿佛它就在我面前了。你这时候不会想做任何事去得到它， 因为完全确认它已经是我的了。这时候我一般不会再想它 了，会做其他事情去，接着它自然就来了。 这个目标流程几乎百试百灵，可以从小事上开始。莱斯 特说，如果你不能成为赢家，那个挫败感就会一直伴随你。 所以一旦设定目标，你就必须达成它。因此一开始不 要设定得太大，让你望而却步，通过实现小目标积累释放 的动能。每一次成功，把收获写下来，这样你就会越来越 会运用目标流程。</p><hr><h2 id="page-180" tabindex="-1">第 180 页 <a class="header-anchor" href="#page-180" aria-label="Permalink to &quot;第 180 页 {#page-180}&quot;">​</a></h2><p>180 我是无限： 我真正通过释放没有实现任何事情。 风： 我之前也是。后来听了莱斯特的音频，发现我有 一个限制性观念，“我不可能对一个目标释放到它实现”。 这背后伴随着以前的挫败感，莱斯特在winner那个 视频里是这样说的“你必须做赢家，哪怕只是为了勾出潜 意识中的嗔恨，你也要做赢家”。不应该把那个“挫败感”， 那个“我不能”的感受保持在潜意识内。 因为我发现一开始做释放，大家都野心勃勃想要去实 现目标。在此之后就发展了一个想法，“太执着目标容易 让释放卡住”，是不是多数人都有过这个想法? 后来我才知道，这个限制性观念是错误的，你这其实 是在说，“我不能实现目标”，而“我不能”是一种挫败感， apathy。个体在实践途中，会发明很多限制性的说法，而 这个莱斯特都没有说过。所以在后期音频中，我看到莱斯 特经常纠正学生的限制性的说法。 所谓的“目标会阻碍你释放”，其实不是这样的，是 你的挫败感（无能为力感）在阻碍你的释放。 目标设定是sedona method流程的一部分，它的目的 是为了勾出被你隐藏起来的情绪和基本欲望。 一个真正体验到完美和无欲的人当然是另一回事，但</p><hr><h2 id="page-181" tabindex="-1">第 181 页 <a class="header-anchor" href="#page-181" aria-label="Permalink to &quot;第 181 页 {#page-181}&quot;">​</a></h2><p>181 是如果一开始释放时回避目标、想要这些东西，并不是在 释放它，而是不想看它，把它压抑到更深处。 莱斯特的释放法已经形成一个非常实操的循序渐进的 体系，在释放法中介绍了一些你可能用到的工具。目标这 个工具的目的是让你压抑的感受浮现。在你慢慢改变了这 个习惯之后，释放了关于目标的挫败感，你就不需要专门 设定目标了，但是“改变你的不能够，使之成为能”，这 件事很重要。 看看目标背后的情绪，上溯到想要控制和想要被认同， 仅仅是让它浮现，让它离开，重复这个流程。这些流程的 设计是为了帮助你持续释放。 所谓目标流程，是一种对潜意识中压抑的情绪和欲望 的勾起。如果你本身就处在一个非常困扰的情绪中，它非 常明显，那你先不用操作目标流程，释放你能够觉察到的。 释放就好了，形而上的讨论其实帮助不太大。释放， 就能清晰地知道是怎么回事。我的意思是智性问题，那些 问题只是在试图用一种知识的说法来填补你的知识。在释 放法这个完整体系中，所有问题都可以通过释放解决。 对形而上的讨论，应该这样说: 无论我们对“真理” 下多少定义，它都不是真理本身。通过释放，然后亲自体 验它，这比用心智去讨论一万遍都要有用。</p><hr><h2 id="page-182" tabindex="-1">第 182 页 <a class="header-anchor" href="#page-182" aria-label="Permalink to &quot;第 182 页 {#page-182}&quot;">​</a></h2><p>182 【2020.12为目标定一个不超过两周的释放时间】 风：定个一两周的目标吧，历时太长的目标会让你失去 动力，而且实际上处在拖延之中。 不可能的感觉，是你处在agf的情绪状态中，它背后有 想要控制，也有想要认同和安全。 达成一个极小的目标，不超过十几分钟。 达成一个一般的目标，半天时间也就够了。 达成一个你认为的很难的大目标，需要多长时间？我认 为不超过一个星期。 如果一个星期做不到，是你没有真正地运用六步骤。 所以，不要拿自己开玩笑。 easy or impossible ， 简单， 或者不可能。能够理解这个概念吗？ 时代万物互联:只有这两种选择。要么简单，要么不可 能没有第三种。 风:嗯。 Cynthia:您说的这种释放是持续释放吧，一周达成一 个很难的目标，这一周应该是持续不间断地释放吧。 风：持续不断是关键。</p><hr><h2 id="page-183" tabindex="-1">第 183 页 <a class="header-anchor" href="#page-183" aria-label="Permalink to &quot;第 183 页 {#page-183}&quot;">​</a></h2><p>183 【2020.11.23当目标到期失败后，释放挫败感】 风：目标设定的一个重大目的，就是为了把这些压抑的 挫败感勾出来。 所以我甚至建议当你到期失败了，就写上失败，面对积 压的挫败感，进行释放。 你无法把那些反对程序压抑在潜意识中的同时获得成 功。无法实现一定你内在还有程序反对它，仅此而已。 先前你保持在潜意识的挫败，你是看不到的，现在就看 到了。因此通过目标设定勾出这些挫败感是好事。当挫败 感浮现出来，你可以决定释放或者把它们压抑回去。我决 定释放它们，聪明一点。 如果你不把它勾出来释放，你就永远没有实现目标的能 力。因此，即使你抵触它，也要定目标，这很简单。 你逃避看它，它就一直待在里面运作。 【2021.1.3】 先达到目标，要不然，你很难下决心去自由。</p><hr><h2 id="page-184" tabindex="-1">第 184 页 <a class="header-anchor" href="#page-184" aria-label="Permalink to &quot;第 184 页 {#page-184}&quot;">​</a></h2><p>184 【2020.11.24对于失败的目标，可以再当一个新目标释放】 风：（如果目标到期没有实现），那得写下失败，然后 对挫败感做释放。 再定一个新的目标，可以是同一个目标，但是要以新目 标的态度去对待它，就像你第一次面对那个目标一样，否 则你就会破罐破摔，会拖延。</p><hr><h2 id="page-185" tabindex="-1">第 185 页 <a class="header-anchor" href="#page-185" aria-label="Permalink to &quot;第 185 页 {#page-185}&quot;">​</a></h2><p>185 【2020.11.24要对目标释放到什么程度——释放到你感 觉目标已经实现，非常清晰笃定，完全确认它已经是我的了】 风： 给点力，先实现个目标出来。 Go All The Way: 现在在万念俱灰，什么都不想做 （笑），就想着拖一拖，晚上释放吧，就是不是现在。 风： （笑） Go All The Way: 我以前释放基本不困，就是闭关第 一天特别困。 风： 你知道为什么吗？ Go All The Way: 为什么？ 风： 因为你在逼迫自己释放（笑）。逼迫，头脑就会反抗， 反抗的方式就是犯困。当你试图郑重其事地做一次大的释 放时，就是这样。你非要摆出一幅“准备好了啊，我要开 始释放了”的姿态，头脑当然会反抗。 我是无限： 比如我一个锅的目标，我就能接受，就 500块嘛，实在不行，十块钱，再不行一块钱吧。 我是无限： 我觉得我的挫败感不是很强，去释放也挺 好释放的。 风： 不是习惯了吧。</p><hr><h2 id="page-186" tabindex="-1">第 186 页 <a class="header-anchor" href="#page-186" aria-label="Permalink to &quot;第 186 页 {#page-186}&quot;">​</a></h2><p>186 伯利恒之星： 破罐子破摔了。破罐子破摔只是逃避而已， 只要我逃避，我就不会尝到失败的痛苦。不能让失败成为 习惯。 风： 完全释放的感受是，你会完全知道它是你的了。 然后你会自然地放下它，你的心智不会再围绕它，然后它 就来了。你会在此刻看到、品尝到你想要的，因为你无比 确定你已经拥有了。所以你不会再有期待，因为你已经得 到了，你会很自然地享受完然后把它放下。 对一个目标完全释放的感觉并不是你相信它未来会到 来，而是你此刻就看到它是你的了，你知道它是你的了， 这才是完全释放。 我估计大部分人都没有体验到这种对目标的完全释放。 他会“知道”自己已经有个锅，不会有任何怀疑，因为他 知道了。</p><hr><h2 id="page-187" tabindex="-1">第 187 页 <a class="header-anchor" href="#page-187" aria-label="Permalink to &quot;第 187 页 {#page-187}&quot;">​</a></h2><p>187 【2020.11.24目标释放要释放到清晰知道“现在”彻底 实现】 风： 你想到你自己拥有的车是什么感觉？尽管你现在没 有去看它，但你清晰地笃定它就是你的。 倚天： 心智不再围绕它，就是真正放下了？ 风： 这里的心智不再围绕它的意思，是没有勾子。即使 你现在有意识去想它，你会马上察觉，&quot;哦，它已经在那儿 了&quot;，然后就会自然放下它。 目标释放达到这个程度，你才有主动性。你不是在那儿 可怜巴巴地做释放，然后张望一下“上帝有没有赐予我？ 我有没有完全交托？”，而是释放到它掉到你的膝盖上。 伯利恒之星： 必须要有主动性，不是等待。 风: 就像假设你有一个女朋友,你每天醒来的时候，你 也没有看到她,但是你知道她是你女朋友。所以我每次问“目 标搞定了吗？”，并不只是说实物有没有到，我是在问你 的目标完全释放了吗？有没有清晰地知道？ Roller： 如果还有一丝怀疑不笃定，就是不完全。 风: 嗯，首先你要有意图，然后释放关于它的所有感受， 你就得到它了。</p><hr><h2 id="page-188" tabindex="-1">第 188 页 <a class="header-anchor" href="#page-188" aria-label="Permalink to &quot;第 188 页 {#page-188}&quot;">​</a></h2><p>188 我是无限： 我觉得它会来，但是觉得不会现在就来，会 拖几天。 风: 那不对。 伯利恒之星： 就得现在。不管你在哪里，现在就得实现。 风: 你的心智让它待在了未来。我告诉你为什么。因为 心智是不会区分时态的，心智是以图像的形式思考。 因为心智以图像的形式思考，所以当你说“会来”的时 候，呈现的画面就是“没有”。 你必须释放到“已经有了”，才会在物质世界显化出来。 伯利恒之星： 所以只有有或者没有。你这次解释得够清 楚，我之前没有完全明白。 风: 心智只是以图像的形式思考，创造以光束发生，以 一帧帧图像的形式发生，所以我们的世界荧幕看上去是连 续不断的。</p><hr><h2 id="page-189" tabindex="-1">第 189 页 <a class="header-anchor" href="#page-189" aria-label="Permalink to &quot;第 189 页 {#page-189}&quot;">​</a></h2><p>189 【2020.11.24目标是为了勾出你对世界的厌恶】 伯利恒之星： 刚才释放了很多东西，控制和认同，我觉 得一定要为了自由去释放，而不是让生活好一点。 Roller: 对，让生活好一点很容易停下来。 伯利恒之星： 我们释放去实现目标，不管是女朋友，钱 还是锅，目的不是生活好一点，因为那是不够的，真的是 要为了自由。把生活变好一点反而复杂化了，而且肯定得 花多得多的时间。 风: 目标是为了勾出你对世界的厌恶。物质世界有什么 好的，这个车架子有什么好的，（笑）物质世界没有什么 是特别好的。 伯利恒之星： 就是，没什么好的。莱斯特留下来不是这 里很好，而是让大家提升到他的层次。 Roller: 先超越物质世界吧。 伯利恒之星： 这是一定要的（笑），不然只是空谈。 Roller: 我看我好多朋友一个个沉醉于纸醉金迷。 风: 不过，你还是得达成目标，对自由的渴望不是建立 在对世界的厌恶上。 伯利恒之星： 对，一定要master这个世界。</p><hr><h2 id="page-190" tabindex="-1">第 190 页 <a class="header-anchor" href="#page-190" aria-label="Permalink to &quot;第 190 页 {#page-190}&quot;">​</a></h2><p>190 Roller: 嗯啊，必须成为一个赢家，不然就被这世界 push着。 伯利恒之星： 所以我们的目标一定得实现，作为自由的 战利品。 Roller: 必须实现。我的膝盖可以承受。 伯利恒之星： 风，即使通过 get very thing by releasing 你 也不需要超过3个月对吧。 风: 只要你在六步骤上。 get everything by releasing only 是一个很好的操作六步骤的方法。 Roller: bravo，毕竟是莱老最喜欢的教导。 伯利恒之星： 嗯嗯，你会一直去实现实现实现。 风: 莱斯特说了，因为你一直有想要，你想要这个，想 要那个。你不会停下来，所以你也不会停下释放。 Roller: 我还想学会弹钢琴，学会弹奏久石让的。确实 好多想要的，全部通过释放get。 伯利恒之星： 我觉得释放目标这个方法最适合我们。 Roller: 是的，这样你才有动力去做释放。不然你就一 直只想要好感觉。</p><hr><h2 id="page-191" tabindex="-1">第 191 页 <a class="header-anchor" href="#page-191" aria-label="Permalink to &quot;第 191 页 {#page-191}&quot;">​</a></h2><p>191 伯利恒之星： 不然你就去忍受当个失败者了。最失败的 事情就是这个，明明我们能做到，还要去当个失败者。 风: 把目标释放到完全实现的过程，是很美妙的。（笑） 伯利恒之星： 那我们去体验吧。（笑） 风：你只是释放、释放，看着它一点点变清晰，看着 所有不可能灰飞烟灭。</p><hr><h2 id="page-192" tabindex="-1">第 192 页 <a class="header-anchor" href="#page-192" aria-label="Permalink to &quot;第 192 页 {#page-192}&quot;">​</a></h2><p>192 【2020.3.11要重视外部确认，内在发生真正的改变， 外在也必然随之改变】 风: 此外，我要强调一件和目前世界上的灵修圈所告诉 你的完全不同的事，这件事是，你要重视外部确认。 第一步，掌控世界(mastering the world)，然后， 掌控心智(mastering the mind)。 如果你此刻感觉很好，但你对世界无能为力，那么你 的潜意识中正压抑着那些agflap。因此，莱斯特的教导要 重视外部确认。这几乎是被他后来所有的学生都忘记了的 一件事。 大黄猫： 外部确认是什么？还是不太明白。 风: 想一想，事情就发生。一个毫不费力的念头，事 物就出现在那里，就像梦境那样。 通过释放，不要妥协。 自由的第一步是掌控世界，然后你释放关于世界的贪 恋和嗔恨。可是如果你做不到，你把“我不能”藏在潜意 识里，你就无法自由，你必须做胜利者。 这是莱斯特和学生反复强调的一点，但他的大部分学 生都妥协了。</p><hr><h2 id="page-193" tabindex="-1">第 193 页 <a class="header-anchor" href="#page-193" aria-label="Permalink to &quot;第 193 页 {#page-193}&quot;">​</a></h2><p>193 我之所以说要重视外部确认，是因为有许多人把一种 表面很好的感觉当作自由。他们的世界并没有变化，因为 潜意识还保持着那些画面。 一个真正改变了心智的人，他的世界必然发生改变， 因为世界是什么?世界仅仅是你的一堆想法的投射而已。</p><hr><h2 id="page-194" tabindex="-1">第 194 页 <a class="header-anchor" href="#page-194" aria-label="Permalink to &quot;第 194 页 {#page-194}&quot;">​</a></h2><p>194 关于目标释放</p><hr><h2 id="page-195" tabindex="-1">第 195 页 <a class="header-anchor" href="#page-195" aria-label="Permalink to &quot;第 195 页 {#page-195}&quot;">​</a></h2><p>195 【2020.10.18 持续释放，没有停止】 风：第四步，就是持续释放。持续的意思就是持续。 你做第一次，然后能做第二次、第三次、第四次……直到 最后一次达到自由。 莱斯特说 “ there is no stop in the six steps ” ,并没有 一个“停止”在六步骤里面。持续的意思就是持续。 【2020.10.24持续释放，让它成为像呼吸般的常态】 风：我解释一下第四步， make release constant 。 因为你们直到现在为止，压抑才是常态。 风谈六步骤 Step 4 第四步: 持续释放。 Make release constant.</p><hr><h2 id="page-196" tabindex="-1">第 196 页 <a class="header-anchor" href="#page-196" aria-label="Permalink to &quot;第 196 页 {#page-196}&quot;">​</a></h2><p>196 所以你们会问“这个需要释放吗？那个需要释放吗？” 你需要问“我需要呼吸吗？”这样的问题吗？你为什么不 问“这个我需要压抑吗？” 因为压抑是你的常态，释放反而成为了你的变态。你 需要让释放成为每时每刻的常态，就像呼吸一样。 呼吸一开始也不是自动进行的，包括你身体的五脏， 起初你都是有意识运作，随后才交给程序自动运作。 不一定要什么事都不干，但是释放不能停下来。一旦停 下来一次，就像飞机助跑停下来，你需要再次让它跑起来。 莱斯特说的，让释放成为常态，让它变成你的新习惯 （ make release constant,let it become your new habit. ） 你先把所有能够释放的时间拿来释放吧，接着，你就 发现你不需要“做什么”，事情会自然发生。你看着身体 移动，因此你能一直释放，而不需要分心去操作身体做事。 释放，就是让感受浮现离开。释放一次，有新的感受 涌现出来，你接着释放第二次，这叫持续释放。如果你此 时没有让感受离开，而是把它压下去，这叫停下来，这点 很简单。 有没有在持续释放，你自己就能知道。</p><hr><h2 id="page-197" tabindex="-1">第 197 页 <a class="header-anchor" href="#page-197" aria-label="Permalink to &quot;第 197 页 {#page-197}&quot;">​</a></h2><p>197 【2020.11.28 释放一次一次又一次，整天不间断地让感受浮 起浮出】 风：所谓持续释放，就是你释放了一次，再释放一次， 然后再释放一次。卡住也是一样，每一次卡住，你都想要 控制，你就释放想要控制。把每一次卡住当成第一次卡住 来释放。 如果你真的这样持续释放，到达一个阶段，当你50% 以上的时间都用来释放，你会发现它超过了压抑的习惯。 当它成为你新的习惯，你就会发现释放和呼吸一样自 然。这个和呼吸一样自然仅仅是比喻，并非让你随着呼吸 释放。 莱斯特有描述： 即使你与他人在一起，你也可以一直，整天不 间断地持续释放。你们可能都经历过（感受）不断的浮起浮出，浮 起浮出的状态（ You&#39;ve probably experienced the state where it comes up and floats out, comes up and floats out. ）。必须达到， 做到这一点。 真的，有太多的“垃圾”了。偶尔的释放也会有所效益。但是， 如果你想将其全部释放掉，大量的释放，持续的释放，看看六步骤吧。 你必须让释放保持持续。整天都不断地让（感受）上浮起，排出去。 你觉察到某种感觉并将它释放。这有点像你坐着观看到它，看它不断 进行着。 浮出来，浮出去（comes up and floats up）。 浮出来，浮出去，不会停下来。</p><hr><h2 id="page-198" tabindex="-1">第 198 页 <a class="header-anchor" href="#page-198" aria-label="Permalink to &quot;第 198 页 {#page-198}&quot;">​</a></h2><p>198 【2020.10.23 释放感受，再接着释放感受，当释放感受 成为常态，感受就会像波浪一般不断浮现并离开】 在焉： 风，你平时释放就像呼吸一样，还用问自 己“能让它离开”这样的问题吗？还是直接释放？ 你平时的释放是像一直在放松的状态一样吗？ 风： 在第二个星期的时候，感受就会不断浮现出来， 然后离开，像波浪一样。 但是当我停下来时，瞥一眼六步骤，立即就会知道自 己哪一步有问题，于是释放就又立即进行了。流程并没有 改变，只是它变得更直接了，操作更少了。 我感到自己一直在六步骤上，而这六步骤形成一个巨 大的推动力，让释放持续下去。领悟频繁发生，这时候你 会被它们带着走，但只要继续提醒自己六步骤，就会继续 释放，达到更高的高峰。 Susan: 不需要特定想起某事来激发情绪吗？ 风：不需要。六步骤里面没有的，都不需要。注意到 第三步是&quot;所有感受都是想要控制和认同，释放它们&quot;， 所有感受的意思就是所有感受。你现在一定有感受，它一 定是想要控制和认同，你就一定可以释放它们。 任何时候你都可以用这个方法，很简单，进入六步骤。</p><hr><h2 id="page-199" tabindex="-1">第 199 页 <a class="header-anchor" href="#page-199" aria-label="Permalink to &quot;第 199 页 {#page-199}&quot;">​</a></h2><p>199 第三步，此刻你的感受是想要控制还是想要认同？释放它们。 第四步，持续释放，让它成为常态。 当你释放一次，你的感受上升了，这时候涌现出新的 感受，它还是一种感受吗？ 当然还是。 它还是想要控制和认同吗？ 当然也还是。 因此，你可以继续释放下去。 再释放，你的感受再次上升。涌现出的感受依然是想 要控制和认同，你依然可以再次用流程释放，就是这样简 单。</p><hr><h2 id="page-200" tabindex="-1">第 200 页 <a class="header-anchor" href="#page-200" aria-label="Permalink to &quot;第 200 页 {#page-200}&quot;">​</a></h2><p>200</p><hr><h2 id="page-201" tabindex="-1">第 201 页 <a class="header-anchor" href="#page-201" aria-label="Permalink to &quot;第 201 页 {#page-201}&quot;">​</a></h2><p>201</p><hr><h2 id="page-202" tabindex="-1">第 202 页 <a class="header-anchor" href="#page-202" aria-label="Permalink to &quot;第 202 页 {#page-202}&quot;">​</a></h2><p>202</p><hr><h2 id="page-203" tabindex="-1">第 203 页 <a class="header-anchor" href="#page-203" aria-label="Permalink to &quot;第 203 页 {#page-203}&quot;">​</a></h2><p>203 ——风 2020.10.8</p><hr><h2 id="page-204" tabindex="-1">第 204 页 <a class="header-anchor" href="#page-204" aria-label="Permalink to &quot;第 204 页 {#page-204}&quot;">​</a></h2><p>204 【2020.1.3 当释放的习惯大于压抑的习惯，持续释放就会发生】 文兰： 一秒释放一次时，或者是自动释放时，是不是 只要是感受就自动释放了，不会去区分是认同还是控制了。 风：识别出来它就释放了。有时候它发生得很快，你 的心智还来不及理解。持续释放时，感受如同波浪式地涌 出，你只是看着它排出去。 刚开始，你压抑的习惯大于释放的习惯，需要一次次 操作流程。当你让释放成为常态之后，持续释放就会发生。 【2020.10.23 持续释放的重要性就如同飞机起飞】 朝颜：风，你这两周释放的量有没有超过你这两年的啊。 风：不是量的问题，是惯性的问题。释放就像飞机助跑， 如果你跑跑停停，就永远飞不起来。只有你一路往前冲， 才能加速到飞起来的程度。</p><hr><h2 id="page-205" tabindex="-1">第 205 页 <a class="header-anchor" href="#page-205" aria-label="Permalink to &quot;第 205 页 {#page-205}&quot;">​</a></h2><p>205 2020.10.22</p><hr><h2 id="page-206" tabindex="-1">第 206 页 <a class="header-anchor" href="#page-206" aria-label="Permalink to &quot;第 206 页 {#page-206}&quot;">​</a></h2><p>206 【2020.10.11 一开始压抑感受是习惯，觉察到每时每刻 的想要，不断释放就能解除压抑感受的习惯，释放就成为 你的惯性，释放就成了常态】 慧轩： 是不是根本来不及感受情绪，情绪就被放掉了？ 风： 差不多就是这样，欲望是一碰就走。随着释放加速， 会感到以前的高点，实际上非常低，欲望会一下子觉察到。 慧轩： 情绪放没了，信念没了，就是空了。无欲无求， 人生就真没意思啦，小我什么都不要。 风： 这个不能用头脑想象。我是想一口气释放到底的， 但现在实在是坐不住，刚刚去大桥上跑了一圈，多余的精 力太多了，这应该是释放带来的巨大能量。我到后两天才 明白持续释放是什么意思。基本上每一次释放就会带来一 次很充沛的能量释出。 巨廷： 你是在释放自己生命中所有不和谐能量吗？还 是针对某些人事物，具体的事件？ 风： 三大欲望。因为你时时刻刻都活在想要里，放完 了又来一个，放完了一个又来一个。 文敏： 心里十分羡慕风，我也想到达那个阶段。 风： 方法用对了就行。</p><hr><h2 id="page-207" tabindex="-1">第 207 页 <a class="header-anchor" href="#page-207" aria-label="Permalink to &quot;第 207 页 {#page-207}&quot;">​</a></h2><p>207 ZOEY： 释放后，被外界激发情绪欲望的频率、强度 有变化吗？ 风： 不是这么讲，我跑完回去再细说吧。 （后来风继续讲） 风： 这个问题是这样的。认同和控制就是世界,对世 界有强烈的贪恋和厌恶。 它时时刻刻都发生，我就在这些想要中，就像鱼儿在 水中一样。但如果你决定持续释放，你来一个放走一个， 很快你会发现你身处于这个欲望大海中。 如果你持续释放几天，你就会非常非常宁静。在这个 宁静之下，有很多强烈的欲望会很明显地浮现出来。被觉 察到时，它只是一下子被释放。 释放成为常态，是因为你发现了你把它压抑在下面是 不自然的，一直在无意识压住它。而这是一个根深蒂固的 强有力的习惯，当释放了足够多的想要控制，这个习惯也 就随之失去力量，越倾向于自然地释放。 释放到一个点的时候，有那么一刻，突然感觉到身体 不是我。它只是在动作，但是却没有一个自我在里面运作。 但这个对身体的认同马上就又回来了，与此同时，我察觉 到那是想要控制，这个想要控制就被释放了。下面的经验</p><hr><h2 id="page-208" tabindex="-1">第 208 页 <a class="header-anchor" href="#page-208" aria-label="Permalink to &quot;第 208 页 {#page-208}&quot;">​</a></h2><p>208 我的直觉告诉我不适合讲出来，我继续释放去了。 倚天： 看来到了高级阶段，的确是一觉察到就释放了， 但为什么初级阶段虽然觉察到了却不能即刻释放，还要反 复操作问句呢？ 风： 就像我刚刚说的那个比喻：游鱼习惯了大海，会 觉察不到自己在水中。因为压抑的习惯是一种强烈的倾向， 所以要不断地通过问句有意识的觉察、以及做出释放的决 定。 但当你走到一个点，这个根深蒂固的习惯已经被释放 掉，那么释放这个自然的倾向本身就成为你的习惯。这时 候，你就很容易让释放成为常态，make it constant。 用莱斯特的话来说，观看那些限制浮上来，然后浮出去 （ you just watch it floats up and floats out ） 。 但是达到那个习惯被扭转的点之前，你必须有意识去做， 否则会被习惯支配，这就是流程的重要性。释放欲望的流程 大概就是这样操作的。</p><hr><h2 id="page-209" tabindex="-1">第 209 页 <a class="header-anchor" href="#page-209" aria-label="Permalink to &quot;第 209 页 {#page-209}&quot;">​</a></h2><p>209 【2020.10.14 风分享自己持续释放的体验 】 风：我持续释放这几天，有一些体验，我前两天没有 分享出来，因为这可能是施加影响，我现在谈论一些，希 望能鼓舞到你们。 这是我和一个朋友的聊天，我把他的部分去掉了。 （以下是风分享的和朋友间10.12-13的聊天记录） 【2020.10.12】这几天持续释放中，我体验到一些东 西，持续释放确实有强烈的能量释出，而且确实有两次脱 离身体中心。我昨晚实在坐不住了，去大桥上跑了几圈， 第三天我就没有睡觉了。大概在第二天晚上的时候，有点 困倦涌上，然后我释放了想要控制，一种莫名的精力涌上 来。 持续释放威力非常大，自由真的是要体验的，所以我 分享一下我这几天的经验，有点惊人，所以我没有在群里 施加影响，你想听听看吗？ 昨天我有一次释放的时候，感觉从身体里&quot;掉出去了&quot;， 这是在能量不停涌现的时候。一开始我迈动身体，我发现 平时我都用想要控制来走路。也就是说我消耗了一部分精 力去控制我的身体移动。这个被觉察到的时候迅速被释放 了。</p><hr><h2 id="page-210" tabindex="-1">第 210 页 <a class="header-anchor" href="#page-210" aria-label="Permalink to &quot;第 210 页 {#page-210}&quot;">​</a></h2><p>210 接着我突然视角转变了。 身体自动走路，手臂和大腿自动&quot;漂&quot;着走。而我不 知道在哪里看着它。这个视角持续了大概两分钟。我首先 是发现，每次我移动身体都是费精力的，也就是我每次动 作实际上都有想要控制，然后我觉察到的那一刻它就被释 放了，这是在持续释放了好几天之后发生的。随后我领悟 到为什么每次释放都会带来巨大的能量。因为实际上我一 直在用这个能量来压抑自己，这个就是我自己的想要控制 造成的。 不过很快，我突然意识到这是一个很大的&quot;领悟&quot;， 因此就想要保持这个&quot;状态&quot;。我一想要保持，就从这个 状态中掉出来了，所以只是持续了两分钟。不过这个体验 给了我很大鼓舞，我释放的动力更足了。 我分享这个体验，希望也能给你一点鼓舞。 （笑）加油。 【2020.10.13】我发现，当你释放得很high的时候， 阻力的形式就会变化。虽然释放变得很容易，但是缺乏动 力。经常会待在一个很好的状态中享受。释放两三次就自 发停了下来。要不断提醒自己，才能继续释放。我要想到 better这个词，前面有更好的，不要止步于此。 前两天，我释放了一次对死亡的恐惧，我发现正如莱斯 特所言，当死亡的恐惧被释放时，想要认同和控制也大量 消散。同时我看到这个世界是怎样构建的,譬如我们的道</p><hr><h2 id="page-211" tabindex="-1">第 211 页 <a class="header-anchor" href="#page-211" aria-label="Permalink to &quot;第 211 页 {#page-211}&quot;">​</a></h2><p>211 德观，我们的高尚与卑劣,它最终是为了维持身体的生存。 在我们的世界中，为了别人的生存而牺牲，为什么会 被认为是高尚的事？因为我们潜意识把身体生存这件事看 作是最重要的,因此会认同那些为了大众的生存牺牲的人。 整个世界，它仅仅是生存程序，它等同于控制和认同。 嗯 ，理论上很早就知道，但看到时还是很震撼。比 如说我抬头看到天花板，天花板居然是想要控制和认同， 很神奇。因为我对它有感觉，感觉就是想要控制和认同。 除了我的感觉外，世界并没有其他东西，nothing out there。 第一步的想要自由，可以被有意识增加，只要提 醒自己就行，但不提醒就会忘记，很容易忘记。很多 人会觉得为什么这么简单的六步骤要写下来，还有get everything by releasing only，为什么要写下来，放 在显眼的地方，因为真的很容易忘记。而且，你本来就有 无限能量。 昨天还有一个事，我在天桥上跑到桥尾，一路跑到下 面，没注意到前面停着一辆车。这时候浑身精力非常充沛， 我伸手一推，那辆车竟然被横着移动了一米，我没有感觉 到累，回到家过了很久，这种浑身能量充沛的感觉才慢慢 平稳下来。 这和那种watch it happen的感觉还不一样，因为持</p><hr><h2 id="page-212" tabindex="-1">第 212 页 <a class="header-anchor" href="#page-212" aria-label="Permalink to &quot;第 212 页 {#page-212}&quot;">​</a></h2><p>212 续释放确实会像莱斯特说的那样，身体会释出很强大的能 量。它会让身体受不了，所以会出去活动。在活动的时候， 我只是宣泄多余的能量，而我昨天大概知道这些能量是怎 么来的了，它一直都在，只是我平常用来压抑自己的感受。 不用来压抑感受时，它就趋向于无限。 我那一推的力量，应该比现在世界上力量最大的大力 士还大，但我的身材很小，没有肌肉，我们被身体限制得 真的很严重。莱斯特还说过，站在核爆中央，只要你不抵抗， 就一点事都没有。不过，热能我体会到了，不抵抗heat， 确实不会热，这个简单些，可以试试。 加油，make it constant，你不一定需要专门抽时间 去做，而是把所有时间都拿来释放，嗯，就是说，其实没 有必要等待一个闭关独处的机会，现在能够感觉到感受， 就可以释放。我们时时刻刻都活在想要里，就像鱼儿活在 水中，觉察到想要控制和想要被认同，它立即被释放了， focus on these two wants，这样做会容易很多。</p><hr><h2 id="page-213" tabindex="-1">第 213 页 <a class="header-anchor" href="#page-213" aria-label="Permalink to &quot;第 213 页 {#page-213}&quot;">​</a></h2><p>213 【2020.10.14 持续释放几天的效果远大于断断续续多年 】 我是无限： 你是释放想要控制，但是我释放的都是想 要改变，想要控制很少，我觉得想要控制是一大堆想要改 变组成的，你怎么看？ 风： 课程是想要控制，莱斯特说话时经常用想要改变。 想要改变、想要推开它、想要抓住它，这都是想要控制。 想要改变是想要控制的一种。 如果要说的针对性一点，那就说想要改变。有时候我 们想要改变，有时候我们想要维持，这都是wanting of control。 我是无限： 对，你这个说得非常好。 风： 我断断续续使用释放法六年，没有持续几天的效 果好（笑），持续多么重要。 我是无限： 对，持续释放会不断深入，间断的释放就 不行。 风： 我体会到莱斯特在视频里说的，帮助他人就是帮 助自己，前段时间我翻译莱斯特的音频和92年释放法课程， 在翻译的过程中，我等于自己又复习了一遍，而且这回发 现了我听很多遍都没有注意的问题，这让我得以持续释放 下去。</p><hr><h2 id="page-214" tabindex="-1">第 214 页 <a class="header-anchor" href="#page-214" aria-label="Permalink to &quot;第 214 页 {#page-214}&quot;">​</a></h2><p>214 我是无限： 你持续释放到死亡恐惧的过程是怎么样的？ 大概的方法和流程？ 风： 方法很简单，把六步骤放在身边，我现在的感受 是什么，想要控制还是想要认同？能觉察到吗？它离开了 吗？还能觉察到更多想要控制或者想要认同吗？能够让它 离开吗？我用的就是92年释放法释放欲望的流程。 每一次释放，会去看到一点自由，然后我会提醒自己 第四步，持续释放。持续释放的方法，就是继续去看现在 我是想要控制还是想要认同。如果我对此感到模糊，马上 我就能感觉到我是想要改变这个状况，而这是想要控制。 觉察到它，立即就有放它离开的倾向。 中途，当然有很多让我停下来（卡住）的状况发生。 注意到，提醒自己第四步（持续释放）。 发现自己用力、努力、胶着，则提醒自己第五步（释 放想要改变）。 到后来，有强烈的喜悦涌现出来时，没有动力释放， 提醒自己第一步（我想要的是自由）。 不知道释放什么时，提醒自己第三步（所有感受都是 想要控制、认同）。 每当这时，都会立即察觉到这个想要控制或者认同，</p><hr><h2 id="page-215" tabindex="-1">第 215 页 <a class="header-anchor" href="#page-215" aria-label="Permalink to &quot;第 215 页 {#page-215}&quot;">​</a></h2><p>215 欲望会来一个放走一个，来一个放走一个，对死亡的恐惧 （想要生存）就如莱斯特所言，自发地浮现到表面来。 第一次释放对死亡的恐惧是最困难的，对死亡的恐惧 第一次浮现时，就像是手碰到了滚烫的火一样，立即缩回 去，我反反复复释放了想要控制，然后再去触碰它时，释 放了一次，后面就简单了，逃避的倾向太强烈，所以我们 倾向于把对死亡的恐惧压抑在最深处。每一次释放对死亡 的恐惧（想要生存)，都会削弱这个逃避的习惯。 我还是先做到最后，再来分享吧，我去释放了，各位 加油，回见！（笑）</p><hr><h2 id="page-216" tabindex="-1">第 216 页 <a class="header-anchor" href="#page-216" aria-label="Permalink to &quot;第 216 页 {#page-216}&quot;">​</a></h2><p>216 【2020.10.30 风分享持续释放后身体和生活的变化】 起初的时候，我是通过释放来做到所有事。后来我清理 了大部分都想要控制和认同，我开始专注于对死亡的恐惧， 于是我释放了很多对死亡的恐惧，一种难以言喻的安全就 这样笼罩着我。 这时候我只要有一个念头，事情就会发生，甚至不需要 刻意对它做释放。 几个星期的释放，你就可以做到这些事。 还有我实际上已经不需要睡眠和食物。我现在不需要睡 觉，旺盛到甚至要到天桥上跑一圈宣泄。 我从第一次闭关，释放的第一个星期就开始了。只要你 持续释放想要控制和认同，身体就会涌现出无穷的精力。 这些能量的涌现甚至会让身体会承受不住，所以需要出去 跑几圈宣泄。（笑） 那时候你自然就停止了睡眠。你不需要刻意去抵触睡 眠，只要在你清醒的时候都用来释放就好了。 嗯，如果你没有疲累，那就释放下去，一次接着一次。 如果你感到疲劳了，睡觉是不影响释放的。 我只是说明这一点，把清醒的时候都拿来做，你会进展 得很快速。我依稀记得莱斯特在一个音频里讲过，如果你</p><hr><h2 id="page-217" tabindex="-1">第 217 页 <a class="header-anchor" href="#page-217" aria-label="Permalink to &quot;第 217 页 {#page-217}&quot;">​</a></h2><p>217 睡觉之前在做释放，你到了梦里，星光层面依然在做释放。 所以，你可以睡觉，你没有必要刻意撑着不睡。等你释 放到精力无穷时，你会自然停止睡眠。这说的足够清晰吗？ （笑） 去吧，祝你成功。（笑） 是的，为什么不把这个方法用到极致呢？它能给你带来 更巨大的好处。</p><hr><h2 id="page-218" tabindex="-1">第 218 页 <a class="header-anchor" href="#page-218" aria-label="Permalink to &quot;第 218 页 {#page-218}&quot;">​</a></h2><p>218 【2020.11.7 仅仅一个念头事情就发生】 伯利恒之星： 这几天进步很大吧。（笑） 风： 你体验过平静吗？是一种时间寂止的感觉。我刚刚看 情绪表平静的描述词，无限、永不衰老、不朽，就是这种感觉。 伯利恒之星： 还没有（笑）。只体验过几秒钟失去对死 亡的恐惧。 风： 以前我把万念俱灰当平静是很错误的。 伯利恒之星： 哈哈哈，我好多年都是。 风： 你体验到波澜不惊了？ 伯利恒之星： 几秒钟，没有完全波澜不惊，一个预览， 然后就掉到底下来了。 风： 那应该是一个很大的鼓舞。（笑） 伯利恒之星： 有一点，我每天都记着那种感受。 风： 我连续住了很多五星级酒店没有花钱。 伯利恒之星： 哈哈哈，跟莱斯特一样了。那可算是一个 巨大的成功经验。 风： 其实这不是这次的成功经验，上次我已经不再收钱， 也不再工作了，因为我强烈地感到自己不需要钱了，于是</p><hr><h2 id="page-219" tabindex="-1">第 219 页 <a class="header-anchor" href="#page-219" aria-label="Permalink to &quot;第 219 页 {#page-219}&quot;">​</a></h2><p>219 真的就不需要钱了。 伯利恒之星： 现在你依然可以做到吧。 风：嗯，我从上次以来，一直在体验莱斯特说的一个念 头事情发生。这成为了一个惯常经验，所以我没有特意强调。 （注：风在此次谈话中另外提到一些超体验的事情，与 莱斯特曾经讲过的相似。因为不适合放在公开传播的册子 里，故隐去了一些对话，只摘选部分。风亲证了莱斯特所 说的“仅凭一个念头，事情就毫不费力地发生”，让我们 自己也通过持续释放，达到这种状态吧。）</p><hr><h2 id="page-220" tabindex="-1">第 220 页 <a class="header-anchor" href="#page-220" aria-label="Permalink to &quot;第 220 页 {#page-220}&quot;">​</a></h2><p>220 而事实上我在问，那么我们为什么不走完全程 并得到完美的自由，好让我们不再有烦恼，不再有 痛苦，在那里我们可以仅凭一个念头得到一切。 有一天我们会这样做的，我们中的每一个人。 为什么现在不这样做呢？ ——莱斯特 任何事情的发生都毫不费力，只是把一个念头 放到我们平静的头脑中，它会很快显化出来。那为 什么不在接下来的几个月里做到呢？ 聪明点。 ——莱斯特</p><hr><h2 id="page-221" tabindex="-1">第 221 页 <a class="header-anchor" href="#page-221" aria-label="Permalink to &quot;第 221 页 {#page-221}&quot;">​</a></h2><p>221 【2020.11.24 持续释放是靠六步骤达成的，不是靠外在的 行动，不是靠闭关，关手机 】 Go All The Way: 我这两天还是无法持续释放，而且 第一天闭关时特别想睡觉。 风： 所以我不推荐别人闭关。（笑） Go All The Way: 一释放就睡觉，不释放也想睡觉， 根本没办法释放。 风： 把自己关起来用处不是特别大，业力是无法被关 起来的。 Go All The Way: 我没有关起来。我照常做事，只是 没看手机，不看群，结果特别困。这就是我的闭关，第二 天好一点了。 风： 但是释放效率也没有达到自己想要的标准吧。 Go All The Way: 是的，完全回不到上次我持续释放 一天的突破状态，一直就卡。 风： 持续释放是靠六步骤达成的，不是靠外在的行动， 不是靠闭关，关手机。（笑）进入六步骤，聊着天也能持 续释放。 Go All The Way: 是啊，上次就是聊天也释放了一天，</p><hr><h2 id="page-222" tabindex="-1">第 222 页 <a class="header-anchor" href="#page-222" aria-label="Permalink to &quot;第 222 页 {#page-222}&quot;">​</a></h2><p>222 现在释放十分钟都不行，好像突然间不会释放了。 风： 回到六步骤就好。其实我不推荐闭关，除非你释 放到自然倾向与外界断联系。 Go All The Way: 我以为是手机分散了我的注意力， 让我不愿意释放。 风： 不是的，是你的karma（笑），是你的程序让你 不释放。负起全责，不要赖手机。 Go All The Way: 我以为断网会让我持续释放。 风： 这是很多人的误解。向外找原因，比如有人以为 是工作拖住自己；有人以为要不是现在的状况，自己早就 自由了；有人以为家人拖住自己……实际上都不是，能拖 住自己的只有自己， take full responsibility 。 Go All The Way: 我逼自己不看手机 ，这样就可以专 心释放了，结果手机确实没影响了，但是我还是不愿意释放。 所以根本不是手机的事，我就是不死心啊，以为外在的东 西能影响我释放。 风： 释放就好了，别管闭关还是聊天。外在的东西要 是能让人达成六步骤，圣人就可以批量生产了。把人全部 关起来，逼他们释放。（笑）</p><hr><h2 id="page-223" tabindex="-1">第 223 页 <a class="header-anchor" href="#page-223" aria-label="Permalink to &quot;第 223 页 {#page-223}&quot;">​</a></h2><p>223 【当你持续释放，你会自动隔离；当你决心向内，没有任 何人事物能打扰你】 【2020.10.23】 风：当你持续释放，你会自动地隔离。 六步骤没有叫你辞职，也没有叫你隔离，它只是叫你 持续释放，当你持续释放，隔离会自动发生。 持续释放不需要依赖一个安静的环境，因为你的世界 仅仅是你思想的投射，你无法通过对一个结果做些什么来 改变起因。如果你感到嘈杂，那只是一个感受，你回到第 三步，释放你现在的想要控制和认同的感受。 一开始你会感到困难，所以你可以把你所有不需要脑 力工作的时间先运用起来。当你这样做，持续释放会产生 一个动能，它会让你的释放发生得越来越简单，这时候你 就可以在做事时也能释放。 再接着释放下去，你会发现自己不用做事了，因为你 不再创造那个图景了。你不再创造&quot;我需要工作&quot;的图景 了。</p><hr><h2 id="page-224" tabindex="-1">第 224 页 <a class="header-anchor" href="#page-224" aria-label="Permalink to &quot;第 224 页 {#page-224}&quot;">​</a></h2><p>224 【2021.1.7】 倚天： “当你持续释放，你会自动隔离”，是说进入 持续释放后，自然不会有人打扰吗？ 风: 当然,外面的世界本来就是你投射的,如果你被 打扰，只能说明你想要被打扰。你用思想创造了那个被打 扰的境况。 倚天： 你在闭关时，没遇到任何打扰吗？ 风： 没有，一旦你决心向内，没有什么能打扰你。 倚天： 是外在有刺激，自己没有反应？还是说外面自 然真的什么干扰都没有了？ 风： 一回事。外面只有你的思想，一开始你还在创造 一些事件，不过那是你的欲望在打扰自己。 释放到后面，尤其是集中释放死亡的恐惧的时候，想 要控制和认同走得差不多了，世界完全不会干扰。如果在 树林里这会更明显，毒蛇猛兽都会离你很远。 倚天： 比如，你在关房里，有人敲门，但对你根本不 构成影响。还是说，一旦你进入持续释放，根本不会有人 来敲门？ 风： 释放了足够多的想要控制和认同，根本不会有人 敲门。 倚天： 我知道了。</p><hr><h2 id="page-225" tabindex="-1">第 225 页 <a class="header-anchor" href="#page-225" aria-label="Permalink to &quot;第 225 页 {#page-225}&quot;">​</a></h2><p>225 【2020.10.30不要找机会让自己停下来 】 风：不要找机会让自己停下来，释放的感觉不美妙吗？ 【2020.12.28继续继续继续 】 风：到达更轻松后，应该继续释放。一次性把底层感 受清空。 不要找机会让自己停下来 到达更轻松后，应该继续释放 一次性把底层感受清空 ——风</p><hr><h2 id="page-226" tabindex="-1">第 226 页 <a class="header-anchor" href="#page-226" aria-label="Permalink to &quot;第 226 页 {#page-226}&quot;">​</a></h2><p>226 【不论是否定目标，只要能一直持续释放，有释放的动力 就可以】 【2020.3.16】 天成： 老师，我刚刚写下来很多想要的目标，也定了 时间。在过程中，是不是只要我持续释放，也不用一直盯 着目标，只是去贯彻六步骤，也可以达成？ 风： 可以。 【2021.7.26】 安心自在： 一定要列目标释放还是说也可以只释放当 下的感受也可以？ 风： it&#39;s up to you。释放，一定要按照自己内在的 节奏来。</p><hr><h2 id="page-227" tabindex="-1">第 227 页 <a class="header-anchor" href="#page-227" aria-label="Permalink to &quot;第 227 页 {#page-227}&quot;">​</a></h2><p>227</p><hr><h2 id="page-228" tabindex="-1">第 228 页 <a class="header-anchor" href="#page-228" aria-label="Permalink to &quot;第 228 页 {#page-228}&quot;">​</a></h2><p>228 【2020.10.18卡住的唯一原因是想要控制】 风：第五步，是一开始可能会用到最多的，因为你会 经常卡住。但是卡住只是因为你想要控制而已。 卡住的唯一原因就是想要控制在运作。就这么简单。 释放掉这个运作你的想要控制，卡住的感受就立即变成了 顺畅。 风谈六步骤 Step 5 第五步: 当你卡住时，释放对卡住的感受的想要 改变。 If you get stuck.let go of the wanting to change the stuckness.</p><hr><h2 id="page-229" tabindex="-1">第 229 页 <a class="header-anchor" href="#page-229" aria-label="Permalink to &quot;第 229 页 {#page-229}&quot;">​</a></h2><p>229 【2020.9.23越是卡住，越要释放】 越是遇到卡住的状况，越要释放，释放想要改变的欲 望。不然的话，你就把它压抑到潜意识中，它就会一直运 作你，你就会一直卡住。 此刻你要决定去释放掉那个卡住你的想要控制，下一个 超越它的决定，你要下决定超越它，才能觉察到，要去允许 它浮现和离开，然后再去做。 不要费力压抑，但也不要逃开，就面对那个卡，直到 释放掉为止，不要做其他事情去逃避。</p><hr><h2 id="page-230" tabindex="-1">第 230 页 <a class="header-anchor" href="#page-230" aria-label="Permalink to &quot;第 230 页 {#page-230}&quot;">​</a></h2><p>230 【没有在释放，也就是卡住时，释放想要控制或改变这种 局面的欲望】 海尔：如果你真的在哪里卡住了，把想要控制或改变 这种被卡住的局面的欲望释放掉。 这一步太重要了，这是圣多纳释放法的安全阀，是当 你走歪路时把你拉回来的保障。 特别要记住：当我们试图改变或控制自己的所感所想 时，就容易卡住。因此，当我们把想要改变或控制自己当 下感受的欲望释放后，整体状态也会随之改变。 很简单的，如果你出现以下情况，就释放想要改变或 控制这种情况的欲望。 ◎ 感受太多，承受不住了 ◎ 离释放越来越偏了 ◎ 你忘了释放这回事 ◎ 你觉得自己怎么都放不下 ◎ 你不能准确把握自己当下的感受 ◎ 你感觉自己的某种特定思考或行为模式特别难释放 ◎ 你想跳过流程，迅速释放干净</p><hr><h2 id="page-231" tabindex="-1">第 231 页 <a class="header-anchor" href="#page-231" aria-label="Permalink to &quot;第 231 页 {#page-231}&quot;">​</a></h2><p>231 【2020.10.24 面对、允许、释放】 风：不要恐惧卡住的习惯，允许它浮现，才能释放它。 卡住的感受出来的时候，你有一个强烈的想要改变它 的倾向，你这时的想法就是由那个想要改变驱动的。任何 头脑想对流程做改动，都是这个原因。 通过压抑的方式能够解决惯性吗？ 不去面对卡的感受，就是把它压抑回去。 惯性不过是一种感受在驱动，程序就是感受，回到六 步骤的第三步，所有感受都是想要控制和认同，释放它们。</p><hr><h2 id="page-232" tabindex="-1">第 232 页 <a class="header-anchor" href="#page-232" aria-label="Permalink to &quot;第 232 页 {#page-232}&quot;">​</a></h2><p>232 【2020.10.18因为你想要逃避感受，所以你就在感受上 面罩了一层模糊不清的感受，释放想要改变，感受就会变 清晰】 风： 卡住了一定要先释放卡的感受，释放想要改变的 欲望，你无法一直带着对那个卡住的抗拒释放，这等于一 脚踩油门一脚踩刹车。 释放不掉就是卡住，stuckness，紧抓感，感受像黏 在上面一样不离开，或者下意识想要逃开，不敢碰，这都 是卡住。 我们倾向于在感到卡住的时候，做别的事情，等到感 觉不那么胶着了再释放，我发现这是不对的，就如莱斯特 说的那样，这会把它压抑到潜意识中让它一直运作你。 （风引用THE WAY Part 1里莱斯特的话） 和研讨会的指导员说一下，让他引导你，或者你持续 释放卡住的感受。看到当你不去释放卡住的感受时，你就 让它继续运作，这会导致你持续地卡住。 stuck，卡住，停滞不前，凡是让你停下来的感受就 是卡住的感受，而不是有一个特别的感受叫&quot;卡&quot;。 还有就是直接面对最底部对死亡的恐惧时，会卡住， 这个大部分人都会卡在那里。</p><hr><h2 id="page-233" tabindex="-1">第 233 页 <a class="header-anchor" href="#page-233" aria-label="Permalink to &quot;第 233 页 {#page-233}&quot;">​</a></h2><p>233 包括看不到（感受），vague feeling（模糊不清的 感受），因为你想要逃开（run away），所以就在上面覆 盖了一层模糊不清的感受，要释放掉想要改变它的欲望， 释放掉这个卡住的感受，你就能再次看见底下那个。 再譬如，在一些主题上感受不到具体的感受，那也是 一种卡住，比如有人说，我知道我想要控制某事，但我感 觉不到，那就是卡在那儿了。 我是无限：这个应该可以灵活采用各种技巧来激发。 风： 这是 elementary way ,小学的方式。 莱斯特说的研究生的方式，是释放那个想要改变卡住 的感受的欲望。也就是说，你是不是觉得这个感受太过模 糊不清，你是不是想要改变它?释放想要改变它，这个模 糊不清的感受就立刻清晰了。 （风引用THE WAY Part 1里莱斯特的话） 仅仅释放卡住的感受，或者甚至是模糊不清的感受， 你可能甚至无法看到它，因为你试图逃避它，或者至少想 要改变这个模糊不清的感受——不管它是什么。它离开之 后你就有能力再次走进对死亡的恐惧。 莱斯特是这样说的，莱斯特专门说了不明显的感受， vague feeling（模糊不清的感受），他专门说了这个。</p><hr><h2 id="page-234" tabindex="-1">第 234 页 <a class="header-anchor" href="#page-234" aria-label="Permalink to &quot;第 234 页 {#page-234}&quot;">​</a></h2><p>234 当感受模糊不清的时候，你就想要改变它。因为当感 受模糊不清的时候，你就想要让它变得更清晰，这个“想 要”，就是想要改变。觉察到，你就可以释放它。释放之后， 你就会变得清晰。 这个我操作过很多次的，确实是 postgraduated way , 比用场景激发感受的 elementary way 要简洁高效 很多。 我是无限： 原来感受不到的原因，是因为上面有一些比如 想要改变的欲望，或者什么东西附着在上面，扰乱了自己的感 知，释放这些之后就可以感受到了。 风： 是的，我就是这个意思。vague feeling覆盖在上 面了。这就是the way那篇反复说明的一个方法。</p><hr><h2 id="page-235" tabindex="-1">第 235 页 <a class="header-anchor" href="#page-235" aria-label="Permalink to &quot;第 235 页 {#page-235}&quot;">​</a></h2><p>235 【2020.10.23当感受模糊不清，释放对它的想要改变， 感受就变得清晰】 风：一个模糊不清的感受，你就释放对它的想要改变， 它就变得清晰了。 每一个当下的感受，都是想要控制和想要认同。如果 辨认不清，它就是模糊不清的感受。释放对它的想要改变， 它就变得清晰。 变得清晰，你就能察觉到现在的感受是想要控制还是 想要认同，然后就能继续释放。 只要不清晰，就有一个想要控制。释放中任何状况的 处理办法都在六步骤中，所以不要使用六步骤以外的方法。 第三步是觉察到所有感受都是想要控制和认同，并且 释放。如果做不到这一步，那就是卡住，适用第五步。 做不到持续释放，也是卡住，是被想要控制和认同驱 动的。课程里面指导员说&quot;当你的感受涌现时，不要压抑 你的感受，但是注意力更多地放在你的想要上&quot;，也就是说， 释放的时候，你允许感受浮现，但是更多觉察你的&quot;想要&quot;。 这就是六步骤的第三步。 觉察到所有感受都是被想要控制和认同，并且释放它们。</p><hr><h2 id="page-236" tabindex="-1">第 236 页 <a class="header-anchor" href="#page-236" aria-label="Permalink to &quot;第 236 页 {#page-236}&quot;">​</a></h2><p>236 【2020.10.23你并不是没有感受，你可能只是压抑了感受】 chole:我还以为自己释放到没有感受了，原来没有感 受是你的感受模糊不清。 风：不是释放到没有感受，因为如果你真的没有感受， 你的体验会非常美妙。它会是一种时时刻刻合一的感觉， 纯粹的爱会涌现。因为你的无限存在就是这样美妙。 如果没有这种美妙的感觉，说明你内在压抑的感受还 很多。你只是压抑了它们，逃离了去感觉，而不是释放了 它们。 【2020.10.23轻松地允许自己觉察到想要改变，释放想 要改变，就能解除卡】 风：觉察到后，你释放了吗？ 我是无限：没，一觉察到发现好像自动缩回去了。 风：那就是卡住了。释放停下来就是卡住了，你想要 释放，但释放停下来，这个就叫作卡住。 我是无限：今天老是这样，成功释放很少。</p><hr><h2 id="page-237" tabindex="-1">第 237 页 <a class="header-anchor" href="#page-237" aria-label="Permalink to &quot;第 237 页 {#page-237}&quot;">​</a></h2><p>237 风：那说明“想要控制”这个程序浮现出来了，正好 是释放的时候，越卡住，越要释放，因为这样能够让你解 除卡住的程序。 你先允许自己觉察到卡住的感受，然后觉察到你想要 改变它，轻松地允许自己觉察到你想要改变，然后它就消 散了。 你再看看现在的感受，如果依然是卡住的，那你就继 续允许自己觉察到它，然后觉察到想要改变它。接着，想 要改变就会继续离开。 因为压抑了很多，所以需要持续释放，但是如果你持 续释放想要改变，释放干净，这个卡住的程序就会彻底消 失，不会再出现。以后的释放在大部分情况下就会变得很 顺畅，不会再卡住，是不是听起来很棒？ 卡住可能还会出现一两次，因为有些卡住的程序压抑 得很深，但是它不会再是一种常态了。</p><hr><h2 id="page-238" tabindex="-1">第 238 页 <a class="header-anchor" href="#page-238" aria-label="Permalink to &quot;第 238 页 {#page-238}&quot;">​</a></h2><p>238 2020.10.22</p><hr><h2 id="page-239" tabindex="-1">第 239 页 <a class="header-anchor" href="#page-239" aria-label="Permalink to &quot;第 239 页 {#page-239}&quot;">​</a></h2><p>239</p><hr><h2 id="page-240" tabindex="-1">第 240 页 <a class="header-anchor" href="#page-240" aria-label="Permalink to &quot;第 240 页 {#page-240}&quot;">​</a></h2><p>240 【2020.11.26持续卡住怎么办】 天成： 风，你是如何突破卡住的程序的？我发现我这 几天一直在卡住。这个星期我都在宾馆里的。 风： 卡住的时候，就是释放想要控制。但是要注意一点， 你的业力会推动你行为，因此，你会去做别的事。这时候 你会发现，无论你做什么事，只要你释放，就会更得心应手。 留意这一点，就会促进你释放。 天成： 做两下，就去看下手机。或者，出去吃个饭。 风： 因此莱斯特并没有建议人们去闭关。他让学生在 行动中做。 天成： 在行动中做是什么意思？ （风引用the way part2里莱斯特的话） 所以，在行动中是没有障碍的，障碍是认同有限的身 体和心智，认同小我。 如果你试着不进行任何行动，你不会成功，因为你的 业力现在正在驱使你去行动。所以如果你想不进行任何行 动，你不会成功，不管你的业力是什么，你都会去做的。 所以想要什么都不做是没有用的，只有释放才有用， 只有释放才会给你所有的道路，你做多快，它就来得多快。</p><hr><h2 id="page-241" tabindex="-1">第 241 页 <a class="header-anchor" href="#page-241" aria-label="Permalink to &quot;第 241 页 {#page-241}&quot;">​</a></h2><p>241 所以，行动与其说是阻碍，不如说是真正的帮助，因 为当你在行动的时候，你被感受推着走，而感受在你行动 的时候又会带来更多的感受，给你去释放掉所有的感受。 所以你必须在这个世界中做，你必须在行动中做，你 不能隔离尘世来做。当你隔离的时候，你只会逃避。 风： 如果你强行闭关，你的头脑会趋向于逃避。因为 你好像在说&quot;准备好了，我要来释放你了&quot;，其实没必要 这样，你可以直接释放，轻松地释放。 持续释放并不需要在行动层面规避行动，只要你有想 要做到的事，就有目标，你就可以持续有动力释放。卡住了， 你就用第五步。 天成： 感觉持续性卡住。 风： 那就是持续性想要控制，其实常常碰到卡住是好 事，那说明你的控制程序浮出。当你每一次在卡住时释放 想要控制，你就解除了一些。这个阶段在你完全跨出agf 之后会好很多，lap的释放会顺畅很多。 天成： 情绪在愤怒这里。 风： 愤怒的状态也会让人卡住，但是你有能量去处理。</p><hr><h2 id="page-242" tabindex="-1">第 242 页 <a class="header-anchor" href="#page-242" aria-label="Permalink to &quot;第 242 页 {#page-242}&quot;">​</a></h2><p>242 天成： 我记得你在九月份在群里分享说，有段时间一 直卡住，连一次释放都没有做，有过这样的阶段吗？ 风： 有。 天成： 后来是如何突破的？ 风： 当你释放感到挫败，你必须有意识去释放，决定 去释放，同时注意到你的想要控制，释放你的抵触和抗拒。 天成： 用释放欲望来释放抵触和抗拒吗？ 风： 嗯。这个阶段是很困难的，我知道这一点，因为会 抵触释放。首先你需要明确你想要更自由，然后你要不断 决定去释放，只释放最表面的，最表面的释放了之后，再 下决定释放最表面的，通过一次接着一次决定释放来持续。 当你一次又一次卡住，你就一次又一次释放想要控制。 每一次释放，你要感到更愉悦和轻松。这是六步骤的运用。 当你达到涅比卡帕三摩地时，就是完全达成六步骤的 第一步，完全地达成第一步会让你自发性地掉进后五步， 因此这点反而没什么必要详说。 在此之前，你要不断核实六步骤，确保你在达到第一 步的路上。 天成： 在到达涅比卡帕三摩地前，都需要不断用功，</p><hr><h2 id="page-243" tabindex="-1">第 243 页 <a class="header-anchor" href="#page-243" aria-label="Permalink to &quot;第 243 页 {#page-243}&quot;">​</a></h2><p>243 不能放松，是吗？ 风： 是的。正如尤迦南达所说，在达到涅比卡帕三摩 地之前，仍不能放松。 天成： 所以我现在需要做的是持续去释放卡住的程序。 风： 但是你不要试图一次性释放掉。 天成： 我有这个倾向。 风： 你要释放最表面的，一次释放，感受会更好。如 果你再做一次释放，你的感受会更好。有耐心地这样做， 会很快清理掉让你卡住的程序。 天成： 当我卡住的时候，我都怀疑自己是不是要去释 放情绪的阶段。心智会说，你体验释放情绪不够多。 风： 哈哈，不要轻易把自己倒退回去。六步骤没让你 倒退回去，一切的答案都在六步骤里。只要偏离六步骤， 你就谁也不要信。六步骤是完美的步骤。</p><hr><h2 id="page-244" tabindex="-1">第 244 页 <a class="header-anchor" href="#page-244" aria-label="Permalink to &quot;第 244 页 {#page-244}&quot;">​</a></h2><p>244 【2020.12.16很愤怒无法释放怎么办】 抒心: 老师我还有一个卡点，就是有些事激发了我的狂怒，恨 不得杀了那个人，想爆粗口，骂人，这种时候我就没法安静的释放， 怎么办呀？ 风: 先允许这个情绪表达出来，然后你就能释放了。 抒心: 可以骂出来，不对着当事人? 风: 嗯，如果你实在克制不住的话，你允许自己稍稍失控一下， 然后去轻松地注意自己的感受。 抒心: 就是说，如果能克制住还是别发疯? 风: 不要压抑感受，但是不要让它爆发得太厉害，导致失控。 在遇到强烈情绪时应该特别小心。 抒心: 当我很想表达到时候却选择了忍住，这就是压抑感受， 是吗？ （风下面引用了两段莱斯特的话） 我们现在花了99%在潜意识心智上，压制着那些过去累积的感 受。如果所有的愤怒一次浮出来，我们会完全失控，可能会伤害某 人，因此我们有必要压制那些累积的愤怒。 同样的还有悲痛，如果悲痛一次性浮出来，我们会被悲痛压垮， 达到我们不能控制自己的程度。</p><hr><h2 id="page-245" tabindex="-1">第 245 页 <a class="header-anchor" href="#page-245" aria-label="Permalink to &quot;第 245 页 {#page-245}&quot;">​</a></h2><p>245 这适用于所有的情绪。有太多的过去累积的情绪，因此我们必 须花费我们绝大多数的时间去压制住这些压力。 我之所以叫它们压力，是因为每一个潜意识的感受都想要浮出 来展现它自己。我们非常小心地让它浮现出来，并放开控制，释放 潜意识中的逼迫和驱动，倾泻它们。 …… 这个技巧首先展示给你心智、情绪的全貌，以及它们怎么关联 起来。这个技巧让你的潜意识心智浮现出来，从我们不去看，到浮 现在你面前——这样你就能够对它做些什么。 它展示了我们能对情绪和感受做的四件事。我们能做到最坏的 事情是压抑。第二件稍微好一点的坏事情是逃避。我们能做的第三 件事是从压抑中释放的开始，它就是表达你的感受或情绪。第四件 事就是我们要去做的，倾倒你的压抑的情绪。 ——About Releasing 关于释放（1）莱斯特早期创立释放法时的音频内容 风： 这些关键的部分都翻译出来了，如果你不允许它表达出来， 你是在压抑它。但是如果一下子浮出太多感受，情绪失控了，你也 无法释放。因此你要非常小心地让它浮现出来，这个过程不要用力。 木: 情绪失控时怎么办？ 风： 如果真的情绪失控时，就让它失控一会儿。允许它表达 出来，你就可以释放了。</p><hr><h2 id="page-246" tabindex="-1">第 246 页 <a class="header-anchor" href="#page-246" aria-label="Permalink to &quot;第 246 页 {#page-246}&quot;">​</a></h2><p>246 【2020.11.10当感觉愤怒，允许自己表达，不需要表达 完，只要不压抑感受，你就可以释放】 在焉： 当愤怒的时候，转向内，不压抑这个能量，而 是体验自己愤怒能量，释放掉。不就行了吗？向外的对别 人的表达是一个故有的习惯，这个时候是被情绪操纵的， 也是失去觉察的。 风： 我知道你的意思。在内观里面，他们是这么教导的。 在焉： 莱斯特说对自己负百分之百的责任。 风： 莱斯特说表达是释放的开始，不是用表达替代释 放。let the things come out。温习一下the way: 在世 界中，当你想要外出时，你必须去压抑，否则你就会被杀死。 如果你对错误的人表达了愤怒，这个人不是揍你，就是要开枪 打死你，这情况日益严重。昨天在加利福尼亚有几百名警察在 街上巡逻，为了阻止帮派枪战。昨天洛杉矶发生了三起帮派枪杀。 你无法在外面停止它，但是在这里(指学释放的地方)你有一 个非常好的机会去表达和释放，向前移动，向上移动。 他不是说你在哪里都要表达。（笑） 风： 上面大家讨论的有些乱，我稍微总结一下吧。首先， 我知道很多人学过一些其他教导里的知识，会把&quot;带觉察&quot; 和&quot;不带觉察&quot;引入这里面。</p><hr><h2 id="page-247" tabindex="-1">第 247 页 <a class="header-anchor" href="#page-247" aria-label="Permalink to &quot;第 247 页 {#page-247}&quot;">​</a></h2><p>247 不过莱斯特先生的意思，是我们有四种处理情绪的方式： 第一种最糟糕，叫压抑； 第二种稍微好一点，叫逃避； 第三种是释放的开始，叫表达； 而我们要做的是第四种，叫释放。 因为表达是释放的开始，所以你会发现，如果你不允 许它表达，你会持续把它压抑在下面。 不要引入觉知的观念，因为有时候这种&quot;带觉知的表 达&quot;其实隐含了一种压抑。 理论上觉知是好的，我也知道，纯粹的觉知。但是引 入了这些概念，其实是混淆了这些简单的教导。 莱斯特的意思很简单，你要允许自己表达，然后你就 可以释放了。允许自己表达不代表你要把表达做完，比如 你可能想要发火，这时候你下意识想要通过某种方法甚至 释放法压抑它。 现在你允许自己表达，可能在你允许表达的那一刻， 你就马上可以觉察到它了。你刚想发火，你就发现自己释 放了。你不用把表达做完。 时代万物互联： 刚发火就释放了？</p><hr><h2 id="page-248" tabindex="-1">第 248 页 <a class="header-anchor" href="#page-248" aria-label="Permalink to &quot;第 248 页 {#page-248}&quot;">​</a></h2><p>248 风： 是的，经常这样。 在焉： 可以理解，当不压抑的时候，人是自由的 可以选择仅仅释放，或者选择一个表达方式给别人。 而压抑的时候，人是不自由的，或许更加愤怒，只是 没有发出来，或许发出来也是扭曲的。 风： 嗯，不压抑的时候，你就可以选择表达或者释放。 其实如果大家真的实践过，会发现这一点：你可能会表达 一点点，然后马上就能释放了。如果不允许表达，可能一 直释放不了。 比如如果你坐不住，却让自己一直坐在那里释放，你 可能一整天都卡在那里，在和这个状况作斗争。这个时候 你只要允许自己站起来走一走可能就能顺利释放了。 我是无限： 你必须表达完，否则头脑容易骗自己。在 允许的情况下。 风： 真正释放过的人会有这个经验，不一定会表达完 的。有时候你摩拳擦掌准备吵架，突然那个感觉出来了， 被释放了，离开了，然后你就不想吵架了。（笑）</p><hr><h2 id="page-249" tabindex="-1">第 249 页 <a class="header-anchor" href="#page-249" aria-label="Permalink to &quot;第 249 页 {#page-249}&quot;">​</a></h2><p>249 【2020.11.10表达是释放的开始，任何情绪感受出来时， 你抗拒它，都是不允许它表达，允许它表达，就可以带出 来释放】 风： 这是about releasing里面的一段，“它展示了 我们能对情绪和感受做的四件事。我们能做到最坏的事情 是压抑。第二件稍微好一点的坏事情是逃避。我们能做的 第三件事是从压抑中释放的开始，它就是表达你的感受或 情绪。第四件事就是我们要去做的，倾倒你的压抑的情绪。” 我是无限： 我这几天也强烈的发现了，不要去压抑自 己对情绪的表达。就让自己表达吧！表达完了，发现去释 放非常简单。但是压抑着表达之后去释放很困难。 风： 释放的开始。（笑） the beginning of releasing the suppressed feelings 。 我是无限： 因为连感受到情绪都难以做到，压抑到令 人发指的程度了，我就压抑表达非常厉害。 风： 每一个被压抑的感受都想要离开。 我是无限。 对。 风： 另外一点就是当你处于万念俱灰的时候你其实是 很不想动弹的。这时候你强迫自己去勤奋，这也是在压抑 万念俱灰，你不让万念俱灰表达，所以要允许自己懒惰，</p><hr><h2 id="page-250" tabindex="-1">第 250 页 <a class="header-anchor" href="#page-250" aria-label="Permalink to &quot;第 250 页 {#page-250}&quot;">​</a></h2><p>250 然后去把这个感觉带出来。 你在恐惧和焦虑的时候硬要去决定和行动也是一样， 这是把情绪压抑住，不让它表达。 我是无限： 原来是这样，我发现我对表达还理解的不够。 风： 你可能以为只有强烈的情绪比如愤怒之类才是表达。 我是无限： 对。 风： 但你如果明显处于万念俱灰之中，却强烈地抗拒 它，努力在外在做出行动，这也是在压抑它。 我是无限： （笑）确实。 风： 比如你明明感受到懒惰，却逼迫自己不去懒惰。 真正的行动的变化，只会发生在你释放了、导致情绪上移 之后。</p><hr><h2 id="page-251" tabindex="-1">第 251 页 <a class="header-anchor" href="#page-251" aria-label="Permalink to &quot;第 251 页 {#page-251}&quot;">​</a></h2><p>251 【2020.10.23控制、认同、安全都不是坏事，但&quot;想要&quot; 会使你持续被匮乏感驱动】 风： 释放流程是一种唤醒释放本能的技巧。 你可以控制感受和释放，实际上莱斯特就用过&quot;控制 你的心智&quot;这个说法。 但是“努力” （ effort ） 是“想要控制”， 想要控制=对控制的匮乏。 所以，一旦有努力，有想要控制，你就会卡住。 卡住的时候，是一个&quot;想要控制&quot;在运作。如果你不 释放掉这个运作你的程序，那就会持续卡住。 当你释放掉这个想要控制的程序，你就感受到顺畅， 因为程序驱动你的感受，接下来发生的所有事就会都处在 你的掌控之中。 因此，不是不能控制感受和释放，而是需要用一个特 定流程和技巧来控制，而不能用你过去的习惯来控制。 通过释放想要控制来控制，通过释放想要认同来获得 认同，通过释放想要安全来获得安全。 控制、认同、安全都不是坏事，但&quot;想要&quot;会使你持 续被匮乏感驱动。</p><hr><h2 id="page-252" tabindex="-1">第 252 页 <a class="header-anchor" href="#page-252" aria-label="Permalink to &quot;第 252 页 {#page-252}&quot;">​</a></h2><p>252 其实，关于个人感悟，我有一个看法。任何个人的体 验所总结出来的心得，都用六步骤来检验。符合六步骤的， 它就是对的。 注意第三步，立即觉察到自己当下的感受是来自想要 控制还是想要认同，并且释放它。 当你当下的感受是想要控制时，就释放想要控制，而 不是让想要控制待在里面运作你。 如果你努力去尝试用力觉察、挖掘，那就是带着想要 控制来做，你应该觉察到这个想要控制，释放掉它。 不是用头脑的问题，是 how you direct it ，方向是什么， 莱斯特描述为&quot;用心智来消除心智&quot;，最关键的是，它导 向的方向是什么。 幸福猫咪： 可以理解为头脑给出一个方向，然后就见 证“无限”来完成吗？ 风： 不是，要符合释放流程，符合六步骤，不是&quot;抛 弃头脑&quot;，不是&quot;不控制&quot;，而是&quot;通过释放流程来做你 想要的事&quot;，莱斯特说的不是&quot;你不应该想要这个、想要 那个&quot;，莱斯特没有谴责那些&quot;想要&quot;，而是&quot;通过释放 来得到你想要的一切&quot;。所以，通过释放流程，符合六步骤， 保持简单，不要掺入其他的东西了。</p><hr><h2 id="page-253" tabindex="-1">第 253 页 <a class="header-anchor" href="#page-253" aria-label="Permalink to &quot;第 253 页 {#page-253}&quot;">​</a></h2><p>253 流程是固定的：就是让感受浮现，看到它是想要控制 还是认同，然后让它离开。 不符合六步骤，就释放不下去。 做不到就是因为没有去做。 只要去做，就能做到。 把六步骤放在身边。 保持纯正，运用流程。 keep it simple ， sweetheart ， 这是莱斯特说的 kiss 原则。 莱斯特说，这很简单，但人们一直在做的，是把它高 度复杂化。 我们可以用很多语言体系来讨论一个相同的事，我们 可能转化很多表达范式，但是那些不是必要的。 必要的是什么？学会释放流程和六步骤，这是你在达 到自由这条路上所需要的一切工具和地图。</p><hr><h2 id="page-254" tabindex="-1">第 254 页 <a class="header-anchor" href="#page-254" aria-label="Permalink to &quot;第 254 页 {#page-254}&quot;">​</a></h2><p>254 【2020.11.17当你的释放停下来的时候，你需要提醒自 己去做释放，但当你在压抑的时候，你需要提醒自己放轻松】 风： 都别忘了目标，先咬一口，先得到好处。（笑） 伯利恒之星： 接下来血盆大口。（笑） 我是无限： 嗷～ 风： 你的锅呢?还有iPhone手机。 伯利恒之星： 两个哦。（笑） 我是无限： [无奈]又忘记了。 风: 习惯性忘记,因为对目标的厌恶,形成了逃避的 习惯。（笑）不相信自己能通过释放得到它。 我是无限： 确实我感到了那种厌恶，因为我觉得很难 实现，所以非常厌恶。 风: 还是得突破这个很难实现的厌恶，也只是一种感 觉，just a feeling。 chloe: 我发现释放嗨很容易，但低级别的比如悲苦， 万念俱灰就没那么容易。这是为什么? 风： 莱斯特说过，因为太沉重了，所以你容易陷入。 所以当你high的时候，是一个很好的机会去dig down。</p><hr><h2 id="page-255" tabindex="-1">第 255 页 <a class="header-anchor" href="#page-255" aria-label="Permalink to &quot;第 255 页 {#page-255}&quot;">​</a></h2><p>255 释放到high的时候，你有力量往深处看，把那些更沉重 的情绪带出来释放，这就是为什么你需要好处。 另外，在agf非常容易卡住，我自己也是这样的。因 为agf的状态太低了，很容易让人觉得自己不行，放弃释放。 而如果你鼓足劲去释放，又可能被恐惧支配，用力过 猛。所以我在agf释放的时候，释放几次就得看一次第五步。 要持续释放，又不能用努力。 Roller: 嗯是的啊，第五步在一开始是很重要。 (接着风分享了一段和阿恒的私聊对话) 风： 每一次都感觉到很轻松快乐，释放本身就很有乐趣。 伯利恒之星： 对，释放也应该是effortless的，你 没注意到的时候它已经完成了。 风： 所以努力释放的时候，还是要注意那是想要控制。 第五步。努力的时候，就是想要控制。 伯利恒之星： 嗯嗯，释放需要持续不断，不是努力。 风： 是的，我在巴利三藏里看到一段话，佛陀的话。</p><hr><h2 id="page-256" tabindex="-1">第 256 页 <a class="header-anchor" href="#page-256" aria-label="Permalink to &quot;第 256 页 {#page-256}&quot;">​</a></h2><p>256 伯利恒之星： 完美，有时我们用了太多的force,而 不是power。 风： 其实是在压抑感受。所有的努力都是在努力压抑 感受。 伯利恒之星： 某种程度上是的。 风： 控制。 伯利恒之星： 控制这个过程，想看到结果。这不是好 的释放者需要做的。 风： 嗯，还是在六步骤里，第五步的状况。 译文：站在一边的天人问世尊：“阁下如何度过洪流？” “朋友，我以不停留（或：不住立）、不用力度过洪流。” “然而阁下，怎样以不停留、不用力度过洪流？” “朋友，当我停留时，则沉溺；当我用力时，则被漂走。 所以我以不停留、不用力度过洪流。”</p><hr><h2 id="page-257" tabindex="-1">第 257 页 <a class="header-anchor" href="#page-257" aria-label="Permalink to &quot;第 257 页 {#page-257}&quot;">​</a></h2><p>257 (大家看完风和阿恒的私聊后继续聊天) Roller： 我之前想要控制的倾向太严重了。（笑） 伯利恒之星： 我也是。 Roller： 没事，当你释放了足够多的想要控制，后面 就简单了。 风： release takes no effort ， zero 。 我是无限： 我一不留神就变成了努力去释放，然后可 能就被压抑了。 风： 想要控制的倾向太强烈了，情绪太沉重，这是正 常的。在agf释放是会有一些困难，那时候我也经常卡住， 逢人就探讨卡住的问题。 Roller： （笑）现在就看看第五步。 我是无限： 估计大部分人都不知道卡住是什么。 Roller： 海尔称之为抵触。 我是无限： 一卡住就努力去释放就变成压抑了，然后 情绪没了，就以为释放了。 风： 你用力当然就会卡住。accumulated garbage（积 压的垃圾）太多了，Stephen都说不容易。</p><hr><h2 id="page-258" tabindex="-1">第 258 页 <a class="header-anchor" href="#page-258" aria-label="Permalink to &quot;第 258 页 {#page-258}&quot;">​</a></h2><p>258 【2021.7.26】 云飘过的声音： 老师，可以深入讲解 一下这段吗？（指前面提到的度过洪流那一段）在日常生 活中怎样才能做到？ 我头脑理解这个道理， release takes no efforts ， 但我怎么做才能做到呢，生活中的事那么多。 风： 这一段是巴利三藏中记载的佛陀的言教，它阐述 的道理，佛陀总结为中道。 当佛陀还是悉达多的时候，他参学当时的各个大师， 学到了禅定的最高阶段。但他发觉，那些被抑制的感受， 就像沉到河底的泥沙。当他处在定中的时候，它们都被镇 压了。但当他从那种高度专注中出来的时候，感受和思想 又再次包围着他，就像被搅浑的河水。 随后，悉达多继续前行，从耆那教的苦行僧那里听来 了苦行的教义。他经历了六年苦行，但却没有感受到解脱。 中道的思想，是他在极度失望的时候，从一位弹琴的 人那里听到的：琴弦过紧的时候，你就需要调松。琴弦过 松的时候，你就需要调紧。这样，你就能理解那段话。 当你的释放停下来的时候，你需要提醒自己去做释放， 但当你在压抑的时候，你需要提醒自己放轻松。 云飘过的声音：嗯嗯，非常感谢您，老师，明白了。</p><hr><h2 id="page-259" tabindex="-1">第 259 页 <a class="header-anchor" href="#page-259" aria-label="Permalink to &quot;第 259 页 {#page-259}&quot;">​</a></h2><p>259 风谈六步骤 Step 6 【2020.10.24释放的感觉用第六步来核实，每一次释放 都能带来轻松愉悦】 风：如果每一次释放都能带给你轻松愉悦，那就是在释放。 如果你释放停下来了，那就是卡住。 持续释放你的感受，持续更加轻松和愉悦。 第六步: 每次你释放，你都更愉悦、轻松、脱离 限制，随着释放，你会越来越愉悦、轻松、脱离 限制。 Each time you release,you are happier and lighter.You have more motivation to go free.</p><hr><h2 id="page-260" tabindex="-1">第 260 页 <a class="header-anchor" href="#page-260" aria-label="Permalink to &quot;第 260 页 {#page-260}&quot;">​</a></h2><p>260 【 2020.10.22释放了遮盖本性的感受，自然会感到愉悦 】 风：你可以随时用第六步来核实自己的释放，感到轻 松愉悦后，继续释放想要认同和控制。 因为你的天然本性是很愉悦的，只要没有愉悦，就是 还有东西覆盖着，这很容易理解。 【 2020.10.22每一次释放带来愉悦和自由会让你自然想 继续释放 】 不卡住的释放，是每一次释放，你都更轻松愉悦自由。 用第六步确证你的释放。如果你感觉自己在和它打持久战， 就是胶着了。如果你感觉释放很用力，就胶着了。 这个必须注意，释放不是持久战。我知道持续释放听 起来像是持久战，但其实不是，释放是每一次都会带给你 极大的愉悦和自由，然后你自然会想要继续释放下去。 【 2020.10.23每一次释放，都会更轻松愉悦 】 风：第六步的意思是，每一次释放，都会更轻松愉悦。 注意，是释放带来的愉悦，不是通过别的限制性的方 式带来的愉悦。</p><hr><h2 id="page-261" tabindex="-1">第 261 页 <a class="header-anchor" href="#page-261" aria-label="Permalink to &quot;第 261 页 {#page-261}&quot;">​</a></h2><p>261 【2020.10.18第六步带来的自由感会加强第一步想要自由】 风：第六步，也是我们最容易忽视的一步。 每次释放都会让你更自由，当然也用轻松、愉悦来形容， 但归根结底就是自由。 这些体验带来的动力会让你加强第一步的想要自由， 而莱斯特说过&quot;如果你彻底做到第一步，你会自然贯彻下 面的五步&quot;。 【2020.11.20用第六步来促进第一步，逐渐转向】 天成： 你是如何真正做到达成第一步的？ 风： 贯彻六步骤。用第六步的gain来促进第一步，它 是一个完美的过程。 你平时在世界的所有地方寻找快乐，它会形成你的主 要目标，但是当你通过释放来收获，你会越来越发现快乐 的来源，直到你发现快乐的唯一来源是你内在的无限存在， 你就会失去所有的外在目标，你的整个方向就会调转，会 达到第一步。当你达到第一步时，就会掉入后五步。 重视第六步 释放带来的轻松愉悦会极大促进第一步</p><hr><h2 id="page-262" tabindex="-1">第 262 页 <a class="header-anchor" href="#page-262" aria-label="Permalink to &quot;第 262 页 {#page-262}&quot;">​</a></h2><p>262 【2020.10.22每次释放提醒自己第六步，会极大加快释放进度】 风：想要自由是需要动力的。而每次提醒自己第六步， 会在很基础微妙的层面给自己的第一步施加一个动力。这 会极大加快你的释放进度，因为后面几步会自然而然地被 贯彻下去。 第六步的关键词是“更”。每一次释放，都会更愉悦 轻松，以及自由。 注意是每一次，只要你有一次卡住，你就不想释放了。 逃避的动力很快就会把你拉到相反的方向。 记得我前几天说的吗？整个心智都是想要，所以在你 自由之前，你总会有想要。区别是 how to direct it ，你是 把它导向自由的方向，还是导向限制的方向。 想要自由，导向的是继续释放。也就是你做了第一次， 你知道下一次你会感觉更好，体验到更多自由，你自然想 要做第二次。 感觉到喜悦之后，继续释放。 然后你会更喜悦，感觉更自由。 接着你再释放，就会再次飚高。 感受不断往上飚。 接连不断的喜悦会给你继续释放的动力。</p><hr><h2 id="page-263" tabindex="-1">第 263 页 <a class="header-anchor" href="#page-263" aria-label="Permalink to &quot;第 263 页 {#page-263}&quot;">​</a></h2><p>263 【2020.10.23释放没有感觉到愉悦怎么办】 我是无限： 第六步怎么弄？ 风： 每一次释放，都会带来轻松愉悦。 我是无限： 都释放不动，肯定没有愉悦。 风： 如果你提醒自己这个 （指第六步） ，你就会停下 来你现在做的，轻松地去允许想要控制浮现。 凡是你运用努力，就是想要控制，愉悦感是会卡住的， 因为你想要控制它。 看来很多人都不知道第五步怎么操作，我具体分享一 下，如果你跟着原始流程做，你会发现第一步是“让自己 尽量放松，将注意力集中到内在”，在身体放松舒适的状 态下觉察到你此刻的感受。 第五步的具体用法，确实是一件容易让人误解的事情。 因为人们往往会发现，自己感受不到对感受的想要控制， 这样，当你试图释放对想要控制的想要控制时，就会无限 卡住。所以要放松，去觉察最表面的“想要”，一次你只 需要觉察到一个“想要”。 当你卡住时，很显然地，你想要改变它，去注意到你 在用力，这个“用力”就是想要控制，它就在最表面，因 此你没有必要刻意去挖掘它。</p><hr><h2 id="page-264" tabindex="-1">第 264 页 <a class="header-anchor" href="#page-264" aria-label="Permalink to &quot;第 264 页 {#page-264}&quot;">​</a></h2><p>264 控制，是卡住的唯一成分。 另外一点，就是它和所有感受一样，并不是一次就能 释放掉所有，所以我在引导别人的时候，会说&quot;你还想要 改变现在的感受吗？&quot;允许更多想要改变被觉察到，当你 成功地释放了一次导致你卡住的想要改变，你要再去感受 是否还有剩余的，释放第二次。 直到你完全释放掉你对它的想要改变，你马上就会发 现这个释放过程会变得非常顺畅。如果你只释放了一点， 而把剩余的压抑进去，继续去带着这个想要控制去释放其 他主题，那么那个没有释放完的想要控制就会继续待在你 的内在运作你，你就会在某次释放的时候又再次卡住。 这也曾经是我一开始持续释放最大的阻碍，实际上我 们就是在释放的时候真的就只是忽视了它，所以，再次说 明，用六步骤，六步骤是唯一的关键，它不仅仅是一个理论， 它是一个在一路上会带着你走的地图。</p><hr><h2 id="page-265" tabindex="-1">第 265 页 <a class="header-anchor" href="#page-265" aria-label="Permalink to &quot;第 265 页 {#page-265}&quot;">​</a></h2><p>265 【2020.9.19真正的释放，每一次都有愉悦】 风： 释放的感觉，是你覆盖上面的感觉清晰离开，然 后下面有一阵愉悦涌上，这是一次释放。如果没有，那可 能只是大脑的想象。 随乐： 我就一次愉悦的感觉也没有过。 风： 嗯，那你就发现问题所在了。你必须先学会释放， 才可能谈持续释放的问题。真正的释放是，每一次都会变 得更加愉悦。 随乐： 我这释放的不对吗？ 风： 以我个人的体验来说，应该不对。因为释放这件事， 只要你体验过一次，就不会混淆。 随乐： 可能不对，应该怎么做呢？ 风： 释放法不复杂，就是 let up and let go （让感受 浮现，让感受离开），但是很多人在实际操作中没有体验 过释放，他们把头脑的某种想像当作释放了。 释放时尽量不要修改方法，那只会削弱方法的威力。 不要混搭，不要修改，这样试试看，能不能找到感觉。 释放是个很清晰的感觉，当你释放一次，你会发现这 个体验和压抑、逃避明显不一样，所以你不会混淆它们。</p><hr><h2 id="page-266" tabindex="-1">第 266 页 <a class="header-anchor" href="#page-266" aria-label="Permalink to &quot;第 266 页 {#page-266}&quot;">​</a></h2><p>266 随乐： 我的问题在哪呢？ 风： 我觉得你是在压抑情绪，习惯性压抑。我当年练 习《丰盛之书》，一直习惯性压抑，因为看到管子法，误 解了它的意思，就想象管子，努力把它往外挤。 后来也是看到书上的一句话，第一次体验到了释放。 那就是“感受自己也是想要出来的”，以及“解压（解除 压力）”。感受在把自己往外推，你只要不压住它，放手， 它就自己出去了。 那次体验颠覆了我对释放的理解，此后释放就很轻松 了，而且很清晰。多试着体验吧。 对我而言，念诵一百句上主也不如一次清晰释放带给 我的体验更加震撼。 所以，重点就在怎么释放和持续释放。 至于真相这个东西，持续释放你就能看到，没必要用 语言文字来不断研究它。再多的研究，也只是语言文字。 （注：此篇只摘选了部分对话，重点提醒大家重视自 己的释放，不要把没有释放当成释放了，勿忘用第六步检 验自己的释放。诚实面对自己的释放结果，才能更好前行。 不怕不会释放，怕的是不知道自己不会，把压抑当释放。）</p><hr><h2 id="page-267" tabindex="-1">第 267 页 <a class="header-anchor" href="#page-267" aria-label="Permalink to &quot;第 267 页 {#page-267}&quot;">​</a></h2><p>267 【2020.10.21持续释放你的感受，持续更加轻松和愉悦】 问：在愉悦感中怎么继续释放？ 风：觉察一下你对现在愉悦的感受想要做什么：你想 要维持这个愉悦？还是想要改变它，使之变得更愉悦？ 当你释放了这个想要控制，你的感受就会move up， 你会发现刚才的愉悦感只是相对的愉悦，前面还有更好的 感觉，然后你不断释放，感觉会更好、更好。所以不要止 步于此，向着终极自由而去。</p><hr><h2 id="page-268" tabindex="-1">第 268 页 <a class="header-anchor" href="#page-268" aria-label="Permalink to &quot;第 268 页 {#page-268}&quot;">​</a></h2><p>268 【2020.12.3持续释放无法靠逼迫达成，持续释放是建 立在第六步带来的轻松愉悦上】 风：你可以定释放次数，但是要注意，如果你用力过猛， 你会卡住。 你不能带着那种逼迫去做，六步骤的持续是建立在你 释放之后感觉更轻松之上的。 要牢记六步骤，用六步骤来导正自己的释放。</p><hr><h2 id="page-269" tabindex="-1">第 269 页 <a class="header-anchor" href="#page-269" aria-label="Permalink to &quot;第 269 页 {#page-269}&quot;">​</a></h2><p>269 【2020.11.17 你无法逼自己释放，你只有看到释放带给自 己好处才会释放，所以请不断确认自己释放的收获及你的 方向】 风：靠六步骤。从六步骤开始，从六步骤结束。 用你的gain确认你的方向。 持续释放变成你的&quot;任务&quot;了，这不好。持续释放是因 为每一次释放都有好处。 这是第六步说的：每一次释放都更轻松、更快乐。 你感到很好，所以继续释放下去。如果你只是强迫自己 释放，你会停下来，你进行不下去的，因为你一边在压抑 你对世界的欲望。 我的方法就是我不停确认自己的gain，以及自己的方向。 譬如她刚刚要听音乐，她想从音乐里面获得什么？那么 这个从释放中能不能获得呢？可不可以试一下呢？ 不断确认自己的收获就可以让你保持持续释放。如果你 说&quot;我行，我必须释放，我不能听音乐&quot;，这不会奏效，因 为你潜意识的一个方向是听音乐，被你压抑进去了。 你显意识和潜意识在拉扯。你不去看它，这不会成功。 写下你认为可以带来快乐的可能性，你认为哪些地方有</p><hr><h2 id="page-270" tabindex="-1">第 270 页 <a class="header-anchor" href="#page-270" aria-label="Permalink to &quot;第 270 页 {#page-270}&quot;">​</a></h2><p>270 快乐，你实际在哪些地方寻求快乐。 如果你压抑这些欲望，你是不可能做到第一步的。你可 以逼自己写作业和工作，但你没法逼自己释放。（笑） 让我详述一下莱斯特最喜欢的教导：get everything by releasing only。 你想要什么？你准备怎么样去做？为什么不通过释放获 得它？这是你实践的方式，你选择去释放。 有时候你可能一下午做别的事，不释放，那是因为潜意 识在寻求一些东西，你没有办法强迫自己释放。 你要看到你在寻求什么，并且问自己&quot;我能从释放中获 得吗？&quot;，看看哪种方式更轻松容易，更快乐，从而选择释放。 这就是为什么我说成功经验是重要的，你得先获得好 处，没好处你不会做的，它会想尽办法逃避释放、抵触释放， 这就是你的心智。 我记得我以前就说过，对第六步的重视让我真正步入了 持续释放。 （风接着分享两张和阿恒的私聊图片，内容如下） 伯利恒之星：昨晚一晚都在很用力释放，没啥收获，放 松下来才有点收获。</p><hr><h2 id="page-271" tabindex="-1">第 271 页 <a class="header-anchor" href="#page-271" aria-label="Permalink to &quot;第 271 页 {#page-271}&quot;">​</a></h2><p>271 风：你看，用力释放是违背第六步的，你在试图控制 。 伯利恒之星：绝对的（笑）。 风：所以它不会发生。 伯利恒之星：今天我才停下来，放松一些。 风：我注意到一点，卡住的时候，实际上你想要控制。 伯利恒之星：想控制才会卡（笑）。 风：但是你取得你想要的方式是通过用心智努力对抗， 这就不是“get everything by releasing only”,你在尝 试用世间的挣扎的方式去做释放。 伯利恒之星：不停地fighting,fighting,fighting， 我发现相互提醒真的很好。 为什么很多人一释放就想要睡觉？很简单，因为相比强 迫的释放，睡觉让你更舒服。心智总是倾向于做更舒服的事。 这就是莱斯特为什么总是要你确认你的gain，这点很 重要。第六步不能被忽略，所以，你得不停获得好处。 从每一次释放开始，每一次释放，你都要感觉更好才行， 你这样才能做下去。</p><hr><h2 id="page-272" tabindex="-1">第 272 页 <a class="header-anchor" href="#page-272" aria-label="Permalink to &quot;第 272 页 {#page-272}&quot;">​</a></h2><p>272 一旦发现强迫、努力，你要马上放轻松，释放想要控制。 如果释放比睡觉更让你舒服，你就自然倾向于释放，这 真的很简单。 所以我说你没看到完整的道路，自然会有疑惑。如果你 经验了六步骤，你就会知道它的完美，莱斯特的所有指引 都是关于它。没有它在身边，你偏离道路是不自知的。</p><hr><h2 id="page-273" tabindex="-1">第 273 页 <a class="header-anchor" href="#page-273" aria-label="Permalink to &quot;第 273 页 {#page-273}&quot;">​</a></h2><p>273 六步骤是带我们上路的工具，用它替代头脑， 用它作为我们的头脑。拿在手上，放在身边。 六步骤一定要清晰，对它清晰，它就会带你上 路。怎么样叫清晰？能够使用，能够持续释放，你 就清晰了。 六步骤没有一步能被忽略，有一步做不到，就 会停滞。你没法说，&quot;先忽略第几步&quot;，这样释放 就会做不下去的。 贯彻六步骤很简单，保持限制很困难。看到感 受，让它离开，清空所有驱动你思考的感受，就是 这样。 做出自由的决定，决定在达到自由之前，不要 停下来。 ——风</p><hr><h2 id="page-274" tabindex="-1">第 274 页 <a class="header-anchor" href="#page-274" aria-label="Permalink to &quot;第 274 页 {#page-274}&quot;">​</a></h2><p>274 在六步骤中，你的释放会是持续的， 在六步骤中，愉悦也是持续增加的。 不在六步骤中，你就会停下来。 六步骤没有的，都不需要。 把它放在身边， 时刻提醒自己。 ——风</p><hr><h2 id="page-275" tabindex="-1">第 275 页 <a class="header-anchor" href="#page-275" aria-label="Permalink to &quot;第 275 页 {#page-275}&quot;">​</a></h2><p>275 为什么强调只符合六步骤？因为头脑会根据不 同的限制性的观念添加很多多余的东西在上面。 六步骤就是一条笔直的通道，跟着头脑的知识 走，则中途很可能拐到其它方向去。 要让释放法帮助到每一个人，请所有人携手让 它保持纯正。 ——风 2020.10.23</p><hr><h2 id="page-276" tabindex="-1">第 276 页 <a class="header-anchor" href="#page-276" aria-label="Permalink to &quot;第 276 页 {#page-276}&quot;">​</a></h2><p>276 ∞附录一 风： 体验到释放的简单高效后，我放下了其他所有 方法 你会发现，圣多纳释放法是当今世界上唯一有效 的，且能很快被你的经验所证明的简单方法。 每个人，在他或她的每一个行为中，都在寻找我 们现在内在的终极状态，但他们是在它不存在的地方 寻找它--在物质世界中。这个方法将使你能够得到 你想要的任何东西，并帮助你达到到最高境界。 这个世界目前需要的是爱，更多的爱，现在由你 通过使用释放法的经验来证明，其只是简单地释放非 爱，而进一步让你将本已自然存在的爱表达出来。 你的生活将变得更健康、更幸福、更丰盛。祝你 好运，并祝你成功。 ——莱斯特</p><hr><h2 id="page-277" tabindex="-1">第 277 页 <a class="header-anchor" href="#page-277" aria-label="Permalink to &quot;第 277 页 {#page-277}&quot;">​</a></h2><p>277 【2020.11.14】 风: 我学过很多东西，很多不同的教导。但是我的体验 告诉我那些会花上很长很长的时间，或者到不了终点。只有 释放法让我体验到高效，能够很快到达。 我一直不理解这个，我觉得其他方法应该也是有用的， 但是我的体验却告诉我释放法是唯一高效的。 直到我看到莱斯特这句话，在音频里听到其他几句话， 我立即明白了，释放法并不是众多方法中的其中一种，它 是当今世界唯一简单可行的方法，是整个世界范围内，the only method。其他方法中出来的&quot;大师&quot;你可以直接判伪了。 除了回来传法的，比如瑜伽的一些大师，很多都是前世 修的很好回来的，但尤迦南达最看好的弟子好像也没有通过 克利亚瑜伽开悟。 克利亚瑜伽已经是&quot;飞机&quot;之路了，是瑜伽里面最快的， 释放法是火箭之路，最为直接。 Go All The Way: 莱斯特还说过，将来会有让人一瞬间就 自由的方法。 风: 未来会有，不在这个时代。过去没有出现释放法， 也是因为整个世界没有到那个阶段。 Roller： 方法都是应时而生的。</p><hr><h2 id="page-278" tabindex="-1">第 278 页 <a class="header-anchor" href="#page-278" aria-label="Permalink to &quot;第 278 页 {#page-278}&quot;">​</a></h2><p>278 Go All The Way: 嗯，就算是现在，释放法也是少数人在做， 极少数人没有扭曲这个方法。 Roller： 目前学释放法的基本都没看重六步骤。 风: 其实这个很奇怪，莱斯特强调过很多次六步骤，kam 也强调过。我一直是自己一个人释放，从起先开始就非常重 视六步骤。 Roller： 可是大多数人真的只是把他用来释放情绪，改善 生活，就像你所说的大多数人的业力使他们能重视这个方法 多少。就拿六步骤第三步来说，很少人去做到，都是在表层 挤柠檬的释放，更不用说其他几步了。你起先没做到第一步， 做到最后五步，你都会有一个超大的move up。 风: 从欲望释放是必须的，这是六步骤的第三步。不这样， 你就无法还原这个方法的高效。</p><hr><h2 id="page-279" tabindex="-1">第 279 页 <a class="header-anchor" href="#page-279" aria-label="Permalink to &quot;第 279 页 {#page-279}&quot;">​</a></h2><p>279 【2020.10.1】 风: 我自己也读过很多宗教、哲学、禅修的东西，现在 都不讲了,因为这些概念性的东西很多时候是障碍。我当年 学佛的时候也很认真，学巴利文读巴利三藏。 大路zheng： 为啥佛法放下了？ 风: 因为释放法对我来说更高效，莱斯特说仅仅释放一 次就等于冥想几个月，这个对我来说很确切，因为我的体验 就是这样。 以前内观修的也还不不错，但它的确不如释放法高效， 于是我就不管它是什么，就用对我最高效的东西。 现在别人讨论佛法，一般我不插嘴。因为我相信这种形 而上学的讨论往往是无益的。现在讨论就集中在“怎么做”上， 怎么做到，怎么到达。即使学佛法，也是如筏喻者，要知道 怎么过河，而且专注点在这上面。 在研究上我花了很多年，以前我较为知识型，但它带给 我的领悟不如我短短的时间内所做的释放大。 对自己真诚一点就能发现，自己到底在原地踏步，还是 在前进。你接受一些概念性的东西、知识性的东西，很容易 让自己有一种错觉，你觉得自己知道得很多，但那不过是头 脑的积累。</p><hr><h2 id="page-280" tabindex="-1">第 280 页 <a class="header-anchor" href="#page-280" aria-label="Permalink to &quot;第 280 页 {#page-280}&quot;">​</a></h2><p>280 头脑并不能理解头脑之外的东西，它只是用一种已有的 经验来揣测一种你没见过的东西。 想象、模拟，和真正见到差别又是巨大的。释放法的学 习是体验式的，experiential。 我见过很多灵修和传统宗教的人，脑袋里塞满了各种见 解，真的很难进步。 今天谈到星空的翻译，星空是早期传播释放法的人，我 很感激他的传播，但是他翻译的东西有一个问题，揉进了太 多灵修惯用词汇。但其实莱斯特先生不喜欢用那些词汇，莱 斯特喜欢用最简洁的语言来表达那些艰涩的概念，他喜欢用 日常英语，所以我做翻译也尽量是往日常走，尽量不用那些 大词。 莱斯特的风格和其他的大师不太一样，他很少使用那些 古典宗教意味很浓的词。但他们这样一翻译，又把那些词重 新加上去了。 所以我如果谈释放法理论，会给自己一个原则，我绝对 不使用莱斯特体系以外的东西来讨论它，所有的语言都是他 自己说的。 我不会用佛法来讨论它，哪怕我学过佛法。我不会混杂 两位大师的教导，因为我相信他们各自的道路都是完整的， 不需要我们这些小我用头脑去衔接拼凑。</p><hr><h2 id="page-281" tabindex="-1">第 281 页 <a class="header-anchor" href="#page-281" aria-label="Permalink to &quot;第 281 页 {#page-281}&quot;">​</a></h2><p>281 我以前读巴利文和英译对照版，花了七八个月时间。 我觉得把各种教导合起来是一个挺奇怪的事，难不成每个大 师都不教完整的地图，需要你用头脑去拼一下？ 米妮： 风，释放法涉及宗教信仰吗？ 风： 不涉及。莱斯特说“不要相信我说的话”，the way里面还引用拉玛纳的话说，没有神，只有你自己。 最重要的是释放法不需要强加给你一套信念系统。你释 放，然后从内在获得领悟，这个不是传统宗教让你先相信一 套东西。 你可以有，但是随着释放，你会自己看到真相。那时候 你不在相信的层面运作，而在知道的层面。你知道是那样， 不需要借助一套心智中的信念系统来相信什么。 莱斯特也经常提到耶稣基督，以及那句“ I am that I am ”， 这是圣经里面表达无限存在的最好的一句。 D： 米妮，莱斯特还说过：你如果完全臣服，你甚至可 以和耶稣去喝咖啡。 风： 嗯，莱斯特说过，只要你接受，你可以和耶稣坐在 一起喝咖啡。 我也学过圣经，纯粹是作为知识性学习。从经院哲学体 系，奥古斯丁、阿奎那、莱布尼兹神义论。尤迦南达实际上</p><hr><h2 id="page-282" tabindex="-1">第 282 页 <a class="header-anchor" href="#page-282" aria-label="Permalink to &quot;第 282 页 {#page-282}&quot;">​</a></h2><p>282 也注释过一段圣经。莱斯特经常提两个开悟者，一个是尤迦 南达，一个是拉玛纳马哈希，古代的主要提佛陀和耶稣。 【2020.10.15】 风: 我想到一个好玩的事，刚开始学释放法时，因为它 太简单了，所以我的头脑总是抗拒用释放法。 我想: 难道我学习巴利语，阅读三藏经典，学习德语研 究古典哲学，学了无数佛教、道教、哲学、神学理论，最后 用的居然是一个这么简单的方法？ 我当时很抗拒用释放法，它越有效，我越纠结。难道这 些东西都白学了吗？ 现在我可以很明确地回答自己：是的，白学了。 想要自由的人不会欺骗自己的。 随着释放，虽然和别人争论的越来越少，但是内心越来 越笃定。</p><hr><h2 id="page-283" tabindex="-1">第 283 页 <a class="header-anchor" href="#page-283" aria-label="Permalink to &quot;第 283 页 {#page-283}&quot;">​</a></h2><p>283 对话一：成功之道——六步骤 问: 老师，可以说说你的成功之道吗？ 风: 六步骤。 问: 为什么你可以做到？而那么多人做不到。 风: 六步骤。因为你需要别的，而我只需要六步骤。 问: 所以，必须要在行动中做。 风: 关键是你没去做。没过多久，你又想到一个心智 的问题，于是开始研究起来，就像这个问题一样。 六步骤里面没有矛盾，但如果你去抠莱斯特的文字， 用你的心智加以曲解加工，你总能找到所谓的“矛盾”。 它会立即让你走向限制的方向。 ∞附录二 风： 六步骤以外，不需要任何别的东西。无论发生什 么也只是六步骤 感谢天成整理分享</p><hr><h2 id="page-284" tabindex="-1">第 284 页 <a class="header-anchor" href="#page-284" aria-label="Permalink to &quot;第 284 页 {#page-284}&quot;">​</a></h2><p>284 那些心智问题，那些偏离六步骤的内容，就会让你偏 离自由。 我是一个智性很强的大脑，但我正确地运用了我的智 性，也就是，认识到心智的限制。 在整个过程中，我只看六步骤。我不需要六步骤以外 的任何东西。如果要说成功秘诀的话，这就是秘诀了。 不停搜集资料的人是达不到终点的，尤其是他们的智 性头脑还分辨不了那些内容。 问: 那我该如何做才能到达终点？ 风: 六步骤。</p><hr><h2 id="page-285" tabindex="-1">第 285 页 <a class="header-anchor" href="#page-285" aria-label="Permalink to &quot;第 285 页 {#page-285}&quot;">​</a></h2><p>285 对话二：在所有的帮助中，没有比毁掉支柱更好的帮助 问: 老师，这次你真的是彻底离开吗？ 风: 嗯。我会离开世界。 问: 直接融入无限？ 风: 不是。不再与人交流。人们所说的isolation。 问: 这是你的内在指引吗？ 风: 嗯，当我决定了，我就去这样做了。 问: 老师，为什么不能继续帮助我们呢？ 风: 离开才是帮助。我看得到全景。如果我待在这里， 不会有任何人自由。依赖关系对成长而言是致命的。 问: 但在我需要你的时候，你可以来帮我吗？ 风: 彻底离开就是帮助。一个无限存在需要帮助吗？ 当你向外寻求帮助的时候，那是一个机会，觉察到它，释放。 向内找到你想要的一切，绝对的安全感只有在你的无 限存在里才有。 在所有的帮助中，没有比毁掉你的所有支柱更好的帮助。 （风下面引用了一段《我和莱斯特》书中的话）</p><hr><h2 id="page-286" tabindex="-1">第 286 页 <a class="header-anchor" href="#page-286" aria-label="Permalink to &quot;第 286 页 {#page-286}&quot;">​</a></h2><p>286 莱斯特告诉我世界会“击垮他的支柱”，所以每个人 都会被迫从内在寻找答案。 “那很好”，他说。 “不是爆炸，而是扬升”，他笑道。 目前，人们总是用世界提供的各种逃避方式在外界寻 求快乐。最终当外界的逃避没完没了时，他预言，我们就 会被迫进驻到内在。 “这真是件好事”，他说， “因为人们会被迫找到答案， 知道他们真正是谁，就像我一样。”他总是对我说他特别 感谢他的心脏病。 风: 当外界的逃避方式都被击垮，你会被迫进入内在， 但你可以变得更有意识，更主动一些，不要等枪顶着脑门 再去做。 你们都非常清楚自己，尽管不是那么深入，但是会知 道自己的行为，有依赖你就会抓着。你依赖外界，就发现 不了内在的无限。这些东西都很简单。 释放法作为自立的方法，并没有那么多问题。所有的 问题，都是在你偏离六步骤时产生的，因此，要么你回到 六步骤上继续释放，要么你走向限制。</p><hr><h2 id="page-287" tabindex="-1">第 287 页 <a class="header-anchor" href="#page-287" aria-label="Permalink to &quot;第 287 页 {#page-287}&quot;">​</a></h2><p>287 我作为一个获得终极自由的人，是不能在这里的。 问: 为什么终极自由的人不能在这里？ 风: 莱斯特待在这里几十年，都是在重复这些，用他 自己的话来说，“over and over and over and over again”，他不断重复讲同样的东西。 他走之前一年，和他的一位学生说，我不能待在这里 了，我在这里，你们只会依赖我，没有人会自由的。 因为他们认为莱斯特在这里，可以指导他们，因此 就不断忘记。莱斯特离开之后，过了没多久，Sedona institute那位女士就获得了自由。 我和莱斯特聊到很多他过去的事情，他在世的时候， 没有人在他的指导下获得自由。 问: 你和莱斯特聊天啦？ 风: 我经常和莱斯特聊天。 问: 这位自由的大师是释放法教师还是学生来的？ 风: 学生。没有释放法教师获得自由。而且莱斯特指 定的释放法教师大部分是他觉得倾向不那么好的，也就是 更倾向于世界的。 问: 你们是怎么聊的呀？</p><hr><h2 id="page-288" tabindex="-1">第 288 页 <a class="header-anchor" href="#page-288" aria-label="Permalink to &quot;第 288 页 {#page-288}&quot;">​</a></h2><p>288 风: 自由的人之间不需要任何媒介沟通。存在于每一 个点。我们之间并没有分离。 问: 我现在没有做释放法教师的想法了。 风: 你未来或许会有，除非你释放了那些程序的驱动。 如果你不释放，它就会不断驱动你去整活。 所有的精彩，所有的创造力，都来自无限存在。心智 是机械化的程序，只会重复。或许可以这样说，一个从心 智程序中自由的人，才真正开始活着，此前只是被不断驱 动的机器人。 问: 昨天有位朋友找我，交流释放法内容后，他给我 发了一些金钱，这次我拒绝了哪怕现在还挺穷。因为我不 想用释放法来收费。 风: well，用这个赚钱会给你一个错误的反馈。用谈 论释放法来代替实际去释放。这些是很容易让人偏离的。 此外，灵性书籍也最容易让人偏离，因为阅读那些书 籍时，人们会骗自己在路上。当你偏离时，如果你知道自 己在偏离，那就可以转回来。 所以，你不需要六步骤以外的东西。the way是好的， 那些大师的书也是好的。终极自由之路，也是好的。 但当阅读它们让你停止释放时，它们就不是好的。</p><hr><h2 id="page-289" tabindex="-1">第 289 页 <a class="header-anchor" href="#page-289" aria-label="Permalink to &quot;第 289 页 {#page-289}&quot;">​</a></h2><p>289 Ralph曾经拿着一本拉玛那马哈希的书，不断阅读，进行 研究。 后来莱斯特说，你疯了，你本来可以释放的。莱斯特 和我说，他无数次去试图纠正学生的倾向。 他的学生会想出很多逃避的方式，譬如询问“我是什 么”，这是一个很高大上的逃避方式。 莱斯特在一段特定时期倡导过这个方法，但是，他们 只是在逃避释放而已。 在这个法门还有可能成功的时代，他教导过。在1970 年结束，已经不会再有人用这个方法成功了。 问: 老师，你还有什么要和我说的吗？ 风: 其实上面的都不用说，说的越少越好。心智积累 那些东西有用吗？为了达到自由，所有的积累都要被释放 的。 就连克利亚南达尊者，都会被障碍，他逐字逐句地回 忆尤迦南达的教导。这有用吗？这完全没有用。他为自己 的上师写书和宣传，代替了实际去做。自由，要去做到才行。 问: 实际上，克里亚南达尊者到达了哪里？ 风: 克利亚南达尊者到达了禅定的阶位，但没有到达</p><hr><h2 id="page-290" tabindex="-1">第 290 页 <a class="header-anchor" href="#page-290" aria-label="Permalink to &quot;第 290 页 {#page-290}&quot;">​</a></h2><p>290 三摩地。 问: 所以还是会退转的？ 风: 嗯，只要你做不到，说再多都没有用。 问: 尤迦南达大师有没有继续帮助他？ 风: 最好的帮助就是离开。 问: 尤迦南达离开克里亚南达是最好的帮助？ 风: 尤迦南达只要在，他永远望着上师，永远把上师 作为知识和力量的来源。而这是不可能自由的。任凭他怎 么呼唤，尤迦南达也不会来。 要调转方向，必须让你在外在找不到安全感。当你在 外在找不到一位大师，你才会在自己的内在找到。 问: 你没有依赖上师，这是你成功的一个优势吗？ 风: 嗯。而且我从来没有想过呼唤莱斯特或者其他大 师。我在学习大乘佛教时，就倾向禅宗而远离净土宗。那 是我的优势，我只想要自己独行。 问: 自立。 风: 嗯，那是我很长时间以来的一个倾向。 问: 之前在群里看你的分享还挺有用的。</p><hr><h2 id="page-291" tabindex="-1">第 291 页 <a class="header-anchor" href="#page-291" aria-label="Permalink to &quot;第 291 页 {#page-291}&quot;">​</a></h2><p>291 风: 当你觉得看什么东西有用，你就会不停去看它。 回到六步骤的话，就会很简单。 但是看其他的文字，哪怕是大师的教导，哪怕是莱斯 特本人的教导，都会让你的心智越来越复杂化，因为心智 倾向于复杂化。 你还喜欢戒禁取，摩西和耶稣教导中所禁止的偶像崇 拜，佛陀把一类行为称之为戒禁取，即认为祭祀等活动有 益于解脱。 其实，没有用。你那些整理大师照片的行为，统统没 有用。相反，这是基于一种邪见，戒禁取见。 你认为和那些外在的形象和仪式相关的事情有帮助， 当你这样做时，你加深了这种见解，也就远离了只有在内 在才能找到的无限存在。 你认识了大师，却仍以世俗的迷信方式对待他们。 问: 是的，我不得不承认。那我该怎么办？ 风: 怎么办？解决方法只有一个。六步骤。释放。如 果我说还有第二条解决方法，你就不会去释放。 问: 老师，我还有什么错误都请你说出来 风: 你现在就在犯错，因为你没有释放，没有在释放</p><hr><h2 id="page-292" tabindex="-1">第 292 页 <a class="header-anchor" href="#page-292" aria-label="Permalink to &quot;第 292 页 {#page-292}&quot;">​</a></h2><p>292 就是错误。任何时间，任何地点，没有在释放就是错误， 哪怕你是在听我讲话。 问: 老师，你在离开前可以给我留一封信吗？ 风: 不会。六步骤。贯彻六步骤，走向终点。 希望在我离开之后，你不要再依赖那些文字或者其他 的什么，而是直接走向终点。 again，六步骤以外，不需要任何别的东西。无论发 生什么也只是六步骤。</p><hr><h2 id="page-293" tabindex="-1">第 293 页 <a class="header-anchor" href="#page-293" aria-label="Permalink to &quot;第 293 页 {#page-293}&quot;">​</a></h2><p>293 对话三：积累概念性的东西只会让你无意识偏离自由的 道路，看资料带来的清明比不上释放带来的清明 2020.3.17 大黄猫: 风老师，可以这么说么，朗读和看书，都是 逃避释放？ 风: 是的。而且看灵性相关的书尤其有一个坏的作用。 天成： 老师，有什么坏的作用？ 风： 因为它用谈论自由代替了真正去自由。在你看电 影看小说的时候，你知道自己在反方向，你是有意识的。 但当你看灵性书籍的时候，你自以为自己在路上，这种偏 离是无意识的。这就是坏的作用。 另一点就是，积累那些你还没体验过的境界的知识， 会让你产生许多错误的想象。那些想象事实上并不会帮助 你抵达那一状态，反而会阻碍，或者让你的心智把并非是 那个的状态的东西当成那一状态。 （风接下来引用了《莱斯特对释放法的一些说明》中 的一些话） 你在心智中发展的任何东西都会阻止你达到顶端。心 智是你最大的敌人。</p><hr><h2 id="page-294" tabindex="-1">第 294 页 <a class="header-anchor" href="#page-294" aria-label="Permalink to &quot;第 294 页 {#page-294}&quot;">​</a></h2><p>294 全部的这些痛苦都没有任何意义，我已经受够了，我 结束了它们。我将全力保持在这种状态。 这需要花一个月时间，也许两个月时间，你就会释放 掉所有的agflap。但总而言之，我认为我们有这个释放心 智的唯一的方法，通过使潜意识程序展现出来，能够让心 智静止。 我们首先进入表意识，释放控制、认同。而其他那些 你试图去释放的，像恐惧——你知道的，你会花上成百上 千世去释放恐惧，在此之后你还会有愤怒，你还会有其他 的情绪。而当你释放掉了想要控制，在它之下的东西就全 部都被放走了。 然后当你释放掉想要安全，你释放了所有的想要认同 和控制，以及在它们之下的一切。你现在太低谷了，因此 不能向着想要安全发起进攻。你被压垮了、你被死亡给吓 住了，于是让它运作着你。但当你释放相当数量的控制和 认同，你就有能力去面对死亡的恐惧了。 但你们可以看到，我们的方法实际上是去释放心智的 驱动。不要试图发展你的心智，这样你是在发展你的敌人， 发展束缚住你的东西。 大黄猫: 风老师，整理你的资料，很受益啊，感觉更 清明了啊。</p><hr><h2 id="page-295" tabindex="-1">第 295 页 <a class="header-anchor" href="#page-295" aria-label="Permalink to &quot;第 295 页 {#page-295}&quot;">​</a></h2><p>295 风： 那比不上释放带来的清明。 天成： 嗯，发展心智的任何东西都是障碍，甚至包括 大师教导的内容。 大黄猫: 风老师，这真的太颠覆信念了。我总觉得看 风老师的资料和大师的资料，都是成长的台阶，了解这些 理论，才能更好的释放。 风： 那会让你自我感觉良好，但你没有释放。 （风接下来分享了两小段来自释放法纪录片《走完全 程》里的视频） Ralph也遇到过完全相同的问题，那时候他是在研究 拉玛那马哈希的书，包括冥想的问题也在上面。 释放法是最高效的方法，它不需要配合冥想、不需要 配合仪式、不需要配合咒语、不需要偶像崇拜、不需要团 体加持。事实上你用任何东西和释放法结合都只会削弱它 的威力，使它的效果变慢。 仅仅用释放法来释放，贯彻六步骤。 大黄猫: 风老师，在第二个视频里，“你完全在你的 头脑里获得这些概念性的东西”，当时我读到这里，还不 是很理解。今天才知道，不去释放，头脑知道的再多，也 没用。</p><hr><h2 id="page-296" tabindex="-1">第 296 页 <a class="header-anchor" href="#page-296" aria-label="Permalink to &quot;第 296 页 {#page-296}&quot;">​</a></h2><p>296</p><hr><h2 id="page-297" tabindex="-1">第 297 页 <a class="header-anchor" href="#page-297" aria-label="Permalink to &quot;第 297 页 {#page-297}&quot;">​</a></h2><p>297 随乐： 我们用释放的同时，再用上莱斯特在《爱的力量》 那本书里的爱的方法是不是更快些呢？ 风： 不是。事实上莱斯特在音频里告诉过你，他用了 三个月，这三个月里面有探索的时间。他说如果他一开始 就知道六步骤，他只会花一个月或者更少时间。 简单，或者不可能。 如果一个月你做不到，两个月你还做不到，那对你而 言自由就是不可能的。 你不可能把它拖到很长。你不可能说，我一天做一点 点，然后过十几年能自由。 贯彻六步骤，要么你在一两个月之内解决它，要么你 就一辈子做不到。 在： 为什么不能拖太长时间？ ∞附录三 风： 贯彻六步骤，要么你在一两个月之内解决它，要 么你就一辈子做不到 2020.12.16</p><hr><h2 id="page-298" tabindex="-1">第 298 页 <a class="header-anchor" href="#page-298" aria-label="Permalink to &quot;第 298 页 {#page-298}&quot;">​</a></h2><p>298 风： 因为如果你一两个月没有自由，那么你就不在六 步骤上。不在六步骤上，你怎么可能自由呢？ 随乐： 单纯用六步骤，不用结合爱的练习吗？ 风： 是的，六步骤是完整的地图，你不需要再给它添 加别的东西了。 按照六步骤释放，一个星期你就能达到极高的状态， 甚至进入涅比卡帕三摩地。 如果你把这个过程拖很长，那就一定不在六步骤中。 莱斯特告诉你，释放一次，相当于冥想好几个月，一次释 放只需要几秒钟而已。你只需要几秒钟就等于冥想了几个 月，这个方法是极高效的。 时代万物互联： 我们错在哪了呢？一天释放都不能到 达一次那个高度。 风： 你可以看看六步骤，就知道自己在不在里面。如 果你在六步骤中，你的释放会是持续的，愉悦也是持续增 加的。 时代万物互联： 第一步肯定没有。第二步，这个自由 的决定是决定自由还是决定释放？ 风： 做出自由的决定。决定在达到自由之前，不要停 下来。佛陀坐在树下时，决定“不找到解脱之道绝不起座”。</p><hr><h2 id="page-299" tabindex="-1">第 299 页 <a class="header-anchor" href="#page-299" aria-label="Permalink to &quot;第 299 页 {#page-299}&quot;">​</a></h2><p>299 在： 现在我们的程度不是可以先忽略第一步和第二步 吗？等到了预流果时，才会用到这两步吧。 风： 不是忽略第一步和第二步。第一步的完全达成， 需要预流，但是你如果不主动运用第一步和第二步，你也 不能达到预流。六步骤是需要你主动贯彻的，然后当你彻 底达成第一步，后五步就会带着你走。 时代万物互联： 那果真有时不是那么想要自由。 风： 所以对你们来说最具有实践性的就是莱斯特最推 荐的教导:get everything by releasing only。 因为你总是有想要，决定通过释放获得每一个想要的 事物，也会让你不停地释放。</p><hr><h2 id="page-300" tabindex="-1">第 300 页 <a class="header-anchor" href="#page-300" aria-label="Permalink to &quot;第 300 页 {#page-300}&quot;">​</a></h2><p>300 所有快乐，都来自于心智安静后，你看到了更 多的一些无限存在，只不过你错误地以为是外在的 某些人事物带给你的。 快乐的唯一来源就是你的无限存在。 人们所谓的性高潮带来的快感，也只是暂时让 心智安静而已。实现目标的快乐是什么呢？当你获 得某些事物，暂时允许心智安静一些。 当你追逐世界时，你是在发展心智，让心智变 得更加嘈杂，这是在加剧痛苦。 解除痛苦的唯一方式是调转方向，让心智安静 下来。因为快乐的唯一来源无限存在，只有心智安 静，无限存在才能显露更多。就是这么简单。 ——风</p><hr><h2 id="page-301" tabindex="-1">第 301 页 <a class="header-anchor" href="#page-301" aria-label="Permalink to &quot;第 301 页 {#page-301}&quot;">​</a></h2><p>301 问： 老师，可以说说业力是如何运作的吗？ 风： 业力就是程序，程序会创造你的每一个想法，你 的思想并不是自由的，因此行动也不是自由的。 问： 老师，请继续讲业力。 风： 业力就是程序，行动与反应。 问： 它是如何运作的？ 风： 程序驱动思想，思想投射世界，就是这样运作的。 世界只是个显示屏，你在世界中做任何事都是在砸显示屏， 改变不了里面播放的任何剧情。 问： 所以直接释放程序就可以改变世界？ 风： 是的，应该说，只有释放程序能够改变世界，否 则世界就会按照既定程序来表现。在程序中，你没有自由 意志，除非你下决定释放程序。所以之前你们无论想整什 ∞附录四：对你创造的整个世界完全负责，对 它保持有意识，你就能有意识创造自己想要的 2021.3.14</p><hr><h2 id="page-302" tabindex="-1">第 302 页 <a class="header-anchor" href="#page-302" aria-label="Permalink to &quot;第 302 页 {#page-302}&quot;">​</a></h2><p>302 么活，我都会说，释放去吧，整活是没用的，只是被程序 驱动而已，重复过去的业力，仅此而已。 问： 我可以通过释放改变我家人的世界吗？比如我想 通过释放治愈妈妈的疾病（即使这个疾病是她自己预设 的）。 风： 可以。 问： 也就是说，我可以通过释放来改变别人的业力？ 风： 你没有改变别人的业力。 问： 这样不是干预别人的生命吗？ 风： 这是宇宙的和谐运作。你现在根本谈不上干涉业 力，这是对自由的人说的。因为自由的人可以做到所有事， 可以超越一切业力的束缚。你现在正处于业力驱动中，你 的所有欲望都是业力的一部分，因此你影响你的都是自己 的业力而已，包括你母亲生病，那是你的业力。 问： 我的业力？ 风： 你谈不上干涉别人的业力，干涉是个大词。 问： 这是她的生命，为什么是我的业力？ 风： 你没办法在解脱之前干涉别人，没有一个分离， 她是你的一个画面。</p><hr><h2 id="page-303" tabindex="-1">第 303 页 <a class="header-anchor" href="#page-303" aria-label="Permalink to &quot;第 303 页 {#page-303}&quot;">​</a></h2><p>303 问： 她在来之前预设自己的生命，也就是业力，导致 了疾病，这也是我的业力？ 风： 她只是你的一个画面。 问： 天啊。就是说，我可以通过释放掌握我看到的整个 世界？ 风： 莱斯特说过很多回。不要像刚听到那样一惊一乍。 （笑） 答： 哈哈哈哈，这个确实刷新了我的认知。 （风下面引用了《彻底自由的最后一步》中莱斯特与 他人的一段对话，为了帮大家更好理解，我放上更完整的 中英文对照部分。） Q：if we see that the other one needs help is it just us that needs it? 问：如果我们看到另一个人需要帮助，是不是只是我 们需要帮助？ Lester: You can help the other one to help himself. If you do things for the other one, you cripple the other one. But we can help others to help themselves. 莱斯特：你可以帮助另一个人帮助他自己。如果你为</p><hr><h2 id="page-304" tabindex="-1">第 304 页 <a class="header-anchor" href="#page-304" aria-label="Permalink to &quot;第 304 页 {#page-304}&quot;">​</a></h2><p>304 另一个人做事，就会削弱另一个人。但是我们可以帮助别 人来帮助自己。 Q：Mainly by our change of attitude? 问：主要靠我们态度的转变？ Lester: That&#39;s part of it; just changing your attitude toward the other one helps the other one. The more we see the perfection of the other one, the more we&#39;re supporting the other one toward that perfection. You change your attitude and the other one will change; watch it. 莱斯特：这是一部分，只要改变你对另一个人的态度 就能帮助他。我们越是看到另一个人的完美，我们就越是 在支持他走向那个完美。你改变你的态度，另一个人就会 改变。看着吧。 Q：To change my attitude, do you mean my basic understanding that he&#39;s part of my consciousness and there&#39;s nothing but perfect consciousness and not think of him as an individual limited? 问：去改变我的态度，你的意思是说，他是我意识的 一部分，除了完美的意识之外别无他物，而不是把他当成 一个有限的个体？ Lester: Yes. That&#39;s an excellent way to do it. It works,</p><hr><h2 id="page-305" tabindex="-1">第 305 页 <a class="header-anchor" href="#page-305" aria-label="Permalink to &quot;第 305 页 {#page-305}&quot;">​</a></h2><p>305 doesn&#39;t it? 莱斯特：是的，这是个很好的方法。它很有效，不是吗？ Q：It works perfectly, yes. It works instantly. 学生：它完全有效，是的，它马上起效。 Lester: People will actually fit our consciousness of them. 莱斯特：人们实际上会成为我们意识中的他们。（人 们会符合我们的意识，我们怎么看他们，他们就会变成什 么样。） Q: Then, if Lillian tells me she wants a bigger house, I&#39;ve got to clear my own consciousness to let her fulfill my desires. Because it&#39;s only in my thoughts that I have her considered, isn&#39;t that right? I don&#39;t have to consider Lillian; it&#39;s only me that I have to consider, my own happiness, then she is happy. That is, my own happiness would be to go to the ultimate happiness— 学生：那么，如果莉莲告诉我她想要一个更大的房子， 我得要清除我自己想让她满足我愿望的意识。因为只是我 的念头让她想到了，不是吗？ 我不必考虑莉莲，我所要考虑的只是我，我自己的幸</p><hr><h2 id="page-306" tabindex="-1">第 306 页 <a class="header-anchor" href="#page-306" aria-label="Permalink to &quot;第 306 页 {#page-306}&quot;">​</a></h2><p>306 福，那么她就会幸福。也就是说，我自己的幸福将是走向 终极的幸福…… Lester: But you gotta separation: Lil and me. 莱斯特：但你有一个分离：莉莲和我。 Q：I always had this problem, you know, since I&#39;ve known you. 学生：我一直有这个问题，你知道的，自从我认识你 以来。 Lester: You didn&#39;t have it at times; you would say, &quot;Who is Lillian but my consciousness?&quot; 莱斯特：有时候你没有，你会说：“除了我的意识， 莉莲是谁?” Q：Yes. I say that. I just said it a few minutes ago: I&#39;ve only got to deal with my own consciousness. 学生：是的，我说了。我几分钟前刚刚说过:我只需 要处理我自己的意识。 Lester: O.K. That includes Lillian. right? 莱斯特：好的，那也包括莉莲，是吧？</p><hr><h2 id="page-307" tabindex="-1">第 307 页 <a class="header-anchor" href="#page-307" aria-label="Permalink to &quot;第 307 页 {#page-307}&quot;">​</a></h2><p>307 Q: Yes, that&#39;s right. 学生：对，是这样。 Q: That includes a bigger house, too. (Laughter.) 学生：这也包括一个更大的房子。(笑声) Q: I&#39;11 have to get rid of a limitation within my own consciousness.That&#39;s all I&#39;m dealing with anyway: I&#39;m not dealing with Lillian or houses or land, I&#39;m dealing with my own consciousness. The blocks are within myself or the unlimitedness is within myself. And, as you said: If I&#39;m an infinite Being now, I can do it now! I won&#39;t have to wait until I get home. 学生：我必须摆脱自己意识中的限制。这就是我所面 对的一切:我不是在和莉莲打交道，也不是在和房子或土 地打交道，我是在和我自己的意识打交道。障碍在我自己 内在，无限在我自己内在。而且，正如你所说:如果我现 在就是无限的存在，我现在就能做到!我不需要等到回家。 Lester: Right. 莱斯特：对。 Q: We&#39;re going to the moving quick! 学生：我们要赶快行动！</p><hr><h2 id="page-308" tabindex="-1">第 308 页 <a class="header-anchor" href="#page-308" aria-label="Permalink to &quot;第 308 页 {#page-308}&quot;">​</a></h2><p>308 Q: By the time you get home, Lil, you&#39;re going to be happy with your house. as is. 学生：当你回到家的时候，小莉，你会对你的房子感 到满意。 Lester: If you accepted it, that same house could be twice the size,when you went home. It would be so natural you wouldn&#39;t even notice it. You&#39;d just move into a home twice the size that you left. 莱斯特：如果你接受了，当你回家的时候，同样一个 房子可以变成两倍大。它会是那样的自然，你甚至不会注 意到。你只是进入了一个比你离开时大两倍的房子。 问： 这就是说，我妈妈生病，亲人负债，等等等都是我 的业力。 风： 业力就是你的欲望。程序，就是感受，就是欲望驱 动的。 负起全责的意思是，你对你创造的整个世界完全负责， 包括太阳升起，灰尘的走向，原子的震动，都是你创造的。 只是你对此没有意识，对它保持有意识，你就能有意识创造 自己想要的，而非不想要的。</p><hr><h2 id="page-309" tabindex="-1">第 309 页 <a class="header-anchor" href="#page-309" aria-label="Permalink to &quot;第 309 页 {#page-309}&quot;">​</a></h2><p>309 问： 老师，我都可以通过释放去帮助他们治愈吗？即使 瘫痪几年呢？ 风： 我其实回答过很多次这类问题。关于&quot;能不能做 到xxx&quot;这一类的问题，我希望你们能记住莱斯特的一句 话： every impossible, no matter how impossible, become immediately a possible ,as you completely released on it. （每一个不可能，不管多么不可能，都会立即变成可能， 只要你在它上面完全释放。） 问： 老师，你这里说宇宙的和谐运作，具体什么意思？ 比如，我通过释放治愈家人，这是宇宙的和谐运作？ 风： 你产生想法的同时，她也会产生相应的想法，分毫 不差。因此你并不需要通过语言和行动去让她改变想法，你 只需要处理自己的思想就行，世界就会改变。 说到底，除了释放什么都不用做。release only。 答： 好。</p><hr><h2 id="page-310" tabindex="-1">第 310 页 <a class="header-anchor" href="#page-310" aria-label="Permalink to &quot;第 310 页 {#page-310}&quot;">​</a></h2><p>310 问： 莱斯特在离开世界后直接融入了无限？ 风： 这个我很早之前就告诉过你。 问： 后来我听你说，莱斯特在离开后，有很多弟子见过他。 风： 仅仅是以某种形式。 问： 你也说过，融入无限后不会以任何形象出现。 风: 融入无限存在不是消失，而是没有形式地存在。 问： Ralf说莱斯特离开后第二天，来找过他。莱斯特是 用什么样的形式找他的？ 风:在梦中。你可以以任何形式见到莱斯特，莱斯特不 再作为一具身体，莱斯特现在就在每一个人身边，以无限存 在的“形式”。 如果你想要看见星光体形式的莱斯特，那你就会以星光 体形式看到他。如果你想要看到肉体形式的莱斯特，你就会 看到肉体形式的莱斯特。这取决于你的接受度。 但他在所有地方，每一个点，没有任何一个地方是他此 刻不存在的。融入无限后，不会再以任何形象出现。 ∞附录五：你每一次释放会帮助到所有人</p><hr><h2 id="page-311" tabindex="-1">第 311 页 <a class="header-anchor" href="#page-311" aria-label="Permalink to &quot;第 311 页 {#page-311}&quot;">​</a></h2><p>311 问： 如果我有足够的接受程度，我还可能看到以肉体形 式的莱斯特？ 风： 嗯，这不是他的“出现”，他现在就在。只是你没 有投射他的肉体形式而已。并不是有一个“莱斯特”作为一 具肉体出现了，而是你试图和一个“莱斯特”的肉体交流。 如果全世界有很多人同时投射莱斯特的肉体，那么他们 会同时看到莱斯特的肉体，但那并不是莱斯特降下来了，而 是处在无限存在中的全能的作用。 问： 莱斯特融入无限后，不再成为一具身体，而是成为 以“无限存在”的形式存在，但若是我想看到一位以肉体或 星光体形式的莱斯特（我可以接受的话），我一样可以看到 肉体形式的莱斯特，是这样吗？ 风： 是的。耶稣和佛陀，都可以。莱斯特也和学生说过 你可以和耶稣一起喝咖啡。 问： 融入无限，不再成为一具身体（肉体，星光体，因 果体），不再轮回。一位悉达是以“无限存在”的形式一直 存在于宇宙每一个点上，继续帮助他人？ 风： 嗯。 问： 一位悉达，还会继续帮助他人获得自由？只是以无 限存在的形式，而不是一具身体。</p><hr><h2 id="page-312" tabindex="-1">第 312 页 <a class="header-anchor" href="#page-312" aria-label="Permalink to &quot;第 312 页 {#page-312}&quot;">​</a></h2><p>312 风： 会无意识地投射所有人，帮助别人获得自由。其实 悉达的帮助是最大的，那是无限存在的层面，只是你的心智 理解不了，因此觉得那些语言文字的教导帮助更大，实际上 那些无形的帮助才是最大的。 问： 悉达帮助的范围是所有生命所有存在，而一位吉万 穆克塔只是帮助少数的人？ 风： 吉万穆克塔也帮助所有生命，大师们都在无意识投 射所有生命，哪怕是你待在山洞里，但是吉万穆克塔的助人 游戏还未玩完，还保留了一些限制。悉达是完美的存在。 问： 吉万穆克塔也帮助所有生命，这里说的吉万穆克塔 是具体哪个阶段？ 风： 初果到四果。 问： 预流圣人也可以帮助所有生命？ 风： 嗯。不仅仅是预流圣人，你每释放一次，就是在帮 助所有生命。世界只是心智的投射而已。 问： 是如何帮助的？比如我到达了涅比卡帕三摩地，但 我妈妈不学习也不修行，也可以帮助她吗？ 风： 那比你做分享帮助大很多。人们不知道业力是如何 运作的，释放会让你更加无私，只要你有无私的意识，你的 心智会投射更完美的世界。它是真正的帮助。</p><hr><h2 id="page-313" tabindex="-1">第 313 页 <a class="header-anchor" href="#page-313" aria-label="Permalink to &quot;第 313 页 {#page-313}&quot;">​</a></h2><p>313 但在agflap状态下，所谓的助人只是满足自我，滋长 自我本身并不会产生多大的帮助。只要你自由了，哪怕是在 山洞里什么也不做，也比所有的行动家加起来帮助大。 问： 我每一次释放，当然帮助了我的世界，也可以帮助 到我妈妈的世界？ 风： 是的，你每一次释放会帮助到所有人。 问： 我每一次释放，都会帮助到所有人的世界。所有人 就是所有人？ 风： 所有人就是所有人。</p><hr><h2 id="page-314" tabindex="-1">第 314 页 <a class="header-anchor" href="#page-314" aria-label="Permalink to &quot;第 314 页 {#page-314}&quot;">​</a></h2><p>314 倚天： “想要”在最表层，这是我今早的伟大发现。 我是无限： 这是一个突破，有了这个突破，你可以越来 越觉察到想要，然后就可以尝试去释放。 风： 突破二人组。（笑） 倚天： 好不容易有一点突破，被你们好一通羞辱。 风： 不用突破啊。直接用。你看，每次突破，你都要用 心智总结一下吧，总结出来都是概念性的东西吧。只不过用 语言转化了一个概念，就想获得体验？ 倚天： 弄不好我今天下午就突破了。 风： 你下一秒钟就可以突破，别拖。 不是头脑理解了一个东西叫突破，是能够体验释放了叫 突破，能够持续体验释放更是一个突破。头脑理解了什么， 那是假突破。这里面有一个误区，我来说一下。 往往人们用方法，没有达到预期的效果，就开始寻找解 决之道。就像开车开不好时会去想，是不是有什么别的诀窍。 行为上就是问这个，问那个，逮到一个释放好的就问。听到 ∞附录六：一有所悟，便走歪路 2021.1.3</p><hr><h2 id="page-315" tabindex="-1">第 315 页 <a class="header-anchor" href="#page-315" aria-label="Permalink to &quot;第 315 页 {#page-315}&quot;">​</a></h2><p>315 一个观点，试了试感觉有用，接着恍然大悟。这个方向是不 对的。 因为，比如你现在过于紧张，别人要你放松，你一放松， 发现能释放了，于是就把放松定义为诀窍。 接着又卡住了，别人叫你允许，一允许，发现成功了， 于是把允许定义为诀窍。 心里面积累的&quot;诀窍&quot;越来越多，释放也就越来越艰难， 因为你时时刻刻去注意那些。 真正的诀窍，是保持简单。回到最简单的释放流程中。 问那些释放好的人是没有用的，因为他们并不能总结自 己成功释放的原因。很多人虽然能释放，但总结的经验是头 脑的想象，是错的。就像你问马云为什么能挣钱一样，其实 他自己也不清楚。 其实很简单，如果释放有那些诀窍和原理，为什么莱斯 特不和你们讲呢？ 释放法的体验是，你越释放，要注意的东西越来越少， 越来越简单。 就像骑自行车一样，学会了之后你上去骑就行了，不用 考虑怎么骑。不用考虑先跨左脚还是右脚，这是通过大量释 放来达到，不是通过一种理智上的理解。</p><hr><h2 id="page-316" tabindex="-1">第 316 页 <a class="header-anchor" href="#page-316" aria-label="Permalink to &quot;第 316 页 {#page-316}&quot;">​</a></h2><p>316 （风接下来引用了一段莱斯特在the way part3中的讲 话） 莱斯特：当我试着把一个体验解释给你们，就像尝试去 告诉你们如何驾驶飞机，甚至开一辆车。我说仅仅是把钥匙 插进去，换到驾驶挡，踩油门，然后你就出发了。 当你想往右边开你就把方向盘转到右边，往左边开就转 到左边，你们能学会开车吗？你知道了开车需要知道的所有 的事情，你能开车吗？不，你需要体验。 在开飞机上就更是如此了，我告诉你们怎么开飞机，你 飞上去，快速地降下来。体验，是把你投到自行车上。我可 以告诉你的头脑怎样骑自行车，但你不会知道如何去做，直 到你体验到它。 当你体验到它时，你无法从理智上转移一个经验给另一 个人，他们必须自己来体验。所以这是体验和智性理解的明 显区别。 智性理解不会给你体验的能力，它可以引导你走向体验， 但是它不会给你一个体验。因为体验不在头脑中，思考不是 体验。 风： 像学习骑自行车一样，直接去操作，摔几次就学会了。</p><hr><h2 id="page-317" tabindex="-1">第 317 页 <a class="header-anchor" href="#page-317" aria-label="Permalink to &quot;第 317 页 {#page-317}&quot;">​</a></h2><p>317 莱斯特：但你们可以看到，我们的方法实际上是去释放 心智的驱动。不要试图发展你的心智，这样你是在发展你的 敌人，发展束缚住你的东西。 风： 当你对释放法的&quot;智性理解&quot;越来越多，你就知道 道路错了。释放得越好，越没有智性理解。 你知道那是感受，你知道可以释放，你知道释放是什么， 你知道释放之后心智安静，那些体验你都有。 莱斯特:是的，你释放你对世界的贪爱和嗔恨，一小口 一小口。但你需要来一大口，而不是这样一小口一小口。 所以你运用你正在做的事去释放。要明白，你唯一需要 的努力就是去摆脱你的努力。这就是你就在世界中做的，你 运用你的努力去摆脱你的努力，但是在你的存在中不需要任 何努力，事物会立即物质化和反物质化。 然而，你尝试用头脑去搞明白。你做不到的，因为你的 头脑、你的智力是障碍，是限制性概念的累积。所以你无法 在你的头脑中搞明白，你可以成为你的存在，你现在就是你 的存在了。 你并不必须要成为一个限制性的车架子，而这是你在工 作和日常中要释放的。你释放所有的贪爱和嗔恨，摆脱所有 和你关联的情绪。我回答了你的问题吗？</p><hr><h2 id="page-318" tabindex="-1">第 318 页 <a class="header-anchor" href="#page-318" aria-label="Permalink to &quot;第 318 页 {#page-318}&quot;">​</a></h2><p>318 学生:是的，我想我没有试着去搞清楚它，但我可以说， 我能跳过一部分。你回答了我的问题。 莱斯特:你无法搞清楚。 风： 注意:你无法搞清楚。正确的努力还是要有的。其 实保持简单地去做还是很重要的。我来说一下我当时也有过 的惯性，以前当我体验到释放时，下意识会去总结，千万别 总结，一个心智的总结会让你走偏很久。 释放得很好，你就继续释放，一悟你就歪。 以前一个人和我说的话: 一有所悟，便走歪路。这句话 对我后来释放帮助很深。 记录收获，不要记录心智对方法的理解，因为那些理解 真的都是限制性的。方法那一页只需要放上六步骤。 我持续释放达到三摩地之后，再看以前的奇葩理解，觉 得自己很蠢。 我很早就发现交流帮助不到我，交流就是大家说自己的 问题，然后互相认同各自的限制性观念，所以大部分交流是 无益的。 修行人之间的交流，就是彼此发自己的心智理解，互相 误导。</p><hr><h2 id="page-319" tabindex="-1">第 319 页 <a class="header-anchor" href="#page-319" aria-label="Permalink to &quot;第 319 页 {#page-319}&quot;">​</a></h2><p>319 把方法发过去就行了，把大师的教导直接发过去就行了。 以前我有一个南传的群组比较好，内观群。平时大家安 安静静，没事发一段经文，不加自己的注解。 后来进来的人多了，开始讨论经验了，群就没用了。心 智加工过后的经验帮助不到人，只会误导人。</p><hr><h2 id="page-320" tabindex="-1">第 320 页 <a class="header-anchor" href="#page-320" aria-label="Permalink to &quot;第 320 页 {#page-320}&quot;">​</a></h2><p>320 天成： 过去你说过女大师比男大师多，是这样吗？ 风： 相差并不多，且大师没有男女。 天成： 因为很少会看到女大师，好像以为女性很难开悟。 风： 女大师在社会中没有男性大师的接受度，因此会选 择隐居而已。等到人们的集体意识中男女平等之后，就会有 女大师出来。 天成： 其实是不是女性比男性更容易开悟？因为女性更 感性一些。 风： 男性与女性各有优势。女性的优势在起初，因为她 们是以感觉来运作的。男性是优势在于智性中心活跃，因此 走到终点的意志力更强。 天成： 智性中心，什么东西？ 风： 眉心。 ∞附录七 男性与女性在释放中各有优势，平衡特性后， 才能到达终点 2021.1.3</p><hr><h2 id="page-321" tabindex="-1">第 321 页 <a class="header-anchor" href="#page-321" aria-label="Permalink to &quot;第 321 页 {#page-321}&quot;">​</a></h2><p>321 天成： 第三眼？ 风： 嗯。男性通常找到答案的意愿更强，女性时常会止 步在快乐中。 天成： 那女性凭什么优势走到终点？ 风： 但是大部分男性连起步都没有，只是在脑内活动。 女性走得更快，只是会容易停在快乐里面。克服了这一点， 平衡了特性，就会达到终点。 男性克服自己思维的惯性，克服自己的性欲，也是一种 平衡特性。 两性各有优势，但最终你需要平衡。 天成： 当今世界上的30位大师，有多少位女大师呢？ 风： 这个我不会说。而且也没有意义，因为我明天造一 具女性身体，我就是女性大师，身体只是可以转化的图像。</p><hr><h2 id="page-322" tabindex="-1">第 322 页 <a class="header-anchor" href="#page-322" aria-label="Permalink to &quot;第 322 页 {#page-322}&quot;">​</a></h2><p>322 ∞附录八 风：让我们携手把原始释放流程纯正地展现在 所有人面前 【2020.10.21在不强迫的情况下传播原始释放法，但不要用 之收钱 】 风： 我花了四年时间在找资料上，同时也在释放。后来 出国接触到莱斯特后期音频和92年的课程，才明白一个简洁、 完整的地图。它非常清晰、简洁、有力，是走向自由的完整 地图。 尤其是莱斯特后期音频对释放法的讲解，学会释放流程 之后，大家可以重点看the way系列，那是莱斯特的直接教导， 会理清楚很多问题，同时也会获得极大的鼓舞。 大家可以在不强迫的情况下尽量传播原始释放，但不要 用之收任何一分钱。</p><hr><h2 id="page-323" tabindex="-1">第 323 页 <a class="header-anchor" href="#page-323" aria-label="Permalink to &quot;第 323 页 {#page-323}&quot;">​</a></h2><p>323 【2020.10.23只有保持免费传播，才能保持释放法的纯正 】 风： 今天我引导那位群友，因为她没有体验过释放情绪， 所以我也是从释放情绪的三问句开始，然后再让她走得深一 步。如果没有体验过释放情绪的人，按照课程顺序来，也会 学的很快。 莱斯特提到，如果你没有那么想要自由，你会被这个世 界拉扯回来，而成功不了的唯一原因就是没那么想要。 所以，即便有了方法，我依然不认为大部分人可以自由， 但是至少把工具提供给人们，让需要帮助的人受到帮助。 但是我在释放的过程中产生了一个强烈的直觉，任何收 费，都会损害这个原始方法的呈现。所以，我希望大家在传 播这个方法的时候不要用它来收一分钱。 最重要的是，必须先自己做到，才能教会别人。如果你 自己做不到丰盛，做不到通过释放获得想要的一切，那么你 也教不会别人。你必然会修改、添加一些限制性的观念在其中。 如果你无法仅仅通过释放来运作一个机构，而是通过收 费，你就无法保持纯正。</p><hr><h2 id="page-324" tabindex="-1">第 324 页 <a class="header-anchor" href="#page-324" aria-label="Permalink to &quot;第 324 页 {#page-324}&quot;">​</a></h2><p>324 【2020.10.30 风：我希望释放法保持免费的传播 】 网友： 你对这个收费的分享，怎么看的？ 风： 我个人的希望是能保持免费的传播，不过那在于你。 因为这些东西，是很多人的无私奉献把它还原的，我只是做 了其中一些工作。 我希望它保持免费的原因有两个：一个是现今的释放法 机构已经够多了，而它们都不是关于觉醒的。我看到免费是 能保证它纯正性的一种方式。第二个原因就是对于你自己而 言，收费实际上会阻碍你的成长。我的观点是这样，但它们 没有强迫性，你依然可以选择做自己想要做的。（笑） 最后，持续释放吧，贯彻六步骤。 网友： 实际上莱斯特在世时教导的课程是收费的还是免 费的？ 风： 他一开始是免费的，后来没有什么人来听，听了也 没有去用，后来进行了收费。 网友： 嗯。</p><hr><h2 id="page-325" tabindex="-1">第 325 页 <a class="header-anchor" href="#page-325" aria-label="Permalink to &quot;第 325 页 {#page-325}&quot;">​</a></h2><p>325 网友： 我现在不想用释放法赚钱啦,我会用它达到自 由。之前我是有想通过释放法教学赚钱的想法的。后来我想， Get everything by releasing only，那我可以通过释放 直接获得金钱呀，干嘛要这么累呢？ 风： 用释放法来释放，可以获得更多的钱，也可以挣到 比钱好无数倍的东西。是啊，为什么要尝试挣扎的方式呢。 （笑） 网友： 对。 风： 直接去释放是聪明人的做法。 网友： 所以我现在有点感觉不太想分享释放法了。我就 想直接释放，去做到自由。但如果有人想要学的话，我感觉 我也会分享，尽我的能力。 风： 嗯，尽量还是以自己释放为主。在无畏之前，分享 是带有想要控制和认同的。 网友： 是的，我明显感觉到。 ∞附录九 在自己提升之后，勿忘帮助他人，以促进自己 进一步地释放 2020.11.26</p><hr><h2 id="page-326" tabindex="-1">第 326 页 <a class="header-anchor" href="#page-326" aria-label="Permalink to &quot;第 326 页 {#page-326}&quot;">​</a></h2><p>326 风： 无畏是50%自私，50%无私。在之后，你就可以决定 帮助他人，这样会促进自己的释放。如果那个时候你还是盯 着自己的自我意识，就会停止释放，这些莱斯特的视频里都 讲过。但在目前，应该以自己释放为主。 网友： 盯着自己的自我意识，是什么意思？ （风发了庆祝莱斯特100周年视频3&amp;4中的一段讲解， 文字内容如下） 莱斯特：你越自由就越想给予，你必须开始给予，你应 该想去帮助任何人，实际上你把这个作为你生活的意义，你 就开始往这条路上走了。 你一定要成为“耶稣基督”，如果他在这里，他会干嘛？ 开个公司，搞个宗教产业，赚点钱？他唯一的兴趣就是帮助 别人。 我觉得我们大多数完成课程的人，都体会到让世界变成 个好世界，然后他们就开始享受他们的生活了。 问问麦克（使用释放法的学生），他会告诉你，麦克就 停下来了。当他在上面的时候（指进入释放的高峰），拥有 了那些东西，然后他发现需要一直释放。记得你跟我说过吧， 但是你停下来了，你已经到了高峰，你只需要继续，你就会 到那个你能瞬间用意念创造东西的地方。</p><hr><h2 id="page-327" tabindex="-1">第 327 页 <a class="header-anchor" href="#page-327" aria-label="Permalink to &quot;第 327 页 {#page-327}&quot;">​</a></h2><p>327 之前刚遇见麦克的时候，买几杯咖啡都困难，有一 段时间满脑都是负面思想，突然有一天开始设定目标了 （莱斯特讲述麦克经历的转变，出演了某个电影），他下 一个目标，设定了6位数的目标，然后他简单、漂亮地 达成了。 然后他就开始走极端了，买房子，买跑车，等等…… 他其实有答案：需要持续（释放）。后来重聚的时候我说， 麦克你是不是要开始帮助别人了？这样你可以更进一步。 他说，不要，然后他就卡住了。 他有他创造的物质的游乐园，但你是不可能在里面持续 待的，你不是向上就是向下。这就是麦克自己给自己上的一课， 不能停下，（应该）持续释放。 麦克如果你继续，你不会是这个状态，我的意思是（你 能到达）那个可以非物质化（分解）身体，然后又物质化（重塑） 身体的状态，瞬间创造任何东西，只用一个无需费力的念头。 一曼注：莱斯特曾经在《Goals and winning》(你必须 赢得目标)中也与麦克对话过，提醒他不该停下释放。 之前麦克曾经为出演百老汇电影的一个重要角色而释放， 后来他又制定了去好莱坞拍电影的目标，得到六位数存款的 目标。在他达到这些目标后，他开始沉迷于名声和物质，停</p><hr><h2 id="page-328" tabindex="-1">第 328 页 <a class="header-anchor" href="#page-328" aria-label="Permalink to &quot;第 328 页 {#page-328}&quot;">​</a></h2><p>328 止了释放。莱斯特说那时候他释放得比其他毕业生要好，本 应该继续释放，大步向前，但麦克却停下释放了。 莱斯特对麦克说：“不管怎样，你停下了，就是这样。 看一下六步骤，六步骤里没有停下。什么也不要让其停下， 你只需要一直保持前进。在与我交谈完的那段时间之后，你 完全可以在一个月左右的时间内完全自由，但是你停下来了。 你当时想要这世上的一切，却忘记了内在的幸福是如此美妙， 而不是这世上的事物。” 在麦克的事例中，有两个非常重要的点： 第一，无论释放达到什么样的好状态，只要没有到终点， 不要停下，因为不进则退。 第二，在自己得到提升之后，也不要忘记帮助他人。在《终 极自由之路》这本书中，莱斯特也讲到：“随着意识的扩展， 我们的爱也会自动增加。通过帮助他人，我们帮助自己实现 目标，让自己获得进一步的成长。我们只有有爱的态度，有 慈悲心，与每个人合一，希望他人知道我们所知道的，才能 走向开悟。” 在《与尤迦南达的对话》这本书当中也提到：他（指尤 迦南达）曾经告诉我一个灵魂必须令另外六个灵魂解脱才能 得到解脱。我（指沃尔特）想，神不希望我们寻找他只是为 了自己，神也不希望我们还没有帮助他人就与无限融合。</p><hr><h2 id="page-329" tabindex="-1">第 329 页 <a class="header-anchor" href="#page-329" aria-label="Permalink to &quot;第 329 页 {#page-329}&quot;">​</a></h2><p>329 助人即是助己。风曾经也遇到与麦克类似的情况，他在 帮助其他人的过程中达到了自助，获得了释放上的突破： 风：我两年前曾经持续释放过一次，一个星期。当时， 心智内的agflap清空得差不多了，接着处在一个非常舒 适的状态，身边的世界也展现前所未有的和谐。 接着，整整半年一次释放也没有做，接着那些agflap 就回来了，我甚至忘记了怎么释放情绪和欲望，持续地卡 住，所以才进群交流。 后来我发现群里的人似乎不知道莱斯特后期音频和原 始版本的释放法的存在，于是就翻译了 the way 和92课 程的两篇。 在翻译的过程中，我自己也温习了一遍，记起了其中 的要点。于是我又开始持续释放，记着上次的教训，就一 次往前走了。 在你到终点前，一定不要停下来。 因为一旦你不在前进，就在后退。 开始分享之后，不知道为什么，我释放也变多了。每 次我翻译完或者分享完，就有更多的动力去释放，这是真 的体验到莱斯特说的，帮助他人就是帮助自己。</p><hr><h2 id="page-330" tabindex="-1">第 330 页 <a class="header-anchor" href="#page-330" aria-label="Permalink to &quot;第 330 页 {#page-330}&quot;">​</a></h2><p>330 通过帮助他人，我们帮助自己 莱斯特：不必刻意寻找需要帮助的人，他们自会进 入我们的生活。帮助这些真诚地想要获得指引的人，是 一种义务。记住，你就是我。 有趣的是，我们开始活得更加扩展，更少地考虑我 们的自我，转而更多地考虑他人，实际上我们这是在帮 助自己。 但世人却并不这么认为，他们可能会将其解读为我 们是在帮助他人。但除了自己，没有人需要帮助，我们 自己才是最大的受益者。通过帮助他人，我们帮助自己 实现目标。 帮助那些需要帮助的人，让他人也更幸福，这并不 意味着放弃自身的成长，我们绝不能停止成长。通过帮 助他人，让自己获得进一步的成长。 我们能为他人所做的最好事情是帮助他们自助。 当你纠正了自己时才能帮助他人。我再说一次，如 果不能自助，就不要助人。但是要试着帮助他人，因为 那会帮助你自助。 ——《终极自由之路》第十九章 如何助人</p><hr><h2 id="page-331" tabindex="-1">第 331 页 <a class="header-anchor" href="#page-331" aria-label="Permalink to &quot;第 331 页 {#page-331}&quot;">​</a></h2><p>331</p><hr><h2 id="page-332" tabindex="-1">第 332 页 <a class="header-anchor" href="#page-332" aria-label="Permalink to &quot;第 332 页 {#page-332}&quot;">​</a></h2><p>332</p><hr><h2 id="page-333" tabindex="-1">第 333 页 <a class="header-anchor" href="#page-333" aria-label="Permalink to &quot;第 333 页 {#page-333}&quot;">​</a></h2><p>333</p><hr><h2 id="page-334" tabindex="-1">第 334 页 <a class="header-anchor" href="#page-334" aria-label="Permalink to &quot;第 334 页 {#page-334}&quot;">​</a></h2><p>334</p><hr><h2 id="page-335" tabindex="-1">第 335 页 <a class="header-anchor" href="#page-335" aria-label="Permalink to &quot;第 335 页 {#page-335}&quot;">​</a></h2><p>335</p><hr><h2 id="page-336" tabindex="-1">第 336 页 <a class="header-anchor" href="#page-336" aria-label="Permalink to &quot;第 336 页 {#page-336}&quot;">​</a></h2><p>336 保持简单 贯彻六步骤 走向终点 ——风</p>',1009)])])}const c=e(o,[["render",p]]);export{u as __pageData,c as default};
